from collections import deque

BLOCKS = ("block1", "block2")
TABLE = "table"
HELD = "held"
START_HOLDING = "block2"


def make_state(locations, holding):
    return (tuple(locations[b] for b in BLOCKS), holding)


def is_clear(locations, block):
    return all(x != block for x in locations)


def successors(state):
    locations, holding = state
    loc = dict(zip(BLOCKS, locations))

    for b in BLOCKS:
        if holding is None and loc[b] == TABLE and is_clear(locations, b):
            nxt = loc.copy()
            nxt[b] = HELD
            yield ("pickup", (b,), make_state(nxt, b))

        if holding == b:
            nxt = loc.copy()
            nxt[b] = TABLE
            yield ("putdown", (b,), make_state(nxt, None))

        if holding is None and loc[b] not in (TABLE, HELD) and is_clear(locations, b):
            support = loc[b]
            if support in BLOCKS:
                nxt = loc.copy()
                nxt[b] = HELD
                yield ("unstack", (b, support), make_state(nxt, b))

        if holding == b:
            for c in BLOCKS:
                if c != b and loc[c] != HELD and is_clear(locations, c):
                    nxt = loc.copy()
                    nxt[b] = c
                    yield ("stack", (b, c), make_state(nxt, None))


def is_goal(state):
    locations, _ = state
    return all(x == TABLE for x in locations)


def main():
    initial_locations = {
        "block1": TABLE,
        "block2": "block1",
    }
    start = make_state(initial_locations, None)
    satisfied = start[1] == START_HOLDING

    parent = {start: (None, None)}
    queue = deque([(start, satisfied)])

    while queue:
        state, satisfied = queue.popleft()

        if is_goal(state) and satisfied:
            actions = []
            current = state
            while parent[current][0] is not None:
                previous, action = parent[current]
                actions.append(action)
                current = previous
            actions.reverse()

            lines = [
                "(" + " ".join([name] + list(args)) + ")"
                for name, args in actions
            ]
            print("\n".join(lines))
            return

        for name, args, nxt in successors(state):
            if not satisfied and nxt[1] != START_HOLDING:
                continue

            next_satisfied = satisfied or nxt[1] == START_HOLDING
            if nxt not in parent:
                parent[nxt] = (state, (name, args))
                queue.append((nxt, next_satisfied))

    print("No plan")


if __name__ == "__main__":
    main()

N = 14
TABLE = 0
HOLD = -1
FRAGILE = 1
BLOCKS = list(range(1, N + 1))


def block_name(b):
    return f"block{b}"


def initial_state():
    on = [TABLE] * (N + 1)
    on[13] = 12
    on[5] = 1
    on[3] = 10
    on[8] = 11
    on[14] = 8
    on[4] = 14
    on[9] = 4
    on[6] = 9
    on[2] = 6
    on[7] = 2
    return on


GOAL_STACKS = [
    [4, 1],
    [10, 12],
    [14],
    [3, 7, 11],
    [8, 5],
    [6],
    [2],
    [13],
    [9],
]


def goal_state():
    goal = [TABLE] * (N + 1)
    seen = set()
    for stack in GOAL_STACKS:
        for i, b in enumerate(stack):
            if b in seen:
                return None
            seen.add(b)
            goal[b] = TABLE if i == 0 else stack[i - 1]
    if len(seen) != N:
        return None
    return goal


def is_clear(on, b):
    for x in BLOCKS:
        if x != b and on[x] == b:
            return False
    return True


def fragile_bad(on):
    for x in BLOCKS:
        if x != FRAGILE and on[x] == FRAGILE:
            return True
    return False


def apply_action(on, held, action):
    a = action[0]

    if a == "pickup":
        b = action[1]
        if held != 0 or on[b] != TABLE or not is_clear(on, b):
            return None
        on = on[:]
        on[b] = HOLD
        return on, b

    if a == "putdown":
        b = action[1]
        if held != b:
            return None
        on = on[:]
        on[b] = TABLE
        return on, 0

    if a == "stack":
        b, c = action[1], action[2]
        if held != b or c == TABLE or c == HOLD or c == b:
            return None
        if on[c] == HOLD:
            return None
        if not is_clear(on, c):
            return None
        if c == FRAGILE:
            return None
        on = on[:]
        on[b] = c
        return on, 0

    if a == "unstack":
        b, c = action[1], action[2]
        if held != 0 or on[b] != c or c == TABLE or c == HOLD:
            return None
        if on[c] == HOLD:
            return None
        if not is_clear(on, b):
            return None
        on = on[:]
        on[b] = HOLD
        return on, b

    return None


def validate(plan, initial, goal):
    on = initial[:]
    held = 0

    for action in plan:
        result = apply_action(on, held, action)
        if result is None:
            return False
        on, held = result
        if fragile_bad(on):
            return False

    if held != 0:
        return False

    for b in BLOCKS:
        if on[b] != goal[b]:
            return False

    return not fragile_bad(on)


def construct_plan(initial):
    on = initial[:]
    plan = []

    # Clear all blocks to the table, removing the block on the fragile block first.
    while True:
        chosen = None

        for b in BLOCKS:
            if on[b] == FRAGILE and is_clear(on, b):
                chosen = b
                break

        if chosen is None:
            for b in BLOCKS:
                if on[b] != TABLE and on[b] != HOLD and is_clear(on, b):
                    chosen = b
                    break

        if chosen is None:
            break

        support = on[chosen]
        plan.append(("unstack", chosen, support))
        on[chosen] = HOLD
        plan.append(("putdown", chosen))
        on[chosen] = TABLE

    # Build the goal stacks from bottom to top.
    for stack in GOAL_STACKS:
        base = stack[0]
        if on[base] != TABLE or not is_clear(on, base):
            return None

        for i in range(1, len(stack)):
            b = stack[i]
            target = stack[i - 1]

            if on[b] != TABLE:
                if not is_clear(on, b):
                    return None
                support = on[b]
                plan.append(("unstack", b, support))
                on[b] = HOLD
                plan.append(("putdown", b))
                on[b] = TABLE

            if on[b] != TABLE or not is_clear(on, b):
                return None

            if on[target] == HOLD or not is_clear(on, target) or target == FRAGILE:
                return None

            plan.append(("pickup", b))
            on[b] = HOLD
            plan.append(("stack", b, target))
            on[b] = target

    return plan


def main():
    initial = initial_state()
    goal = goal_state()

    if goal is None:
        print("No plan")
        return

    plan = construct_plan(initial)

    if plan is None or not validate(plan, initial, goal):
        print("No plan")
        return

    for action in plan:
        if action[0] in ("pickup", "putdown"):
            print(f"({action[0]} {block_name(action[1])})")
        else:
            print(f"({action[0]} {block_name(action[1])} {block_name(action[2])})")


if __name__ == "__main__":
    main()

import sys

def main():
    blocks = list(range(1, 16))

    initial_stacks = [
        (4, 14, 8),
        (10,),
        (1,),
        (12,),
        (6, 7, 5),
        (3, 13, 15, 9),
        (11, 2),
    ]

    goal_stacks = [
        (13, 2),
        (9,),
        (1,),
        (11,),
        (7, 12),
        (14, 5, 8),
        (10,),
        (15,),
        (4, 6, 3),
    ]

    initial_on = {b: 0 for b in blocks}
    for st in initial_stacks:
        for i, b in enumerate(st):
            initial_on[b] = 0 if i == 0 else st[i - 1]

    goal_on = {b: 0 for b in blocks}
    for st in goal_stacks:
        for i, b in enumerate(st):
            goal_on[b] = 0 if i == 0 else st[i - 1]

    loc = initial_on.copy()
    arm = 0
    actions = []

    def is_clear(b):
        return all(loc[x] != b for x in blocks)

    def pickup(b):
        nonlocal arm
        if arm != 0 or loc[b] != 0 or not is_clear(b):
            return False
        arm = b
        loc[b] = -1
        actions.append(("pickup", b))
        return True

    def putdown(b):
        nonlocal arm
        if arm != b:
            return False
        loc[b] = 0
        arm = 0
        actions.append(("putdown", b))
        return True

    def unstack(b, c):
        nonlocal arm
        if arm != 0 or loc[b] != c or not is_clear(b):
            return False
        arm = b
        loc[b] = -1
        actions.append(("unstack", b, c))
        return True

    def stack(b, c):
        nonlocal arm
        if arm != b or b == c or loc[c] == -1 or not is_clear(c):
            return False
        loc[b] = c
        arm = 0
        actions.append(("stack", b, c))
        return True

    ok = True

    # Clear every non-block1 block down to the table.
    while True:
        b = None
        for x in blocks:
            if x == 1:
                continue
            if loc[x] != 0 and loc[x] != -1 and is_clear(x):
                b = x
                break
        if b is None:
            break
        c = loc[b]
        if not unstack(b, c) or not putdown(b):
            ok = False
            break

    if ok and loc[1] != 0:
        ok = False
    if ok:
        for x in blocks:
            if x != 1 and loc[x] != 0:
                ok = False
                break

    if ok:
        seen = []
        for st in goal_stacks:
            seen.extend(st)
        if sorted(seen) != blocks:
            ok = False
        else:
            for st in goal_stacks:
                for i in range(1, len(st)):
                    b = st[i]
                    c = st[i - 1]
                    if not pickup(b) or not stack(b, c):
                        ok = False
                        break
                if not ok:
                    break

    def valid_plan(plan):
        vloc = initial_on.copy()
        varm = 0
        debt = False

        def vclear(b):
            return all(vloc[x] != b for x in blocks)

        for a in plan:
            act = a[0]
            if act == "pickup":
                b = a[1]
                if varm != 0 or vloc[b] != 0 or not vclear(b):
                    return False
                varm = b
                vloc[b] = -1
            elif act == "putdown":
                b = a[1]
                if varm != b:
                    return False
                vloc[b] = 0
                varm = 0
            elif act == "unstack":
                b, c = a[1], a[2]
                if varm != 0 or vloc[b] != c or not vclear(b):
                    return False
                varm = b
                vloc[b] = -1
            elif act == "stack":
                b, c = a[1], a[2]
                if varm != b or b == c or vloc[c] == -1 or not vclear(c):
                    return False
                vloc[b] = c
                varm = 0
            else:
                return False

            moved = a[1]
            if moved == 1:
                debt = True
            if moved == 4:
                debt = False

        if varm != 0 or debt:
            return False
        return all(vloc[b] == goal_on[b] for b in blocks)

    if ok and valid_plan(actions):
        lines = []
        for a in actions:
            if len(a) == 2:
                lines.append(f"({a[0]} block{a[1]})")
            else:
                lines.append(f"({a[0]} block{a[1]} block{a[2]})")
        sys.stdout.write("\n".join(lines))
        if lines:
            sys.stdout.write("\n")
    else:
        sys.stdout.write("No plan\n")

if __name__ == "__main__":
    main()

import heapq

BLOCKS = tuple(range(1, 15))
TABLE = 0
HELD = -1
MAX_STACKS = 3


def initial_state():
    below = [TABLE] * 15

    below[7] = TABLE
    below[5] = TABLE
    below[1] = 5
    below[2] = 1

    below[13] = TABLE
    below[12] = 13

    below[14] = TABLE
    below[11] = 14

    below[3] = TABLE

    below[4] = TABLE
    below[10] = 4
    below[8] = 10
    below[6] = 8

    below[9] = TABLE

    return tuple(below), TABLE


def goal_state():
    below = [TABLE] * 15

    below[3] = TABLE
    below[10] = 3

    below[6] = TABLE
    below[8] = 6

    below[4] = TABLE

    below[7] = TABLE
    below[13] = 7

    below[5] = TABLE
    below[2] = 5
    below[12] = 2
    below[14] = 12
    below[9] = 14
    below[1] = 9
    below[11] = 1

    return tuple(below), TABLE


def above_map(below):
    above = [TABLE] * 15
    for b in BLOCKS:
        support = below[b]
        if support > TABLE:
            above[support] = b
    return above


def stack_count(below):
    return sum(1 for b in BLOCKS if below[b] == TABLE)


def constraint_ok(state, depth):
    if depth == 0:
        return True
    return stack_count(state[0]) <= MAX_STACKS


def neighbors(state):
    below, arm = state
    above = above_map(below)

    if arm == TABLE:
        for x in BLOCKS:
            if below[x] == TABLE and above[x] == TABLE:
                nb = list(below)
                nb[x] = HELD
                yield ("pickup", x), (tuple(nb), x)

        for x in BLOCKS:
            support = below[x]
            if support > TABLE and above[x] == TABLE:
                nb = list(below)
                nb[x] = HELD
                yield ("unstack", x, support), (tuple(nb), x)

    if arm != TABLE:
        nb = list(below)
        nb[arm] = TABLE
        yield ("putdown", arm), (tuple(nb), TABLE)

        for y in BLOCKS:
            if y != arm and below[y] != HELD and above[y] == TABLE:
                nb = list(below)
                nb[arm] = y
                yield ("stack", arm, y), (tuple(nb), TABLE)


def heuristic(state, goal_below):
    below, _ = state
    return sum(1 for b in BLOCKS if below[b] != goal_below[b])


def solve():
    start = initial_state()
    goal = goal_state()

    if start == goal:
        return []

    if not constraint_ok(goal, 1):
        return None

    goal_below = goal[0]
    counter = 0
    heap = [(heuristic(start, goal_below), 0, counter, start, ())]
    best = {start: 0}

    while heap:
        _, g, _, state, path = heapq.heappop(heap)

        if best.get(state) != g:
            continue

        if state == goal:
            return path

        for action, ns in neighbors(state):
            if not constraint_ok(ns, g + 1):
                continue

            ng = g + 1
            if ng < best.get(ns, float("inf")):
                best[ns] = ng
                counter += 1
                heapq.heappush(
                    heap,
                    (ng + heuristic(ns, goal_below), ng, counter, ns, path + (action,)),
                )

    return None


def format_action(action):
    if action[0] in ("pickup", "putdown"):
        return f"({action[0]} block{action[1]})"
    return f"({action[0]} block{action[1]} block{action[2]})"


def main():
    plan = solve()
    if plan is None:
        print("No plan")
    else:
        for action in plan:
            print(format_action(action))


if __name__ == "__main__":
    main()

import heapq


def main():
    # Variables:
    #   on[block] = support block, or None if on the table / held.
    #   held = block currently in the hand, or None.
    # Constraints:
    #   - one held block at most
    #   - a block can be picked up / unstacked only if clear
    #   - a block can be stacked / put down only when held
    # Goal:
    #   - held is None and every block is on the table.
    blocks = [f"block{i}" for i in range(1, 14)]
    idx = {b: i for i, b in enumerate(blocks)}

    # Initial tower from bottom to top.
    tower = [
        "block8", "block10", "block7", "block2", "block3", "block13",
        "block4", "block6", "block12", "block11", "block9", "block1", "block5"
    ]

    start_on = [None] * len(blocks)
    for lower, upper in zip(tower, tower[1:]):
        start_on[idx[upper]] = lower

    start = (tuple(start_on), None)

    def is_goal(state):
        on_vals, held = state
        return held is None and all(v is None for v in on_vals)

    def heuristic(state):
        # Admissible cost: held block needs 1 putdown,
        # block on another needs at least unstack + putdown.
        on_vals, held = state
        h = 0
        for b, v in zip(blocks, on_vals):
            if b == held:
                h += 1
            elif v is not None:
                h += 2
        return h

    def clear_set(on_vals, held):
        above = set()
        for v in on_vals:
            if v is not None:
                above.add(v)
        clear = set(blocks) - above
        if held is not None:
            clear.add(held)
        return clear

    def successors(state):
        on_vals, held = state
        clear = clear_set(on_vals, held)
        out = []

        if held is None:
            # unstack X Y
            for i, b in enumerate(blocks):
                support = on_vals[i]
                if support is not None and b in clear:
                    new_vals = list(on_vals)
                    new_vals[i] = None
                    out.append(((tuple(new_vals), b), f"(unstack {b} {support})"))

            # pickup X
            for i, b in enumerate(blocks):
                if on_vals[i] is None and b in clear:
                    out.append(((on_vals, b), f"(pickup {b})"))
        else:
            # putdown X
            out.append(((on_vals, None), f"(putdown {held})"))

            # stack X Y
            hi = idx[held]
            for i, b in enumerate(blocks):
                if b != held and b in clear:
                    new_vals = list(on_vals)
                    new_vals[hi] = b
                    out.append(((tuple(new_vals), None), f"(stack {held} {b})"))

        return out

    if is_goal(start):
        return

    h0 = heuristic(start)
    counter = 0
    heap = [(h0, h0, 0, counter, start)]
    g_score = {start: 0}
    parent = {start: (None, None)}
    INF = 10**9

    while heap:
        f, h, g, _, state = heapq.heappop(heap)

        if g != g_score.get(state):
            continue

        if is_goal(state):
            actions = []
            cur = state
            while parent[cur][0] is not None:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev
            actions.reverse()
            print("\n".join(actions))
            return

        for ns, action in successors(state):
            ng = g + 1
            if ng < g_score.get(ns, INF):
                g_score[ns] = ng
                parent[ns] = (state, action)
                nh = heuristic(ns)
                counter += 1
                heapq.heappush(heap, (ng + nh, nh, ng, counter, ns))

    print("No plan")


if __name__ == "__main__":
    main()

stacks = [
    [1],
    [3],
    [2],
    [10, 7, 13, 5],
    [9, 8, 4, 12, 11, 6],
]

blocks = [f"block{i}" for i in range(1, 14)]
support = {}

for stack in stacks:
    for i, n in enumerate(stack):
        b = f"block{n}"
        support[b] = "table" if i == 0 else f"block{stack[i - 1]}"

for b in blocks:
    support.setdefault(b, "table")

plan = []
holding = None

def is_clear(b):
    return all(s != b for s in support.values())

while True:
    if all(s == "table" for s in support.values()):
        break

    movable = None
    for b in blocks:
        if support[b] is not None and support[b] != "table" and is_clear(b):
            movable = b
            break

    if movable is None:
        plan = None
        break

    holding = movable
    plan.append(f"(unstack {movable} {support[movable]})")
    support[movable] = None
    plan.append(f"(putdown {movable})")
    support[movable] = "table"
    holding = None

if plan is None:
    print("No plan")
else:
    print("\n".join(plan))

import heapq
import itertools


def block_name(i):
    return f"block{i}"


initial_towers = [
    [10, 13, 9, 1],
    [4, 7],
    [5, 12],
    [8, 6, 3],
    [11],
    [2],
]

goal_towers = [
    [1, 6, 3, 9, 5],
    [13, 7],
    [11],
    [12, 10, 8, 2, 4],
]


def make_state(towers):
    state = [0] * 14
    for tower in towers:
        for idx, b in enumerate(tower):
            state[b] = 0 if idx == 0 else tower[idx - 1]
    return tuple(state)


def is_clear(state, b):
    for i in range(1, 14):
        if state[i] == b:
            return False
    return True


goal_support = [0] * 14
for tower in goal_towers:
    for idx, b in enumerate(tower):
        goal_support[b] = 0 if idx == 0 else tower[idx - 1]


def heuristic(state):
    must = [False] * 14

    for i in range(1, 14):
        cur = state[i]
        if cur == -1 or cur != goal_support[i]:
            must[i] = True

    changed = True
    while changed:
        changed = False
        for i in range(1, 14):
            if not must[i]:
                s = state[i]
                if s != 0 and s != -1 and must[s]:
                    must[i] = True
                    changed = True

    total = 0
    for i in range(1, 14):
        if not must[i]:
            continue

        cur = state[i]
        g = goal_support[i]

        if cur == -1:
            if g == 0:
                total += 1
            else:
                if state[g] == -1:
                    total += 3
                elif not is_clear(state, g) or must[g]:
                    total += 3
                else:
                    total += 1
        elif cur == g:
            total += 4
        else:
            total += 2

    return total


def successors(state):
    held = state[0]
    result = []

    if held == 0:
        for b in range(1, 14):
            s = state[b]

            if s == 0:
                if is_clear(state, b):
                    ns = list(state)
                    ns[0] = b
                    ns[b] = -1
                    result.append((("pickup", b), tuple(ns)))

            elif s != -1:
                if is_clear(state, b):
                    ns = list(state)
                    ns[0] = b
                    ns[b] = -1
                    result.append((("unstack", b, s), tuple(ns)))
    else:
        ns = list(state)
        ns[0] = 0
        ns[held] = 0
        result.append((("putdown", held), tuple(ns)))

        for c in range(1, 14):
            if state[c] == -1:
                continue
            if held == 1 and c == 4:
                continue
            if is_clear(state, c):
                ns = list(state)
                ns[0] = 0
                ns[held] = c
                if ns[1] == 4:
                    continue
                result.append((("stack", held, c), tuple(ns)))

    return result


def main():
    start = make_state(initial_towers)
    goal = make_state(goal_towers)

    if start == goal:
        return

    h0 = heuristic(start)
    counter = itertools.count()
    heap = [(h0, 0, next(counter), start)]

    best_g = {start: 0}
    parent = {start: None}
    found = False

    while heap:
        f, neg_g, _, state = heapq.heappop(heap)
        g = -neg_g

        if g != best_g.get(state):
            continue

        if state == goal:
            found = True
            break

        generated = []
        for action, ns in successors(state):
            ng = g + 1
            if ng < best_g.get(ns, 10**9):
                hns = heuristic(ns)
                generated.append((hns, ng, action, ns))

        generated.sort(key=lambda x: (x[0], x[1]))

        for hns, ng, action, ns in generated:
            if ng < best_g.get(ns, 10**9):
                best_g[ns] = ng
                parent[ns] = (state, action)
                heapq.heappush(heap, (ng + hns, -ng, next(counter), ns))

    if not found:
        print("No plan")
        return

    path = []
    cur = goal
    while parent[cur] is not None:
        prev, action = parent[cur]
        path.append(action)
        cur = prev

    path.reverse()

    lines = []
    for action in path:
        args = " ".join(block_name(x) for x in action[1:])
        lines.append(f"({action[0]} {args})")

    print("\n".join(lines))


if __name__ == "__main__":
    main()

import sys
import heapq


def main():
    blocks = tuple(range(1, 11))

    # loc[b] = 0 means on table, loc[b] = c means on block c, loc[b] = -1 means held
    loc = [0] * 11
    for b in (3, 8, 10, 4, 6, 5, 7):
        loc[b] = 0
    loc[1] = 10
    loc[2] = 1
    loc[9] = 6

    start = (tuple(loc), 0, 0)  # (locations, arm, frozen_mask)

    expected = [0] * 11
    for b in (3, 6, 7, 2, 10, 5, 4, 8, 9):
        expected[b] = 0
    expected[1] = 8
    expected = tuple(expected)

    INF = 10**9

    def is_clear(state, b):
        l = state[0]
        for z in blocks:
            if l[z] == b:
                return False
        return True

    def heuristic(state):
        l, _arm, frozen = state
        total = 0
        for b in blocks:
            if (frozen >> b) & 1:
                if l[b] != 0 or expected[b] != 0:
                    return INF
            if l[b] == expected[b]:
                continue
            if l[b] == -1:
                total += 1
            else:
                total += 2
        return total

    def is_goal(state):
        return state[0] == expected and state[1] == 0

    heap = [(heuristic(start), 0, start)]
    parent = {start: None}
    best = {start: 0}

    while heap:
        _f, g, state = heapq.heappop(heap)

        if g > best.get(state, INF):
            continue

        if is_goal(state):
            actions = []
            while parent[state] is not None:
                prev, action = parent[state]
                actions.append(action)
                state = prev
            actions.reverse()
            print("\n".join(actions))
            return

        l, arm, frozen = state

        def add(new_state, action):
            ng = g + 1
            if ng < best.get(new_state, INF):
                best[new_state] = ng
                parent[new_state] = (state, action)
                h = heuristic(new_state)
                if h < INF:
                    heapq.heappush(heap, (ng + h, ng, new_state))

        if arm == 0:
            for b in blocks:
                if l[b] == 0 and is_clear(state, b) and not ((frozen >> b) & 1):
                    nl = list(l)
                    nl[b] = -1
                    add((tuple(nl), b, frozen), f"(pickup block{b})")

            for x in blocks:
                y = l[x]
                if y != 0 and y != -1 and is_clear(state, x):
                    nl = list(l)
                    nl[x] = -1
                    add((tuple(nl), x, frozen), f"(unstack block{x} block{y})")
        else:
            b = arm

            nl = list(l)
            nl[b] = 0
            add((tuple(nl), 0, frozen | (1 << b)), f"(putdown block{b})")

            for y in blocks:
                if y == b:
                    continue
                if is_clear(state, y):
                    nl = list(l)
                    nl[b] = y
                    add((tuple(nl), 0, frozen), f"(stack block{b} block{y})")

    print("No plan")


if __name__ == "__main__":
    main()

BLOCKS = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k']
DISPLAY = {b: b for b in BLOCKS}

INITIAL_HAND = 'f'
INITIAL_LOC = {
    'a': 'table',
    'b': 'a',
    'c': 'b',
    'd': 'table',
    'e': 'd',
    'f': None,
    'g': 'table',
    'h': 'g',
    'i': 'h',
    'j': 'i',
    'k': 'j',
}

GOAL_HAND = None
GOAL_LOC = {
    'a': 'table',
    'b': 'a',
    'c': 'b',
    'd': 'table',
    'e': 'd',
    'f': 'table',
    'g': 'f',
    'h': 'g',
    'i': 'h',
    'j': 'i',
    'k': 'j',
}


def is_clear(block, loc, hand):
    if block == hand:
        return True
    return all(loc[other] != block for other in BLOCKS if other != block)


def apply_action(state, action):
    hand, loc = state
    kind = action[0]

    if kind == 'pickup':
        x = action[1]
        if hand is not None:
            return None
        if loc[x] != 'table':
            return None
        if not is_clear(x, loc, hand):
            return None
        new_loc = dict(loc)
        new_loc[x] = None
        return (x, new_loc)

    if kind == 'putdown':
        x = action[1]
        if hand != x:
            return None
        new_loc = dict(loc)
        new_loc[x] = 'table'
        return (None, new_loc)

    if kind == 'unstack':
        x, y = action[1], action[2]
        if hand is not None:
            return None
        if loc[x] != y:
            return None
        if not is_clear(x, loc, hand):
            return None
        new_loc = dict(loc)
        new_loc[x] = None
        return (x, new_loc)

    if kind == 'stack':
        x, y = action[1], action[2]
        if hand != x:
            return None
        if y not in BLOCKS or y == x:
            return None
        if loc[y] is None:
            return None
        if not is_clear(y, loc, hand):
            return None
        new_loc = dict(loc)
        new_loc[x] = y
        return (None, new_loc)

    return None


def generate_plan():
    plan = []
    stacks = [['a', 'b', 'c'], ['d', 'e'], ['g', 'h', 'i', 'j', 'k']]
    hand = INITIAL_HAND

    if hand is not None:
        plan.append(('putdown', hand))
        stacks.append([hand])
        hand = None

    support = {b: 'table' for b in BLOCKS}
    for stack in stacks:
        for i in range(1, len(stack)):
            support[stack[i]] = stack[i - 1]

    move = set()
    for b in BLOCKS:
        if support[b] != GOAL_LOC[b]:
            move.add(b)

    changed = True
    while changed:
        changed = False
        for stack in stacks:
            for i, block in enumerate(stack):
                if block in move:
                    for above in stack[i + 1:]:
                        if above not in move:
                            move.add(above)
                            changed = True

    while True:
        moved = False
        for stack in stacks:
            if len(stack) > 1 and stack[-1] in move:
                top = stack[-1]
                below = stack[-2]
                plan.append(('unstack', top, below))
                plan.append(('putdown', top))
                stack.pop()
                stacks.append([top])
                moved = True
                break
        if not moved:
            break

    goal_stacks = [['a', 'b', 'c'], ['d', 'e'], ['f', 'g', 'h', 'i', 'j', 'k']]
    for stack in goal_stacks:
        for i in range(1, len(stack)):
            block = stack[i]
            if block in move:
                plan.append(('pickup', block))
                plan.append(('stack', block, stack[i - 1]))

    return plan


def main():
    plan = generate_plan()
    state = (INITIAL_HAND, dict(INITIAL_LOC))

    for action in plan:
        state = apply_action(state, action)
        if state is None:
            print('No plan')
            return

    if state[0] == GOAL_HAND and state[1] == GOAL_LOC:
        for action in plan:
            if len(action) == 2:
                print(f'({action[0]} {DISPLAY[action[1]]})')
            else:
                print(f'({action[0]} {DISPLAY[action[1]]} {DISPLAY[action[2]]})')
    else:
        print('No plan')


if __name__ == '__main__':
    main()

import sys
from collections import Counter

TABLE = 0
BLOCKS = tuple(range(1, 15))

initial_on = {
    1: TABLE,
    2: 6,
    3: TABLE,
    4: 1,
    5: 8,
    6: TABLE,
    7: TABLE,
    8: TABLE,
    9: 10,
    10: 14,
    11: 4,
    12: 13,
    13: 11,
    14: TABLE,
}
initial_holding = TABLE

original_goal = {
    7: TABLE,
    13: 7,
    4: TABLE,
    8: 4,
    1: TABLE,
    11: TABLE,
    5: TABLE,
    6: TABLE,
    2: TABLE,
    3: TABLE,
    10: TABLE,
    12: TABLE,
    14: TABLE,
    9: TABLE,
}

additional_goal = {
    b: (b - 1 if b > 1 else TABLE) for b in BLOCKS
}


def solve(start_on, start_holding, target_on):
    on = dict(start_on)
    holding = start_holding
    actions = []

    def name(b):
        return f"block{b}"

    def is_clear(b):
        if holding == b:
            return True
        if on[b] is None:
            return False
        for x in BLOCKS:
            if on[x] == b:
                return False
        return True

    def top_of(b):
        if on[b] is None:
            return None
        for x in BLOCKS:
            if on[x] == b:
                return x
        return None

    def putdown(b):
        nonlocal holding
        if holding != b:
            return False
        on[b] = TABLE
        holding = TABLE
        actions.append(f"(putdown {name(b)})")
        return True

    def pickup(b):
        nonlocal holding
        if holding != TABLE or on[b] != TABLE or not is_clear(b):
            return False
        on[b] = None
        holding = b
        actions.append(f"(pickup {name(b)})")
        return True

    def unstack(b, s):
        nonlocal holding
        if holding != TABLE or on[b] != s or not is_clear(b):
            return False
        on[b] = None
        holding = b
        actions.append(f"(unstack {name(b)} {name(s)})")
        return True

    def stack(b, s):
        nonlocal holding
        if holding != b or on[s] is None or not is_clear(s):
            return False
        on[b] = s
        holding = TABLE
        actions.append(f"(stack {name(b)} {name(s)})")
        return True

    def ensure_empty():
        nonlocal holding
        if holding != TABLE:
            putdown(holding)

    def move_to_table(b):
        if holding == b:
            putdown(b)
            return
        ensure_empty()
        if on[b] == TABLE:
            return
        while True:
            t = top_of(b)
            if t is None:
                break
            move_to_table(t)
        s = on[b]
        if s is None:
            return
        unstack(b, s)
        putdown(b)

    def clear_support(s):
        if s == TABLE:
            return
        ensure_empty()
        while True:
            t = top_of(s)
            if t is None:
                break
            move_to_table(t)

    def place_block(b):
        target = target_on[b]
        if holding == b:
            putdown(b)
        ensure_empty()
        if on[b] == target:
            return

        while True:
            t = top_of(b)
            if t is None:
                break
            move_to_table(t)

        clear_support(target)

        if on[b] == TABLE:
            pickup(b)
        else:
            unstack(b, on[b])

        if target == TABLE:
            putdown(b)
        else:
            stack(b, target)

    target_above = {}
    for b, s in target_on.items():
        if s != TABLE:
            target_above[s] = b

    processed = set()
    for b in BLOCKS:
        if target_on[b] == TABLE:
            cur = b
            while cur is not None and cur not in processed:
                processed.add(cur)
                place_block(cur)
                cur = target_above.get(cur)

    for b in BLOCKS:
        if b not in processed:
            place_block(b)

    if holding != TABLE:
        return None
    for b in BLOCKS:
        if on[b] != target_on[b]:
            return None
    return actions


required_on = {}
conflict = False

for goal in (original_goal, additional_goal):
    for b, s in goal.items():
        if b in required_on and required_on[b] != s:
            conflict = True
            break
        required_on[b] = s
    if conflict:
        break

if conflict or len(required_on) != len(BLOCKS):
    print("No plan")
    sys.exit(0)

goal_on = required_on

for b in BLOCKS:
    s = goal_on[b]
    if s != TABLE and s not in goal_on:
        print("No plan")
        sys.exit(0)

support_counts = Counter(goal_on.values())
for s, cnt in support_counts.items():
    if s != TABLE and cnt > 1:
        print("No plan")
        sys.exit(0)

for b in BLOCKS:
    seen = set()
    cur = b
    while cur != TABLE:
        if cur in seen:
            print("No plan")
            sys.exit(0)
        seen.add(cur)
        cur = goal_on[cur]

plan = solve(initial_on, initial_holding, goal_on)

if plan is None:
    print("No plan")
else:
    sys.stdout.write("\n".join(plan))
    if plan:
        sys.stdout.write("\n")

import heapq
import itertools

TABLE = -1
HELD = -2
N = 14

BLOCKS = [f"block{i}" for i in range(1, N + 1)]

# Goal supports:
# block1 on block9
# block3 on block13, block13 on block12, block12 on block11, block11 on block2
# block4 on block7
# block10 on block5
# block14 on block6
# block2, block5, block6, block7, block8, block9 on table
GOAL = [TABLE] * N
GOAL[0] = 8     # block1 on block9
GOAL[2] = 12    # block3 on block13
GOAL[3] = 6     # block4 on block7
GOAL[9] = 4     # block10 on block5
GOAL[10] = 1    # block11 on block2
GOAL[11] = 10   # block12 on block11
GOAL[12] = 11   # block13 on block12
GOAL[13] = 5    # block14 on block6
GOAL_TUPLE = tuple(GOAL)


def heuristic(support):
    # Lower bound: each block whose support is wrong needs at least one action.
    # If it is held, one action can fix it; otherwise at least two.
    h = 0
    for cur, g in zip(support, GOAL_TUPLE):
        if cur != g:
            h += 1 if cur == HELD else 2

    # Safe extra lower bound: if a block must move, any correctly placed block
    # sitting on top of it must be moved off it first.
    for y in range(N):
        if support[y] != GOAL_TUPLE[y]:
            for z in range(N):
                if support[z] == y and support[z] == GOAL_TUPLE[z]:
                    h += 1

    return h


def moved_of(action):
    # Interpret "move" as a support-changing action: stack or unstack.
    verb = action[0]
    if verb == "stack" or verb == "unstack":
        return action[1]
    return None


def generate_actions(support, last1):
    held = -1
    for i, c in enumerate(support):
        if c == HELD:
            held = i
            break

    count = [0] * N
    for c in support:
        if 0 <= c < N:
            count[c] += 1

    actions = []

    # pickup
    for i in range(N):
        if held == -1 and support[i] == TABLE and count[i] == 0:
            actions.append(("pickup", i, None))

    # putdown
    if held != -1:
        actions.append(("putdown", held, None))

    # unstack
    if held == -1:
        for i in range(N):
            s = support[i]
            if 0 <= s < N and count[i] == 0:
                actions.append(("unstack", i, s))

    # stack
    # To keep the search directed, blocks other than block2/block3 only stack
    # onto their goal support. block2/block3 may also be used temporarily.
    if held != -1:
        goal_target = GOAL_TUPLE[held]
        for j in range(N):
            if j == held or support[j] == HELD or count[j] != 0:
                continue
            if j == goal_target or held in (1, 2):
                actions.append(("stack", held, j))

    # Additional constraint: after moving block1, the next moved block must be
    # block2 or block3.
    if last1:
        actions = [a for a in actions if moved_of(a) in (1, 2)]

    def score(a):
        verb, x, y = a
        g = GOAL_TUPLE[x]
        if verb == "stack" and g == y:
            return 0
        if verb == "putdown" and g == TABLE:
            return 1
        if verb == "unstack" and g == TABLE:
            return 1
        if verb == "pickup" and g != TABLE:
            return 1
        if verb == "unstack":
            return 2
        if verb == "stack":
            return 2
        if verb == "pickup":
            return 3
        return 4

    actions.sort(key=score)
    return actions


def apply_action(support, action):
    verb, x, y = action
    lst = list(support)
    if verb == "pickup":
        lst[x] = HELD
    elif verb == "putdown":
        lst[x] = TABLE
    elif verb == "unstack":
        lst[x] = HELD
    elif verb == "stack":
        lst[x] = y
    return tuple(lst)


def main():
    start_support = tuple([TABLE] * N)
    start_state = (start_support, False)
    start_h = heuristic(start_support)

    best = {start_state: 0}
    parent = {start_state: None}
    heap = [(start_h, start_h, 0, 0, start_state)]
    counter = itertools.count(1)
    INF = 10**9
    goal_state = None

    while heap:
        f, h, g, _, state = heapq.heappop(heap)
        if g != best.get(state):
            continue

        support, last1 = state

        if support == GOAL_TUPLE and not last1:
            goal_state = state
            break

        for action in generate_actions(support, last1):
            moved = moved_of(action)

            if last1 and moved not in (1, 2):
                continue

            new_support = apply_action(support, action)
            new_last1 = (moved == 0)
            new_state = (new_support, new_last1)
            ng = g + 1

            if ng < best.get(new_state, INF):
                best[new_state] = ng
                parent[new_state] = (state, action)
                nh = heuristic(new_support)
                heapq.heappush(heap, (ng + nh, nh, ng, next(counter), new_state))

    if goal_state is None:
        print("No plan")
        return

    plan = []
    cur = goal_state
    while parent[cur] is not None:
        prev, action = parent[cur]
        plan.append(action)
        cur = prev
    plan.reverse()

    for verb, x, y in plan:
        if y is None:
            print(f"({verb} {BLOCKS[x]})")
        else:
            print(f"({verb} {BLOCKS[x]} {BLOCKS[y]})")


if __name__ == "__main__":
    main()

import heapq

# Blocks are represented internally as integers 1..14.
BLOCKS = list(range(1, 15))


def bname(b):
    return f"block{b}"


def initial_state():
    # support 0 means "on the table"
    on = {b: 0 for b in BLOCKS}
    on[8] = 12
    on[14] = 3
    return on, 0


# Final constraints from the problem statement.
TABLE_BY_THEMSELVES = [1, 10, 4, 9, 8, 6, 13, 14, 12, 11, 3, 2]

MULTIPLES = [b for b in BLOCKS if b % 3 == 0]
ODD = [b for b in BLOCKS if b % 3 != 0 and b % 2 == 1]
EVEN = [b for b in BLOCKS if b % 3 != 0 and b % 2 == 0]


def target_on_from_additional():
    # The additional constraint determines three ordered stacks:
    # lowest number on the table, highest number on top.
    target = {}
    for stack in (MULTIPLES, ODD, EVEN):
        prev = 0
        for b in stack:
            target[b] = prev
            prev = b
    return target


def top_set(on):
    return set(on.values())


def check_original(on, held):
    if held != 0:
        return False

    tops = top_set(on)

    # These blocks are stated to be on the table by themselves.
    for b in TABLE_BY_THEMSELVES:
        if on.get(b) != 0:
            return False
        if b in tops:
            return False

    # Block 7 is on top of block 6.
    if on.get(7) != 6:
        return False

    # Block 5 is on the table.
    if on.get(5) != 0:
        return False

    return True


def check_additional(on, held):
    if held != 0:
        return False

    # Exactly three stacks.
    if sum(1 for b in BLOCKS if on.get(b) == 0) != 3:
        return False

    # Build each stack from bottom to top.
    stacks = []
    for b in BLOCKS:
        if on.get(b) == 0:
            stack = [b]
            cur = b
            while True:
                nxt = None
                for c in BLOCKS:
                    if on.get(c) == cur:
                        nxt = c
                        break
                if nxt is None:
                    break
                stack.append(nxt)
                cur = nxt
            stacks.append(stack)

    if len(stacks) != 3:
        return False

    allowed = [set(MULTIPLES), set(ODD), set(EVEN)]
    used = set()

    for stack in stacks:
        # Stacks must be in increasing block-number order from bottom to top.
        if stack != sorted(stack):
            return False

        s = set(stack)
        for i, a in enumerate(allowed):
            if s == a and i not in used:
                used.add(i)
                break
        else:
            return False

    return len(used) == 3


def feasible_final():
    # The additional constraint uniquely determines the final support relation.
    target = target_on_from_additional()
    return check_additional(target, 0) and check_original(target, 0)


if not feasible_final():
    print("No plan")
    raise SystemExit


TARGET = target_on_from_additional()


def make_key(on, held):
    return (held, tuple(sorted(on.items())))


def successors(on, held):
    tops = top_set(on)

    if held == 0:
        # pickup a clear block from the table
        for b in BLOCKS:
            if on.get(b) == 0 and b not in tops:
                new_on = dict(on)
                del new_on[b]
                yield (("pickup", b), new_on, b)

        # unstack a clear block from another block
        for b in BLOCKS:
            support = on.get(b)
            if support is not None and support != 0 and b not in tops:
                new_on = dict(on)
                del new_on[b]
                yield (("unstack", b, support), new_on, b)
    else:
        x = held

        # putdown the held block
        new_on = dict(on)
        new_on[x] = 0
        yield (("putdown", x), new_on, 0)

        # stack the held block on a clear block
        for y in BLOCKS:
            if y != x and on.get(y) is not None and y not in tops:
                new_on = dict(on)
                new_on[x] = y
                yield (("stack", x, y), new_on, 0)


def heuristic(on, held):
    # Number of blocks whose current support differs from the target support.
    # Each action changes the support of at most one block, so this is admissible.
    mismatches = 0
    for b in BLOCKS:
        current = -1 if b == held else on.get(b)
        if current != TARGET[b]:
            mismatches += 1
    return mismatches


def solve():
    start_on, start_held = initial_state()
    start_key = make_key(start_on, start_held)

    counter = 0
    heap = [(heuristic(start_on, start_held), 0, counter, start_key, start_on, start_held)]
    best_g = {start_key: 0}
    parent = {start_key: (None, None)}

    while heap:
        f, g, _, key, on, held = heapq.heappop(heap)

        if g != best_g.get(key):
            continue

        if held == 0 and on == TARGET:
            actions = []
            k = key
            while parent[k][0] is not None:
                prev, action = parent[k]
                actions.append(action)
                k = prev
            actions.reverse()
            return actions

        for action, new_on, new_held in successors(on, held):
            nkey = make_key(new_on, new_held)
            ng = g + 1

            if nkey not in best_g or ng < best_g[nkey]:
                best_g[nkey] = ng
                parent[nkey] = (key, action)
                counter += 1
                heapq.heappush(
                    heap,
                    (ng + heuristic(new_on, new_held), ng, counter, nkey, new_on, new_held)
                )

    return None


def format_action(action):
    if action[0] == "pickup":
        return f"(pickup {bname(action[1])})"
    if action[0] == "putdown":
        return f"(putdown {bname(action[1])})"
    if action[0] == "stack":
        return f"(stack {bname(action[1])} {bname(action[2])})"
    if action[0] == "unstack":
        return f"(unstack {bname(action[1])} {bname(action[2])})"
