import heapq
import sys
from itertools import count
from functools import lru_cache

BLOCKS = tuple(range(1, 11))


def block_name(b):
    return f"block{b}"


def support_from(mapping):
    s = [0] * 11
    for b, sup in mapping.items():
        s[b] = sup
    return tuple(s)


INITIAL_SUPPORT = support_from({
    3: 0, 7: 3,
    10: 0, 4: 0, 2: 0, 9: 0, 1: 0, 6: 0, 5: 0,
    8: 5,
})

GOAL_SUPPORT = support_from({
    6: 0, 2: 0, 10: 0,
    7: 2, 4: 7,
    8: 10, 1: 8, 3: 1, 9: 3, 5: 9,
})

GOAL_STATE = (GOAL_SUPPORT, 0)


def goal_is_valid():
    children = {}
    for b in BLOCKS:
        s = GOAL_SUPPORT[b]
        if s < 0 or s > 10 or s == b:
            return False
        if s > 0:
            if s in children:
                return False
            children[s] = b

    for b in BLOCKS:
        seen = set()
        cur = b
        while cur != 0:
            if cur in seen:
                return False
            seen.add(cur)
            cur = GOAL_SUPPORT[cur]
    return True


def is_clear(support, b):
    for c in BLOCKS:
        if support[c] == b:
            return False
    return True


def apply_action(state, action, b, other):
    support = list(state[0])
    held = state[1]

    if action == "pickup":
        support[b] = -1
        held = b
    elif action == "unstack":
        support[b] = -1
        held = b
    elif action == "putdown":
        support[b] = 0
        held = 0
    elif action == "stack":
        support[b] = other
        held = 0

    return (tuple(support), held)


def successors(state):
    support, held = state

    if held == 0:
        for b in BLOCKS:
            sup = support[b]
            if sup == -1:
                continue
            if not is_clear(support, b):
                continue

            if sup == 0:
                yield ("pickup", b), apply_action(state, "pickup", b, 0)
            else:
                yield ("unstack", b, sup), apply_action(state, "unstack", b, sup)
    else:
        b = held
        yield ("putdown", b), apply_action(state, "putdown", b, 0)

        for x in BLOCKS:
            if x == b:
                continue
            if support[x] == -1:
                continue
            if not is_clear(support, x):
                continue
            yield ("stack", b, x), apply_action(state, "stack", b, x)


@lru_cache(maxsize=None)
def heuristic(state):
    support, held = state
    memo = {}
    visiting = set()

    def fixed(b):
        if b in memo:
            return memo[b]
        if b in visiting:
            return False

        visiting.add(b)
        s = support[b]

        if s != GOAL_SUPPORT[b]:
            res = False
        elif s == 0:
            res = True
        elif s == -1:
            res = False
        else:
            res = fixed(s)

        visiting.remove(b)
        memo[b] = res
        return res

    h = 0
    for b in BLOCKS:
        if not fixed(b):
            h += 1 if held == b else 2
    return h


def solve():
    if not goal_is_valid():
        return None

    start = (INITIAL_SUPPORT, 0)
    if start == GOAL_STATE:
        return []

    counter = count()
    h0 = heuristic(start)

    heap = [(h0, 0, next(counter), start)]
    g_score = {start: 0}
    parent = {start: (None, None)}

    while heap:
        _, neg_g, _, state = heapq.heappop(heap)
        g = -neg_g

        if g != g_score.get(state):
            continue

        if state == GOAL_STATE:
            plan = []
            while state != start:
                prev, action = parent[state]
                plan.append(action)
                state = prev
            plan.reverse()
            return plan

        for action, nxt in successors(state):
            ng = g + 1
            if ng < g_score.get(nxt, float("inf")):
                g_score[nxt] = ng
                parent[nxt] = (state, action)
                h = heuristic(nxt)
                heapq.heappush(heap, (ng + h, -ng, next(counter), nxt))

    return None


def main():
    plan = solve()

    if plan is None:
        sys.stdout.write("No plan\n")
        return

    lines = []
    for action in plan:
        if len(action) == 2:
            lines.append(f"({action[0]} {block_name(action[1])})")
        else:
            lines.append(f"({action[0]} {block_name(action[1])} {block_name(action[2])})")

    sys.stdout.write("\n".join(lines))
    if lines:
        sys.stdout.write("\n")


if __name__ == "__main__":
    main()

def main():
    blocks = [f"block{i}" for i in range(1, 12)]
    goal_order = [
        "block11", "block8", "block2", "block4", "block10",
        "block1", "block5", "block6", "block3", "block7", "block9"
    ]

    goal_support = {
        goal_order[i]: (goal_order[i - 1] if i > 0 else "table")
        for i in range(len(goal_order))
    }

    goal_children = {b: [] for b in blocks}
    for b in blocks:
        support = goal_support[b]
        if support != "table":
            goal_children[support].append(b)

    plan = []
    initial_placed = {goal_order[0]}

    def search(placed, obligation):
        if len(placed) == len(blocks):
            return not obligation

        for b in goal_order:
            if b in placed:
                continue

            support = goal_support[b]

            if support != "table" and support not in placed:
                continue

            if any(child in placed for child in goal_children[b]):
                continue

            if support != "table" and any(child in placed for child in goal_children[support]):
                continue

            next_obligation = obligation
            if b == "block1":
                next_obligation = True
            elif b == "block6":
                next_obligation = False

            if support == "table":
                actions = [f"(pickup {b})", f"(putdown {b})"]
            else:
                actions = [f"(pickup {b})", f"(stack {b} {support})"]

            plan.extend(actions)
            if search(placed | {b}, next_obligation):
                return True
            del plan[-len(actions):]

        return False

    found = search(initial_placed, False)

    if not found:
        print("No plan")
        return

    on = {b: "table" for b in blocks}
    holding = None
    obligation = False
    valid = True

    def clear(block):
        return all(on[x] != block for x in blocks if on[x] != "held")

    for line in plan:
        inner = line[1:-1].split()
        if not inner:
            valid = False
            break

        action = inner[0]

        if action == "pickup":
            if len(inner) != 2:
                valid = False
                break
            b = inner[1]
            if holding is not None or on[b] != "table" or not clear(b):
                valid = False
                break
            holding = b
            on[b] = "held"

        elif action == "putdown":
            if len(inner) != 2:
                valid = False
                break
            b = inner[1]
            if holding != b:
                valid = False
                break
            holding = None
            on[b] = "table"

        elif action == "stack":
            if len(inner) != 3:
                valid = False
                break
            b, y = inner[1], inner[2]
            if holding != b or y == b or on[y] == "held" or not clear(y):
                valid = False
                break
            holding = None
            on[b] = y

        elif action == "unstack":
            if len(inner) != 3:
                valid = False
                break
            b, y = inner[1], inner[2]
            if holding is not None or on[b] != y or not clear(b):
                valid = False
                break
            holding = b
            on[b] = "held"

        else:
            valid = False
            break

        if b == "block1":
            obligation = True
        elif b == "block6":
            obligation = False

    if valid and holding is None and all(on[b] == goal_support[b] for b in blocks) and not obligation:
        print("\n".join(plan))
    else:
        print("No plan")


if __name__ == "__main__":
    main()

import sys

def main():
    initial_stacks = [
        ["block3", "block14", "block7", "block11"],
        ["block10", "block12", "block5", "block6", "block8", "block4", "block9", "block13", "block2", "block1"]
    ]
    goal_stacks = [
        ["block14", "block4", "block1"],
        ["block11", "block5", "block10", "block6", "block12", "block3", "block7", "block13", "block8", "block9", "block2"]
    ]

    def find_stack(stacks, block):
        for i, stack in enumerate(stacks):
            if block in stack:
                return i
        return None

    def pop_to_table(stacks, block, plan):
        i = find_stack(stacks, block)
        if i is None:
            return False
        stack = stacks[i]
        if stack[-1] != block:
            return False
        if len(stack) == 1:
            return True
        support = stack[-2]
        plan.append(f"(unstack {block} {support})")
        plan.append(f"(putdown {block})")
        stack.pop()
        if not stack:
            stacks.pop(i)
        stacks.append([block])
        return True

    def clear_block(stacks, block, plan):
        while True:
            i = find_stack(stacks, block)
            if i is None:
                return False
            stack = stacks[i]
            if stack[-1] == block:
                return True
            top = stack[-1]
            if not pop_to_table(stacks, top, plan):
                return False

    def move_to_table(stacks, block, plan):
        if not clear_block(stacks, block, plan):
            return False
        return pop_to_table(stacks, block, plan)

    def pop_to_block(stacks, block, target, plan):
        i = find_stack(stacks, block)
        if i is None:
            return False
        stack = stacks[i]
        if stack[-1] != block:
            return False
        if len(stack) == 1:
            plan.append(f"(pickup {block})")
            stacks.pop(i)
        else:
            support = stack[-2]
            plan.append(f"(unstack {block} {support})")
            stack.pop()
            if not stack:
                stacks.pop(i)
        j = find_stack(stacks, target)
        if j is None:
            return False
        target_stack = stacks[j]
        if target_stack[-1] != target:
            return False
        plan.append(f"(stack {block} {target})")
        target_stack.append(block)
        return True

    def move_to_block(stacks, block, target, plan):
        if not clear_block(stacks, block, plan):
            return False
        return pop_to_block(stacks, block, target, plan)

    def generate_plan():
        stacks = [list(s) for s in initial_stacks]
        plan = []
        for goal_stack in goal_stacks:
            current = None
            for block in goal_stack:
                if current is None:
                    if not move_to_table(stacks, block, plan):
                        return None
                    current = block
                else:
                    if not move_to_block(stacks, block, current, plan):
                        return None
                    current = block
        return plan, stacks

    def simulate(plan, initial_stacks):
        stacks = [list(s) for s in initial_stacks]
        held = None
        for line in plan:
            parts = line.strip().strip("()").split()
            if not parts:
                return None
            action = parts[0]
            if action == "pickup":
                if len(parts) != 2:
                    return None
                block = parts[1]
                if held is not None:
                    return None
                i = find_stack(stacks, block)
                if i is None:
                    return None
                stack = stacks[i]
                if len(stack) != 1 or stack[0] != block:
                    return None
                stacks.pop(i)
                held = block
            elif action == "putdown":
                if len(parts) != 2:
                    return None
                block = parts[1]
                if held != block:
                    return None
                stacks.append([block])
                held = None
            elif action == "unstack":
                if len(parts) != 3:
                    return None
                block = parts[1]
                support = parts[2]
                if held is not None:
                    return None
                i = find_stack(stacks, block)
                if i is None:
                    return None
                stack = stacks[i]
                if len(stack) < 2 or stack[-1] != block or stack[-2] != support:
                    return None
                stack.pop()
                if not stack:
                    stacks.pop(i)
                held = block
            elif action == "stack":
                if len(parts) != 3:
                    return None
                block = parts[1]
                target = parts[2]
                if held != block:
                    return None
                if block == target:
                    return None
                j = find_stack(stacks, target)
                if j is None:
                    return None
                target_stack = stacks[j]
                if target_stack[-1] != target:
                    return None
                target_stack.append(block)
                held = None
            else:
                return None
        if held is not None:
            return None
        return stacks

    def goal_reached(stacks):
        return set(tuple(s) for s in stacks) == set(tuple(s) for s in goal_stacks)

    def constraint_ok(plan):
        need_block5 = False
        for line in plan:
            parts = line.strip().strip("()").split()
            if len(parts) < 2:
                return False
            moved = parts[1]
            if moved == "block1":
                need_block5 = True
            elif moved == "block5":
                need_block5 = False
        return not need_block5

    result = generate_plan()
    if result is None:
        print("No plan")
        return

    plan, _ = result
    final_stacks = simulate(plan, initial_stacks)

    if final_stacks is None or not goal_reached(final_stacks) or not constraint_ok(plan):
        print("No plan")
        return

    sys.stdout.write("\n".join(plan))
    if plan:
        sys.stdout.write("\n")

if __name__ == "__main__":
    main()

import sys
from collections import deque

N = 7
TABLE = -1
HELD = -2
NONE = -3

# Indices 0..6 correspond to block1..block7.
# Initial:
# block1 on block6, block7 on block4, all others on table.
INIT_LOC = (5, TABLE, TABLE, TABLE, TABLE, TABLE, 3)

# Goal:
# block1, block2, block4, block5 on table
# block3 on block5
# block6 on block4
# block7 on block6
GOAL_LOC = (TABLE, TABLE, 4, TABLE, TABLE, 3, 5)

START_STATE = (INIT_LOC, -1, False, NONE)


def is_clear(loc, i):
    for k in range(N):
        if k != i and loc[k] == i:
            return False
    return True


def successors(state):
    loc, held, need5, start = state

    if held == -1:
        # Pickup from table.
        for i in range(N):
            if loc[i] == TABLE and is_clear(loc, i):
                if need5 and i != 4:
                    continue
                new_loc = list(loc)
                new_loc[i] = HELD
                yield (tuple(new_loc), i, need5, TABLE), ('pickup', i)

        # Unstack from another block.
        for i in range(N):
            if loc[i] != TABLE and loc[i] != HELD:
                if is_clear(loc, i):
                    if need5 and i != 4:
                        continue
                    j = loc[i]
                    new_loc = list(loc)
                    new_loc[i] = HELD
                    yield (tuple(new_loc), i, need5, j), ('unstack', i, j)

    else:
        i = held

        # If a multiple-of-3 move is pending, the next completed move must be block5.
        if need5 and i != 4:
            return

        # Putdown, only if it changes support.
        if start != TABLE:
            new_loc = list(loc)
            new_loc[i] = TABLE
            yield (tuple(new_loc), -1, (i % 3 == 0), NONE), ('putdown', i)

        # Stack on another clear block, only if it changes support.
        for j in range(N):
            if j == i:
                continue
            if loc[j] == HELD:
                continue
            if j == start:
                continue
            if is_clear(loc, j):
                new_loc = list(loc)
                new_loc[i] = j
                yield (tuple(new_loc), -1, (i % 3 == 0), NONE), ('stack', i, j)


def is_goal(state):
    loc, held, _, _ = state
    return held == -1 and loc == GOAL_LOC


def main():
    parent = {START_STATE: None}
    queue = deque([START_STATE])

    while queue:
        state = queue.popleft()

        if is_goal(state):
            actions = []
            cur = state
            while parent[cur] is not None:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev
            actions.reverse()

            lines = []
            for action in actions:
                if action[0] in ('pickup', 'putdown'):
                    lines.append(f"({action[0]} block{action[1] + 1})")
                else:
                    lines.append(
                        f"({action[0]} block{action[1] + 1} block{action[2] + 1})"
                    )

            sys.stdout.write("\n".join(lines))
            return

        for nxt, action in successors(state):
            if nxt not in parent:
                parent[nxt] = (state, action)
                queue.append(nxt)

    print("No plan")


if __name__ == "__main__":
    main()

import heapq

BLOCKS = tuple(range(1, 9))


def canonical(stacks):
    return tuple(sorted(tuple(s) for s in stacks if s))


INITIAL_STACKS = canonical(((1, 5, 7, 8), (2, 6, 4), (3,)))
GOAL_STACKS = canonical(((5, 6), (1,), (2,), (3,), (4,), (7,), (8,)))

GOAL_SUPPORT = [None] * (max(BLOCKS) + 1)
for stack in GOAL_STACKS:
    for i, b in enumerate(stack):
        GOAL_SUPPORT[b] = stack[i - 1] if i > 0 else None


def heuristic(state):
    stacks, held = state
    h = 0

    for stack in stacks:
        bottom = stack[0]
        if GOAL_SUPPORT[bottom] is not None:
            h += 2

        for i in range(1, len(stack)):
            b = stack[i]
            support = stack[i - 1]
            if support != GOAL_SUPPORT[b]:
                h += 2

    if held is not None:
        h += 1

    return h


def successors(state):
    stacks, held = state
    result = []

    if held is None:
        for idx, stack in enumerate(stacks):
            top = stack[-1]

            if len(stack) == 1:
                new_stacks = stacks[:idx] + stacks[idx + 1:]
                result.append(
                    (f"(pickup block{top})", (canonical(new_stacks), top))
                )
            else:
                below = stack[-2]
                new_stack = stack[:-1]
                new_stacks = stacks[:idx] + (new_stack,) + stacks[idx + 1:]
                result.append(
                    (f"(unstack block{top} block{below})", (canonical(new_stacks), top))
                )
    else:
        b = held

        new_stacks = stacks + ((b,),)
        result.append(
            (f"(putdown block{b})", (canonical(new_stacks), None))
        )

        for idx, stack in enumerate(stacks):
            below = stack[-1]
            new_stack = stack + (b,)
            new_stacks = stacks[:idx] + (new_stack,) + stacks[idx + 1:]
            result.append(
                (f"(stack block{b} block{below})", (canonical(new_stacks), None))
            )

    return result


def main():
    start = (INITIAL_STACKS, None)
    goal = (GOAL_STACKS, None)

    if start == goal:
        return

    g_score = {start: 0}
    parent = {}
    closed = set()
    counter = 0

    heap = [(heuristic(start), counter, start)]
    counter += 1

    while heap:
        _, _, state = heapq.heappop(heap)

        if state in closed:
            continue

        if state == goal:
            actions = []
            while state in parent:
                prev_state, action = parent[state]
                actions.append(action)
                state = prev_state

            actions.reverse()
            if actions:
                print("\n".join(actions))
            return

        closed.add(state)
        g = g_score[state]

        for action, next_state in successors(state):
            if next_state in closed:
                continue

            ng = g + 1
            old = g_score.get(next_state)

            if old is None or ng < old:
                g_score[next_state] = ng
                parent[next_state] = (state, action)
                heapq.heappush(
                    heap,
                    (ng + heuristic(next_state), counter, next_state)
                )
                counter += 1

    print("No plan")


if __name__ == "__main__":
    main()

import sys


def main():
    blocks = list(range(1, 14))

    def name(i):
        return f"block{i}"

    on = {
        1: 6,
        2: 11,
        3: None,
        4: None,
        5: 13,
        6: None,
        7: None,
        8: 4,
        9: None,
        10: None,
        11: 7,
        12: None,
        13: None,
    }

    on_top = {b: None for b in blocks}
    for b, s in on.items():
        if s is not None:
            on_top[s] = b

    arm = None
    plan = []

    def apply_action(action, a, b=None):
        nonlocal arm

        if action == "pickup":
            if arm is not None or on[a] is not None or on_top[a] is not None:
                return False
            arm = a
            return True

        if action == "putdown":
            if arm is None or on[arm] is not None or on_top[arm] is not None:
                return False
            arm = None
            return True

        if action == "stack":
            if (
                arm is None
                or arm != a
                or on[a] is not None
                or on_top[a] is not None
                or b is None
                or b == a
                or on_top[b] is not None
            ):
                return False
            on[a] = b
            on_top[b] = a
            arm = None
            return True

        if action == "unstack":
            if arm is not None or b is None or on[a] != b or on_top[a] is not None:
                return False
            on[a] = None
            on_top[b] = None
            arm = a
            return True

        return False

    def add_action(action, a, b=None):
        if not apply_action(action, a, b):
            return False
        if b is None:
            plan.append(f"({action} {name(a)})")
        else:
            plan.append(f"({action} {name(a)} {name(b)})")
        return True

    while any(on[b] is not None for b in blocks):
        top = None
        for b in blocks:
            if on[b] is not None and on_top[b] is None:
                top = b
                break

        if top is None:
            print("No plan")
            return

        support = on[top]
        if not add_action("unstack", top, support):
            print("No plan")
            return
        if not add_action("putdown", top):
            print("No plan")
            return

    goal_stacks = [
        [6, 13],
        [2, 8, 7, 1],
        [5, 9],
        [12, 3, 11, 4],
        [10],
    ]

    for stack in goal_stacks:
        current = stack[0]
        if on[current] is not None or on_top[current] is not None:
            print("No plan")
            return

        for b in stack[1:]:
            if on[b] is not None or on_top[b] is not None:
                print("No plan")
                return

            if not add_action("pickup", b):
                print("No plan")
                return
            if not add_action("stack", b, current):
                print("No plan")
                return

            current = b

    expected_on = {
        13: 6,
        8: 2,
        7: 8,
        1: 7,
        9: 5,
        3: 12,
        11: 3,
        4: 11,
    }

    if arm is not None:
        print("No plan")
        return

    for b in blocks:
        if on[b] != expected_on.get(b, None):
            print("No plan")
            return

    print("\n".join(plan))


if __name__ == "__main__":
    main()

import sys
from collections import deque

def main():
    blocks = ["a", "b", "c", "d", "e", "f", "g", "h"]
    n = len(blocks)
    TABLE = -1
    HELD = -2

    initial_support = (TABLE, 0, TABLE, TABLE, 3, 4, TABLE, 6)
    goal_support = (TABLE, 0, 1, TABLE, 3, 4, TABLE, 6)

    start = (None, initial_support)
    goal = (None, goal_support)

    def is_clear(support, x):
        for z, s in enumerate(support):
            if z != x and s == x:
                return False
        return True

    def successors(state):
        held, support = state

        for x in range(n):
            if held is None and support[x] == TABLE and is_clear(support, x):
                ns = list(support)
                ns[x] = HELD
                yield ("pickup", x, None), (x, tuple(ns))

            y = support[x]
            if y != TABLE and y != HELD and is_clear(support, x):
                ns = list(support)
                ns[x] = HELD
                yield ("unstack", x, y), (x, tuple(ns))

        if held is not None:
            x = held

            ns = list(support)
            ns[x] = TABLE
            yield ("putdown", x, None), (None, tuple(ns))

            for y in range(n):
                if y != x and is_clear(support, y):
                    ns = list(support)
                    ns[x] = y
                    yield ("stack", x, y), (None, tuple(ns))

    parent = {start: (None, None)}
    q = deque([start])
    found = False

    while q:
        state = q.popleft()

        if state == goal:
            found = True
            break

        for action, nxt in successors(state):
            if nxt not in parent:
                parent[nxt] = (state, action)
                if nxt == goal:
                    found = True
                    break
                q.append(nxt)

        if found:
            break

    if goal not in parent:
        print("No plan")
        return

    actions = []
    state = goal
    while parent[state][0] is not None:
        prev, action = parent[state]
        actions.append(action)
        state = prev

    actions.reverse()

    for action in actions:
        name, x, y = action
        if y is None:
            print(f"({name} {blocks[x]})")
        else:
            print(f"({name} {blocks[x]} {blocks[y]})")

