import sys


class PlanError(Exception):
    pass


def main():
    blocks = [f"block{i}" for i in range(1, 13)]
    block_set = set(blocks)

    # Initial state:
    # on_table(b): b is directly on the table
    # on(x, y): x is directly on y
    initial_on_table = {
        "block7", "block9", "block4", "block6", "block12",
        "block8", "block2", "block3", "block10",
    }
    initial_on = {
        "block5": "block4",
        "block11": "block5",
        "block1": "block10",
    }

    # Goal state facts.
    goal_on_table = {"block12", "block9", "block4"}
    goal_on = {
        "block11": "block9",
        "block3": "block11",
        "block6": "block4",
        "block10": "block6",
        "block1": "block10",
        "block7": "block1",
        "block5": "block7",
        "block8": "block5",
        "block2": "block8",
    }

    # Additional constraint: final arm must hold block12.
    required_arm = "block12"

    # Validate that all named blocks exist.
    for b in list(initial_on_table) + list(initial_on.keys()) + list(initial_on.values()):
        if b not in block_set:
            print("No plan")
            return

    for b in list(goal_on_table) + list(goal_on.keys()) + list(goal_on.values()):
        if b not in block_set:
            print("No plan")
            return

    if required_arm is not None and required_arm not in block_set:
        print("No plan")
        return

    # Validate the initial configuration.
    ok = True
    initial_above = {}
    for x, y in initial_on.items():
        if y in initial_above and initial_above[y] != x:
            ok = False
        initial_above[y] = x

    for b in blocks:
        if b in initial_on_table and b in initial_on:
            ok = False
        if b not in initial_on_table and b not in initial_on:
            ok = False

    for start in blocks:
        if start not in initial_on:
            continue
        seen = set()
        cur = start
        while cur in initial_on:
            if cur in seen:
                ok = False
                break
            seen.add(cur)
            cur = initial_on[cur]
        if not ok:
            break
        if cur not in initial_on_table:
            ok = False
            break

    if not ok:
        print("No plan")
        return

    # Validate the goal configuration and the final holding constraint.
    ok = True
    below = dict(goal_on)
    above = {}

    for x, y in goal_on.items():
        if y in above and above[y] != x:
            ok = False
        above[y] = x

    # A held block cannot simultaneously be on the table, on another block,
    # or have another block on top of it.
    if required_arm is not None:
        if required_arm in goal_on_table or required_arm in below or required_arm in above:
            ok = False

    for b in goal_on_table:
        if b in below:
            ok = False

    for start in blocks:
        if start not in below:
            continue
        seen = set()
        cur = start
        while cur in below:
            if cur in seen:
                ok = False
                break
            seen.add(cur)
            cur = below[cur]
        if not ok:
            break
        if cur not in goal_on_table:
            ok = False
            break

    if not ok:
        print("No plan")
        return

    # Current state.
    on_table = set(initial_on_table)
    on = dict(initial_on)
    arm = None
    plan = []

    def is_clear(b):
        return not any(top == b for top in on.values())

    def do_pickup(b):
        nonlocal arm
        if arm is not None or b not in on_table or not is_clear(b):
            raise PlanError
        on_table.remove(b)
        arm = b
        plan.append(f"(pickup {b})")

    def do_putdown(b):
        nonlocal arm
        if arm != b or not is_clear(b):
            raise PlanError
        arm = None
        on_table.add(b)
        plan.append(f"(putdown {b})")

    def do_unstack(x, y):
        nonlocal arm
        if arm is not None or on.get(x) != y or not is_clear(x):
            raise PlanError
        del on[x]
        on_table.add(y)
        arm = x
        plan.append(f"(unstack {x} {y})")

    def do_stack(x, y):
        nonlocal arm
        if arm != x or not is_clear(x) or not is_clear(y):
            raise PlanError
        if y not in on_table and y not in on:
            raise PlanError
        arm = None
        on[x] = y
        plan.append(f"(stack {x} {y})")

    try:
        # First move all stacked blocks to the table.
        while on:
            tops = [x for x in on if is_clear(x)]
            if not tops:
                raise PlanError
            x = tops[0]
            y = on[x]
            do_unstack(x, y)

        # Build each goal stack from bottom to top.
        goal_stacks = []
        for base in sorted(goal_on_table):
            stack = [base]
            cur = base
            while cur in above:
                cur = above[cur]
                stack.append(cur)
            goal_stacks.append(stack)

        for stack in goal_stacks:
            for i in range(1, len(stack)):
                x = stack[i]
                y = stack[i - 1]
                do_pickup(x)
                do_stack(x, y)

        # Satisfy the additional final holding constraint.
        if required_arm is not None:
            do_pickup(required_arm)

        # Final verification of all required goal facts.
        for b in goal_on_table:
            if b not in on_table:
                raise PlanError

        for x, y in goal_on.items():
            if on.get(x) != y:
                raise PlanError

        if arm != required_arm:
            raise PlanError

        if required_arm is not None and (
            required_arm in on_table or required_arm in on or required_arm in on.values()
        ):
            raise PlanError

    except PlanError:
        print("No plan")
        return

    if plan:
        sys.stdout.write("\n".join(plan) + "\n")


if __name__ == "__main__":
    main()

import sys
from collections import deque


def b(n):
    return f"block{n}"


BLOCKS = [b(i) for i in range(1, 16)]
IDX = {name: i for i, name in enumerate(BLOCKS)}
N = len(BLOCKS)

TABLE = -1
ARM = -2
REQUIRED_STACKS = 4

INITIAL_STACKS = [
    [b(6), b(3), b(5)],
    [b(11)],
    [b(14), b(8), b(7), b(9), b(4), b(15), b(12), b(2), b(13), b(10)],
    [b(1)],
]

GOAL_STACKS = [
    [b(8), b(7), b(12), b(5), b(13)],
    [b(15), b(4)],
    [b(3), b(11), b(2), b(9), b(14), b(10), b(6), b(1)],
]


def make_state(stacks):
    parent = [TABLE] * N
    for stack in stacks:
        prev = TABLE
        for name in stack:
            i = IDX[name]
            parent[i] = prev
            prev = i
    return (tuple(parent), -1)


def stack_count(state):
    parent, _ = state
    return sum(1 for p in parent if p == TABLE)


def clear_blocks(parent):
    covered = [False] * N
    for i, p in enumerate(parent):
        if p >= 0:
            covered[p] = True
    return [not covered[i] for i in range(N)]


def successors(state):
    parent, holding = state
    parent = list(parent)
    clear = clear_blocks(parent)

    for x in range(N):
        if holding == -1:
            if parent[x] == TABLE and clear[x]:
                nxt = parent[:]
                nxt[x] = ARM
                yield (tuple(nxt), x), f"(pickup {BLOCKS[x]})"
            elif parent[x] >= 0 and clear[x]:
                y = parent[x]
                nxt = parent[:]
                nxt[x] = ARM
                yield (tuple(nxt), x), f"(unstack {BLOCKS[x]} {BLOCKS[y]})"

    if holding != -1:
        x = holding

        nxt = parent[:]
        nxt[x] = TABLE
        yield (tuple(nxt), -1), f"(putdown {BLOCKS[x]})"

        for y in range(N):
            if y != x and clear[y] and parent[y] != ARM:
                nxt = parent[:]
                nxt[x] = y
                yield (tuple(nxt), -1), f"(stack {BLOCKS[x]} {BLOCKS[y]})"


def solve():
    initial = make_state(INITIAL_STACKS)
    goal = make_state(GOAL_STACKS)

    # The goal is reached after moving has started, so it must satisfy
    # the additional exact stack-count constraint.
    if stack_count(goal) != REQUIRED_STACKS:
        print("No plan")
        return

    if initial == goal:
        return

    # If the initial state already has exactly the required number of stacks,
    # pickup and putdown would change that number and are therefore forbidden.
    # Hence the set of blocks directly on the table is invariant.
    if stack_count(initial) == REQUIRED_STACKS:
        initial_table = {i for i, p in enumerate(initial[0]) if p == TABLE}
        goal_table = {i for i, p in enumerate(goal[0]) if p == TABLE}
        if initial_table != goal_table:
            print("No plan")
            return

    queue = deque([initial])
    came_from = {initial: None}

    while queue:
        state = queue.popleft()

        if state == goal:
            actions = []
            cur = state
            while came_from[cur] is not None:
                prev, action = came_from[cur]
                actions.append(action)
                cur = prev
            print("\n".join(reversed(actions)))
            return

        for next_state, action in successors(state):
            if stack_count(next_state) != REQUIRED_STACKS:
                continue
            if next_state not in came_from:
                came_from[next_state] = (state, action)
                queue.append(next_state)

    print("No plan")


if __name__ == "__main__":
    solve()

def valid_config(blocks, on_pairs, table_blocks, held=None):
    blocks_set = set(blocks)
    if held is not None and held not in blocks_set:
        return False

    table_set = set(table_blocks)
    if not table_set.issubset(blocks_set):
        return False

    assigned = set()
    if held is not None:
        assigned.add(held)

    for b in table_set:
        if b in assigned:
            return False
        assigned.add(b)

    support_of = {}
    top_of = {}

    for x, y in on_pairs:
        if x not in blocks_set or y not in blocks_set:
            return False
        if x in assigned:
            return False
        if x in support_of:
            return False
        if y in top_of:
            return False
        if held is not None and (x == held or y == held):
            return False

        support_of[x] = y
        top_of[y] = x
        assigned.add(x)

    if assigned != blocks_set:
        return False

    for b in blocks_set:
        seen = set()
        cur = b
        while cur in support_of:
            if cur in seen:
                return False
            seen.add(cur)
            cur = support_of[cur]

    return True


def make_state(blocks, on_pairs, table_blocks, arm=None):
    loc = {b: None for b in blocks}
    top = {b: None for b in blocks}

    for b in table_blocks:
        loc[b] = None

    for x, y in on_pairs:
        loc[x] = ("on", y)
        top[y] = x

    if arm is not None:
        loc[arm] = "held"

    return {"loc": loc, "top": top, "arm": arm}


def clear_to_table(st, blocks, plan):
    while True:
        moved = False
        for support in blocks:
            topb = st["top"][support]
            if topb is not None and st["top"][topb] is None:
                plan.append(("unstack", topb, support))
                st["arm"] = topb
                st["loc"][topb] = "held"
                st["top"][support] = None

                plan.append(("putdown", topb))
                st["arm"] = None
                st["loc"][topb] = None

                moved = True
                break
        if not moved:
            break


def build_goal(st, goal_on, goal_table, plan):
    goal_top = {}
    for x, y in goal_on:
        goal_top[y] = x

    for bottom in goal_table:
        current = bottom
        while current in goal_top:
            nxt = goal_top[current]

            plan.append(("pickup", nxt))
            st["arm"] = nxt
            st["loc"][nxt] = "held"

            plan.append(("stack", nxt, current))
            st["arm"] = None
            st["loc"][nxt] = ("on", current)
            st["top"][current] = nxt

            current = nxt


def final_pickup(st, held, plan):
    plan.append(("pickup", held))
    st["arm"] = held
    st["loc"][held] = "held"


def matches_goal(st, blocks, goal_on, goal_table, final_held):
    if st["arm"] != final_held:
        return False

    goal_on_set = set(goal_on)
    goal_table_set = set(goal_table)

    for b in blocks:
        loc = st["loc"][b]

        if b == final_held:
            if loc != "held":
                return False
            continue

        if loc is None:
            if b not in goal_table_set:
                return False
        elif loc == "held":
            return False
        elif isinstance(loc, tuple):
            if len(loc) != 2 or loc[0] != "on" or (b, loc[1]) not in goal_on_set:
                return False
        else:
            return False

    for x, y in goal_on:
        if st["loc"][x] != ("on", y):
            return False

    for b in goal_table_set:
        if st["loc"][b] is not None:
            return False

    return True


def main():
    blocks = [f"block{i}" for i in range(1, 15)]

    initial_on = [
        ("block3", "block4"),
        ("block2", "block7"),
        ("block9", "block10"),
        ("block13", "block6"),
        ("block14", "block13"),
    ]

    initial_table = [
        "block4",
        "block12",
        "block5",
        "block7",
        "block1",
        "block8",
        "block10",
        "block11",
        "block6",
    ]

    goal_on = [
        ("block2", "block7"),
        ("block11", "block2"),
        ("block1", "block11"),
        ("block3", "block1"),
        ("block5", "block6"),
        ("block10", "block5"),
        ("block13", "block10"),
        ("block12", "block13"),
        ("block14", "block12"),
        ("block9", "block14"),
        ("block8", "block9"),
        ("block4", "block8"),
    ]

    goal_table = ["block7", "block6"]
    final_held = "block4"

    if not valid_config(blocks, initial_on, initial_table, None):
        print("No plan")
        return

    if not valid_config(blocks, goal_on, goal_table, final_held):
        print("No plan")
        return

    st = make_state(blocks, initial_on, initial_table, None)
    plan = []

    clear_to_table(st, blocks, plan)
    build_goal(st, goal_on, goal_table, plan)

    if final_held is not None:
        final_pickup(st, final_held, plan)

    if matches_goal(st, blocks, goal_on, goal_table, final_held):
        for action in plan:
            if len(action) == 2:
                print(f"({action[0]} {action[1]})")
            else:
                print(f"({action[0]} {action[1]} {action[2]})")
    else:
        print("No plan")


