import sys
from collections import deque


def main():
    blocks = ('a', 'b', 'c', 'd', 'e')
    pos = {b: i for i, b in enumerate(blocks)}

    # Initial state from the additional constraint:
    # one tower of every second letter, one tower of the remaining letters,
    # each tower alphabetical from the table upward.
    letters = 'abcde'
    towers = (letters[::2], letters[1::2])

    on = {b: None for b in blocks}
    for tower in towers:
        for i, b in enumerate(tower):
            on[b] = tower[i - 1] if i > 0 else None

    # Goal: a on b on c on d on e on table.
    goal_on = {
        'a': 'b',
        'b': 'c',
        'c': 'd',
        'd': 'e',
        'e': None,
    }

    def make_state(on_dict, held):
        return (tuple(on_dict[b] for b in blocks), held)

    def is_clear(state, b):
        on_tuple, held = state
        if b == held:
            return False
        for support in on_tuple:
            if support == b:
                return False
        return True

    def apply_action(state, action):
        on_list = list(state[0])
        held = state[1]
        kind = action[0]

        if kind == 'pickup':
            b = action[1]
            on_list[pos[b]] = None
            held = b

        elif kind == 'putdown':
            b = action[1]
            on_list[pos[b]] = None
            held = None

        elif kind == 'unstack':
            x, y = action[1], action[2]
            on_list[pos[x]] = None
            held = x

        elif kind == 'stack':
            x, y = action[1], action[2]
            on_list[pos[x]] = y
            held = None

        return (tuple(on_list), held)

    start = make_state(on, None)
    goal = make_state(goal_on, None)

    if start == goal:
        return

    parent = {start: None}
    queue = deque([start])
    found = False

    while queue:
        state = queue.popleft()

        if state == goal:
            found = True
            break

        on_tuple, held = state
        actions = []

        if held is None:
            for b in blocks:
                support = on_tuple[pos[b]]
                if support is not None and is_clear(state, b):
                    actions.append(('unstack', b, support))

            for b in blocks:
                if on_tuple[pos[b]] is None and is_clear(state, b):
                    actions.append(('pickup', b))
        else:
            actions.append(('putdown', held))
            for y in blocks:
                if is_clear(state, y):
                    actions.append(('stack', held, y))

        for action in actions:
            next_state = apply_action(state, action)
            if next_state not in parent:
                parent[next_state] = (state, action)
                queue.append(next_state)

    if not found or goal not in parent:
        print('No plan')
        return

    plan = []
    current = goal
    while parent[current] is not None:
        previous, action = parent[current]
        plan.append(action)
        current = previous

    plan.reverse()

    for action in plan:
        print('({})'.format(' '.join(action)))


if __name__ == '__main__':
    main()

import sys
from collections import deque

BLOCKS = tuple(range(1, 15))
MAX_HEIGHT = 5


def build_state(stacks):
    """
    State representation:
      held: 0 if empty, otherwise the held block id
      on:   on[b] = 0 if block b is on the table, otherwise the block under b
      on_top: on_top[b] = 0 if block b is clear, otherwise the block above b
    """
    on = [0] * 15
    on_top = [0] * 15

    for stack in stacks:
        for i, b in enumerate(stack):
            on[b] = 0 if i == 0 else stack[i - 1]
            on_top[b] = stack[i + 1] if i + 1 < len(stack) else 0

    return (0, tuple(on), tuple(on_top))


INITIAL = build_state([
    [3, 9, 4, 2, 14, 12, 7],
    [11, 8, 1, 6, 10, 13],
    [5],
])

GOAL = build_state([
    [6, 8],
    [5],
    [12],
    [1],
    [11, 14, 7],
    [4],
    [9, 3],
    [13],
    [2],
    [10],
])


def stack_heights(state):
    _, on, on_top = state
    heights = []

    for b in BLOCKS:
        if on[b] == 0:
            h = 0
            cur = b
            while cur != 0:
                h += 1
                cur = on_top[cur]
            heights.append(h)

    return heights


def valid_state(state, depth):
    # The initial configuration is exempt.  After any action, every stack
    # must be at most MAX_HEIGHT blocks high.
    if depth == 0:
        return True
    return max(stack_heights(state)) <= MAX_HEIGHT


def successors(state, depth):
    held, on, on_top = state

    # pickup X: X is on the table and clear, arm empty
    if held == 0:
        for b in BLOCKS:
            if on[b] == 0 and on_top[b] == 0:
                ns = (b, on, on_top)
                if valid_state(ns, depth + 1):
                    yield ("pickup", b), ns

    # putdown X: X is held
    if held != 0:
        ns = (0, on, on_top)
        if valid_state(ns, depth + 1):
            yield ("putdown", held), ns

    # unstack X Y: X is clear, X is on Y, arm empty
    if held == 0:
        for b in BLOCKS:
            c = on[b]
            if c != 0 and on_top[b] == 0:
                on2 = list(on)
                on_top2 = list(on_top)
                on2[b] = 0
                on_top2[c] = 0
                ns = (b, tuple(on2), tuple(on_top2))
                if valid_state(ns, depth + 1):
                    yield ("unstack", b, c), ns

    # stack X Y: X is held, Y is clear
    if held != 0:
        b = held
        for c in BLOCKS:
            if c != b and on_top[c] == 0:
                on2 = list(on)
                on_top2 = list(on_top)
                on2[b] = c
                on_top2[c] = b
                ns = (0, tuple(on2), tuple(on_top2))
                if valid_state(ns, depth + 1):
                    yield ("stack", b, c), ns


def action_text(action):
    if action[0] == "pickup":
        return f"(pickup block{action[1]})"
    if action[0] == "putdown":
        return f"(putdown block{action[1]})"
    if action[0] == "unstack":
        return f"(unstack block{action[1]} block{action[2]})"
    if action[0] == "stack":
        return f"(stack block{action[1]} block{action[2]})"
    raise ValueError("Unknown action")


def main():
    if INITIAL == GOAL:
        return

    queue = deque([(INITIAL, [])])
    seen = {INITIAL}

    while queue:
        state, plan = queue.popleft()

        for action, ns in successors(state, len(plan)):
            if ns in seen:
                continue

            if ns == GOAL:
                plan.append(action)
                sys.stdout.write("\n".join(action_text(a) for a in plan))
                return

            seen.add(ns)
            queue.append((ns, plan + [action]))

    sys.stdout.write("No plan")


if __name__ == "__main__":
    main()

import sys

def main():
    blocks = [f"block{i}" for i in range(1, 16)]
    on = {b: "table" for b in blocks}
    on["block15"] = "block2"
    on["block4"] = "block15"
    on["block13"] = "block1"
    on["block8"] = "block13"
    held = None
    actions = []

    def clear(b):
        return all(on[x] != b for x in blocks)

    def no_plan():
        sys.stdout.write("No plan\n")

    while True:
        if held is not None:
            no_plan()
            return
        movable = None
        for b in blocks:
            if on[b] != "table" and on[b] is not None and clear(b):
                movable = b
                break
        if movable is None:
            break
        under = on[movable]
        if under == "table" or under is None:
            no_plan()
            return
        actions.append(f"(unstack {movable} {under})")
        on[movable] = None
        held = movable
        actions.append(f"(putdown {movable})")
        on[movable] = "table"
        held = None

    goal_stacks = [
        ["block7"],
        ["block8", "block5", "block15", "block6", "block4", "block11", "block10", "block3", "block14"],
        ["block13", "block9", "block12", "block1", "block2"],
    ]

    if sorted(sum(goal_stacks, [])) != sorted(blocks):
        no_plan()
        return

    for stack in goal_stacks:
        prev = None
        for b in stack:
            if prev is None:
                if on[b] != "table" or not clear(b):
                    no_plan()
                    return
                prev = b
            else:
                if held is not None:
                    no_plan()
                    return
                if on[b] != "table" or not clear(b):
                    no_plan()
                    return
                actions.append(f"(pickup {b})")
                on[b] = None
                held = b
                if on[prev] is None or not clear(prev):
                    no_plan()
                    return
                actions.append(f"(stack {b} {prev})")
                on[b] = prev
                held = None
                prev = b

    if held is not None:
        no_plan()
        return

    goal_on = {b: "table" for b in blocks}
    for stack in goal_stacks:
        for i in range(1, len(stack)):
            goal_on[stack[i]] = stack[i - 1]

    if on != goal_on:
        no_plan()
        return

    sys.stdout.write("\n".join(actions))
    if actions:
        sys.stdout.write("\n")

if __name__ == "__main__":
    main()

import sys
from functools import lru_cache

N = 14
TABLE = -1
HELD = -2
INF = 10**9

initial = [TABLE] * N
for b in (11, 5, 3, 4, 12, 13, 10, 2):
    initial[b - 1] = TABLE
for top, bottom in ((1, 5), (6, 1), (9, 6), (14, 4), (8, 12), (7, 13)):
    initial[top - 1] = bottom - 1
start = tuple(initial)

goal = [TABLE] * N
for b in (14, 8, 1, 5, 7, 10, 12, 9, 3, 13):
    goal[b - 1] = TABLE
for top, bottom in ((2, 7), (4, 10), (11, 3), (6, 13)):
    goal[top - 1] = bottom - 1
goal = tuple(goal)

goal_tops = {i for i in range(N) if goal[i] != TABLE}
goal_bases = {goal[i] for i in range(N) if goal[i] != TABLE}


def is_clear(state, b):
    for i in range(N):
        if state[i] == b:
            return False
    return True


@lru_cache(maxsize=None)
def heuristic(state):
    must = [False] * N
    for i in range(N):
        if state[i] != goal[i]:
            must[i] = True

    changed = True
    while changed:
        changed = False
        for i in range(N):
            if not must[i]:
                sup = state[i]
                if 0 <= sup < N and must[sup]:
                    must[i] = True
                    changed = True

    count = 0
    held = False
    for i in range(N):
        if must[i]:
            count += 1
        if state[i] == HELD:
            held = True

    return 2 * count - (1 if held else 0)


def neighbors(state):
    held = None
    for i, s in enumerate(state):
        if s == HELD:
            held = i
            break

    res = []

    if held is None:
        for b in range(N):
            sup = state[b]
            if sup == TABLE:
                if is_clear(state, b):
                    lst = list(state)
                    lst[b] = HELD
                    res.append((("pickup", b, None), tuple(lst)))
            elif sup != HELD:
                if is_clear(state, b):
                    lst = list(state)
                    lst[b] = HELD
                    res.append((("unstack", b, sup), tuple(lst)))
    else:
        b = held

        lst = list(state)
        lst[b] = TABLE
        res.append((("putdown", b, None), tuple(lst)))

        for y in range(N):
            if y == b or state[y] == HELD:
                continue
            if is_clear(state, y):
                lst = list(state)
                lst[b] = y
                res.append((("stack", b, y), tuple(lst)))

    return res


def action_score(action, state, new_state):
    kind = action[0]

    if kind == "putdown" or kind == "stack":
        b = action[1]
        return 0 if new_state[b] == goal[b] else 10

    b = action[1]
    sup = state[b]

    if b in goal_bases:
        return 1
    if 0 <= sup < N and sup in goal_bases:
        return 2
    if b in goal_tops:
        return 3
    if 0 <= sup < N and sup in goal_tops:
        return 4
    return 5


def dfs(state, g, threshold, path, path_set):
    h = heuristic(state)
    if g + h > threshold:
        return None, g + h

    if state == goal:
        return path.copy(), None

    candidates = []
    min_cut = INF

    for action, new_state in neighbors(state):
        if new_state in path_set:
            continue

        new_h = heuristic(new_state)
        fg = g + 1 + new_h

        if fg > threshold:
            if fg < min_cut:
                min_cut = fg
            continue

        score = action_score(action, state, new_state)
        candidates.append((new_h, score, action, new_state))

    candidates.sort(key=lambda x: (x[0], x[1]))

    for _, _, action, new_state in candidates:
        path.append(action)
        path_set.add(new_state)

        result, cut = dfs(new_state, g + 1, threshold, path, path_set)

        path_set.remove(new_state)
        path.pop()

        if result is not None:
            return result, None

        if cut < min_cut:
            min_cut = cut

    return None, min_cut


def main():
    sys.setrecursionlimit(10000)

    if start == goal:
        return

    threshold = heuristic(start)

    for _ in range(1000):
        path = []
        path_set = {start}
        plan, cutoff = dfs(start, 0, threshold, path, path_set)

        if plan is not None:
            out = []
            for action in plan:
                if action[0] == "pickup":
                    out.append(f"(pickup block{action[1] + 1})")
                elif action[0] == "putdown":
                    out.append(f"(putdown block{action[1] + 1})")
                elif action[0] == "unstack":
                    out.append(f"(unstack block{action[1] + 1} block{action[2] + 1})")
                else:
                    out.append(f"(stack block{action[1] + 1} block{action[2] + 1})")
            sys.stdout.write("\n".join(out))
            return

        if cutoff == INF:
            sys.stdout.write("No plan")
            return

        if cutoff <= threshold:
            threshold += 1
        else:
            threshold = cutoff

    sys.stdout.write("No plan")


if __name__ == "__main__":
    main()

import heapq
import itertools

N = 12
TABLE = -1
HELD = -2
IMMOBILE = {3, 8, 11}

goal_on = [TABLE] * N
goal_on[11] = TABLE
goal_on[8] = TABLE
goal_on[10] = 8
goal_on[2] = 10
goal_on[3] = TABLE
goal_on[5] = 3
goal_on[9] = 5
goal_on[0] = 9
goal_on[6] = 0
goal_on[4] = 6
goal_on[7] = 4
goal_on[1] = 7

initial_on = [TABLE] * N
for i in (6, 8, 3, 5, 11, 7, 1, 2):
    initial_on[i] = TABLE
initial_on[4] = 3
initial_on[10] = 4
initial_on[0] = 9
initial_on[9] = TABLE


def make_action(code, x, y=0):
    return code * 144 + x * 12 + y


def encode(held, on):
    return bytes([held + 1]) + bytes(v + 2 for v in on)


def compute_must(on):
    must = [False] * N
    for i in range(N):
        if on[i] != goal_on[i]:
            must[i] = True

    above = [[] for _ in range(N)]
    for i, s in enumerate(on):
        if s >= 0:
            above[s].append(i)

    q = [i for i in range(N) if must[i]]
    head = 0
    while head < len(q):
        b = q[head]
        head += 1
        for a in above[b]:
            if not must[a]:
                must[a] = True
                q.append(a)

    return must


def heuristic(held, on):
    must = compute_must(on)

    top = [-1] * N
    clear = [True] * N
    for i, s in enumerate(on):
        if s >= 0:
            top[s] = i
            clear[s] = False

    h = 0
    for i in range(N):
        if not must[i]:
            continue

        cur = on[i]
        goal = goal_on[i]

        if i == held:
            lb = 1
        elif cur != goal:
            lb = 2
        else:
            lb = 4

        if goal >= 0 and cur != goal:
            need_wait = (not clear[goal]) or must[goal]
            if need_wait:
                if i == held:
                    lb += 2
                elif cur >= 0:
                    forbidden_goal = goal if must[goal] else -1
                    forbidden_top = top[goal] if not clear[goal] else -1
                    s = cur
                    while s >= 0:
                        if s == forbidden_goal or s == forbidden_top:
                            lb += 2
                            break
                        s = on[s]

        h += lb

    return h


def constructive_plan():
    state = initial_on[:]
    actions = []

    while True:
        clear = [True] * N
        for i, s in enumerate(state):
            if s >= 0:
                clear[s] = False

        moved = False
        for x in range(N):
            if state[x] >= 0 and clear[x] and x not in IMMOBILE:
                y = state[x]
                actions.append(make_action(3, x, y))
                state[x] = HELD
                actions.append(make_action(1, x))
                state[x] = TABLE
                moved = True
                break

        if not moved:
            break

    towers = [
        [8, 10, 2],
        [3, 5, 9, 0, 6, 4, 7, 1],
        [11],
    ]

    for tower in towers:
        for idx in range(1, len(tower)):
            b = tower[idx]
            s = tower[idx - 1]
            actions.append(make_action(0, b))
            state[b] = HELD
            actions.append(make_action(2, b, s))
            state[b] = s

    return actions


def reconstruct(key, info):
    actions = []
    cur = key
    while True:
        _, prev, action = info[cur]
        if action is None:
            break
        actions.append(action)
        cur = prev
    actions.reverse()
    return actions


def validate(actions):
    on = initial_on[:]
    held = -1

    for a in actions:
        code = a // 144
        x = (a // 12) % 12
        y = a % 12

        if code == 0:
            if held != -1 or on[x] != TABLE or x in IMMOBILE:
                return False
            for z in range(N):
                if on[z] == x:
                    return False
            on[x] = HELD
            held = x

        elif code == 1:
            if held != x or x in IMMOBILE:
                return False
            on[x] = TABLE
            held = -1

        elif code == 2:
            if held != x or x in IMMOBILE or y == x or on[y] == HELD:
                return False
            for z in range(N):
                if on[z] == y:
                    return False
            on[x] = y
            held = -1

        elif code == 3:
            if held != -1 or on[x] != y or x in IMMOBILE:
                return False
            for z in range(N):
                if on[z] == x:
                    return False
            on[x] = HELD
            held = x

        else:
            return False

    return held == -1 and on == goal_on


def solve():
    start_key = encode(-1, initial_on)
    goal_key = encode(-1, goal_on)

    best_plan = constructive_plan()
    best_len = len(best_plan)

    h0 = heuristic(-1, initial_on)
    info = {start_key: (0, None, None)}
    counter = itertools.count()
    heap = [(h0, 0, next(counter), start_key)]

    nodes = 0
    limit = 1000000

    while heap:
        f, g, _, key = heapq.heappop(heap)

        if g != info[key][0]:
            continue

        if f >= best_len:
            break

        if key == goal_key:
            best_plan = reconstruct(key, info)
            best_len = g
            break

        nodes += 1
        if nodes > limit:
            break

        held = key[0] - 1
        on = [b - 2 for b in key[1:]]

        must = compute_must(on)

        clear = [True] * N
        for i, s in enumerate(on):
            if s >= 0:
                clear[s] = False

        if held == -1:
            for x in range(N):
                if not must[x] or x in IMMOBILE:
                    continue

                if on[x] == TABLE and clear[x]:
                    new_on = on.copy()
                    new_on[x] = HELD
                    new_held = x
                    action = make_action(0, x)
                    ng = g + 1

                    if ng < best_len:
                        h = heuristic(new_held, new_on)
                        if ng + h < best_len:
                            new_key = encode(new_held, new_on)
                            old = info.get(new_key)
                            if old is None or old[0] > ng:
                                info[new_key] = (ng, key, action)
                                heapq.heappush(heap, (ng + h, ng, next(counter), new_key))

                elif on[x] >= 0 and clear[x]:
                    y = on[x]
                    new_on = on.copy()
                    new_on[x] = HELD
                    new_held = x
                    action = make_action(3, x, y)
                    ng = g + 1

                    if ng < best_len:
                        h = heuristic(new_held, new_on)
                        if ng + h < best_len:
                            new_key = encode(new_held, new_on)
                            old = info.get(new_key)
                            if old is None or old[0] > ng:
                                info[new_key] = (ng, key, action)
                                heapq.heappush(heap, (ng + h, ng, next(counter), new_key))

        else:
            x = held
            if x in IMMOBILE:
                continue

            new_on = on.copy()
            new_on[x] = TABLE
            new_held = -1
            action = make_action(1, x)
            ng = g + 1

            if ng < best_len:
                h = heuristic(new_held, new_on)
                if ng + h < best_len:
                    new_key = encode(new_held, new_on)
                    old = info.get(new_key)
                    if old is None or old[0] > ng:
                        info[new_key] = (ng, key, action)
                        heapq.heappush(heap, (ng + h, ng, next(counter), new_key))

            y = goal_on[x]
            if y >= 0 and y != x and on[y] != HELD and clear[y] and not must[y]:
                new_on = on.copy()
                new_on[x] = y
                new_held = -1
                action = make_action(2, x, y)
                ng = g + 1

                if ng < best_len:
                    h = heuristic(new_held, new_on)
                    if ng + h < best_len:
                        new_key = encode(new_held, new_on)
                        old = info.get(new_key)
                        if old is None or old[0] > ng:
                            info[new_key] = (ng, key, action)
                            heapq.heappush(heap, (ng + h, ng, next(counter), new_key))

    return best_plan


def action_to_str(a):
    code = a // 144
    x = (a // 12) % 12
    y = a % 12

    if code == 0:
        return f"(pickup block{x + 1})"
    if code == 1:
        return f"(putdown block{x + 1})"
    if code == 2:
        return f"(stack block{x + 1} block{y + 1})"
    return f"(unstack block{x + 1} block{y + 1})"


def main():
    plan = solve()
    if not plan or not validate(plan):
        print("No plan")
    else:
        for a in plan:
            print(action_to_str(a))


if __name__ == "__main__":
    main()

BLOCKS = list(range(1, 15))
INITIAL_STACKS = [[10, 6, 8], [13, 2, 9, 7], [4, 1, 14, 5, 3, 11]]
GOAL_STACKS = [[13, 3, 10], [4, 8, 11], [6, 1, 7, 2, 12, 9, 5, 14]]


def make_state(stacks):
    on = [0] * 15
    clear = [True] * 15
    for stack in stacks:
        for i in range(len(stack) - 1):
            on[stack[i + 1]] = stack[i]
            clear[stack[i]] = False
    return (0, tuple(on), tuple(clear))


def satisfies_goal(stacks):
    if len(stacks) != len(GOAL_STACKS):
        return False
    goal = [tuple(s) for s in GOAL_STACKS]
    for s in goal:
        if s not in stacks:
            return False
    return True


def satisfies_additional(stacks):
    if len(stacks) != 2:
        return False
    for s in stacks:
        if not s:
            return False
        for i in range(len(s) - 1):
            if s[i] >= s[i + 1]:
                return False

    def all_mult(s):
        return all(x % 5 == 0 for x in s)

    def no_mult(s):
        return all(x % 5 != 0 for x in s)

    return (all_mult(stacks[0]) and no_mult(stacks[1])) or (
        all_mult(stacks[1]) and no_mult(stacks[0])
    )


def find_target():
    n = len(BLOCKS)
    for mask in range(1, 1 << n):
        if not (mask & 1):
            continue
        tower0 = tuple(b for b in BLOCKS if mask & (1 << (b - 1)))
        tower1 = tuple(b for b in BLOCKS if not (mask & (1 << (b - 1))))
        if not tower0 or not tower1:
            continue
        stacks = (tower0, tower1)
        if satisfies_goal(stacks) and satisfies_additional(stacks):
            return stacks
    return None


def plan_to_stacks(initial_state, target_stacks):
    _, on, clear = initial_state
    on = list(on)
    clear = list(clear)
    actions = []

    while True:
        moved = False
        for b in range(1, 15):
            if on[b] != 0 and clear[b]:
                below = on[b]
                actions.append(f"(unstack block{b} block{below})")
                on[b] = 0
                clear[b] = True
                clear[below] = True
                actions.append(f"(putdown block{b})")
                moved = True
                break
        if not moved:
            break

    for stack in target_stacks:
        for i, b in enumerate(stack):
            while on[b] != 0 or not clear[b]:
                cur = b
                while True:
                    above = 0
                    for c in range(1, 15):
                        if on[c] == cur:
                            above = c
                            break
                    if above == 0:
                        break
                    cur = above

                if cur != b:
                    below_cur = on[cur]
                    actions.append(f"(unstack block{cur} block{below_cur})")
                    on[cur] = 0
                    clear[cur] = True
                    clear[below_cur] = True
                    actions.append(f"(putdown block{cur})")
                    on[cur] = 0
                    clear[cur] = True
                else:
                    below_b = on[b]
                    actions.append(f"(unstack block{b} block{below_b})")
                    on[b] = 0
                    clear[b] = True
                    clear[below_b] = True
                    actions.append(f"(putdown block{b})")
                    on[b] = 0
                    clear[b] = True
                    break

            if i == 0:
                actions.append(f"(pickup block{b})")
                on[b] = 0
                clear[b] = True
                actions.append(f"(putdown block{b})")
                on[b] = 0
                clear[b] = True
            else:
                below = stack[i - 1]
                actions.append(f"(pickup block{b})")
                on[b] = 0
                clear[b] = True
                actions.append(f"(stack block{b} block{below})")
                on[b] = below
                clear[b] = False
                clear[below] = False

    return actions


def main():
    initial = make_state(INITIAL_STACKS)
    target = find_target()
    if target is None:
        print("No plan")
        return
    for action in plan_to_stacks(initial, target):
        print(action)


main()

import heapq

TABLE = 0
HELD = -1
BLOCKS = tuple(range(1, 13))


def block_name(b):
    return f"block{b}"


def build_goal_on():
    goal = {b: TABLE for b in BLOCKS}
    for top, bottom in [
        (9, 6),
        (3, 2),
        (7, 3),
        (4, 7),
        (11, 4),
        (12, 11),
        (8, 12),
        (1, 8),
        (10, 1),
        (5, 10),
    ]:
        goal[top] = bottom
    return goal


GOAL_ON_DICT = build_goal_on()
GOAL_ON = tuple([TABLE] + [GOAL_ON_DICT[b] for b in range(1, 13)])


def allowed_stack(x, y):
    return not (x % 2 == 1 and y % 2 == 0)


def goal_is_valid():
    for b in BLOCKS:
        support = GOAL_ON_DICT[b]
        if support != TABLE and not allowed_stack(b, support):
            return False
    return True


def is_clear(mask, b):
    return (mask >> b) & 1


def successors(state):
    on, clear_mask, holding = state
    results = []

    if holding == 0:
        for x in BLOCKS:
            if not is_clear(clear_mask, x):
                continue

            if on[x] == TABLE:
                new_on = list(on)
                new_on[x] = HELD
                results.append(
                    (
                        f"pickup {block_name(x)}",
                        (tuple(new_on), clear_mask, x),
                    )
                )
            elif on[x] != HELD:
                y = on[x]
                new_on = list(on)
                new_on[x] = HELD
                new_clear = clear_mask | (1 << y)
                results.append(
                    (
                        f"unstack {block_name(x)} {block_name(y)}",
                        (tuple(new_on), new_clear, x),
                    )
                )
    else:
        x = holding
        if is_clear(clear_mask, x):
            new_on = list(on)
            new_on[x] = TABLE
            results.append(
                (
                    f"putdown {block_name(x)}",
                    (tuple(new_on), clear_mask, 0),
                )
            )

            for y in BLOCKS:
                if y == x:
                    continue
                if on[y] == HELD:
                    continue
                if not is_clear(clear_mask, y):
                    continue
                if not allowed_stack(x, y):
                    continue

                new_on = list(on)
                new_on[x] = y
                new_clear = (clear_mask & ~(1 << y)) | (1 << x)
                results.append(
                    (
                        f"stack {block_name(x)} {block_name(y)}",
                        (tuple(new_on), new_clear, 0),
                    )
                )

    return results


def heuristic(state):
    on = state[0]
    h = 0
    for b in BLOCKS:
        current = on[b]
        target = GOAL_ON[b]
        if current == target:
            continue
        if current == HELD:
            h += 1
        else:
            h += 2
    return h


def main():
    if not goal_is_valid():
        print("No plan")
        return

    start_on = tuple([TABLE] + [TABLE] * 12)
    start_clear = 0
    for b in BLOCKS:
        start_clear |= 1 << b
    start = (start_on, start_clear, 0)

    if start[0] == GOAL_ON and start[2] == 0:
        return

    best_g = {start: 0}
    parent = {start: None}
    counter = 0
    heap = [(heuristic(start), 0, counter, start)]
    counter += 1

    while heap:
        _, g, _, state = heapq.heappop(heap)

        if g != best_g.get(state):
            continue

        if state[0] == GOAL_ON and state[2] == 0:
            actions = []
            cur = state
            while parent[cur] is not None:
                prev, action = parent[cur]
