goal_state = (tuple(goal_on), 0)


def is_clear(on, held, b):
    if held == b:
        return True
    for z in range(1, N + 1):
        if z != held and on[z] == b:
            return False
    return True


def max_stack_height(on, held):
    memo = {}

    def height(b):
        if b in memo:
            return memo[b]
        if b == held:
            val = 0
        elif on[b] == 0:
            val = 1
        else:
            val = 1 + height(on[b])
        memo[b] = val
        return val

    best = 0
    for b in range(1, N + 1):
        if b != held:
            best = max(best, height(b))
    return best


def successors(state):
    on, held = state
    result = []

    if held == 0:
        for x in range(1, N + 1):
            if on[x] == 0 and is_clear(on, held, x):
                new_on = list(on)
                new_on[x] = 0
                result.append((
                    f"(pickup {block_name(x)})",
                    (tuple(new_on), x)
                ))
            elif on[x] != 0 and is_clear(on, held, x):
                y = on[x]
                new_on = list(on)
                new_on[x] = 0
                result.append((
                    f"(unstack {block_name(x)} {block_name(y)})",
                    (tuple(new_on), x)
                ))
    else:
        x = held

        new_on = list(on)
        new_on[x] = 0
        result.append((
            f"(putdown {block_name(x)})",
            (tuple(new_on), 0)
        ))

        for y in range(1, N + 1):
            if y == x:
                continue
            if is_clear(on, held, y):
                new_on = list(on)
                new_on[x] = y
                result.append((
                    f"(stack {block_name(x)} {block_name(y)})",
                    (tuple(new_on), 0)
                ))

    return result


def solve():
    if initial_state == goal_state:
        return

    parent = {initial_state: None}
    action = {initial_state: None}
    depth = {initial_state: 0}
    queue = deque([initial_state])

    while queue:
        state = queue.popleft()

        if state == goal_state:
            plan = []
            cur = state
            while parent[cur] is not None:
                plan.append(action[cur])
                cur = parent[cur]
            plan.reverse()
            if plan:
                print("\n".join(plan))
            return

        for act, nxt in successors(state):
            nd = depth[state] + 1

            if nd > 0 and max_stack_height(nxt[0], nxt[1]) > 2:
                continue

            if nxt in parent:
                continue

            parent[nxt] = state
            action[nxt] = act
            depth[nxt] = nd
            queue.append(nxt)

    print("No plan")


