import sys

def main():
    blocks = [f"block{i}" for i in range(1, 11)]
    table = "table"

    support = {b: table for b in blocks}
    support["block8"] = "block5"

    goal = {b: table for b in blocks}
    goal["block3"] = "block2"
    goal["block5"] = "block3"
    goal["block1"] = "block5"
    goal["block7"] = "block1"
    goal["block8"] = "block7"
    goal["block9"] = "block6"
    goal["block10"] = "block9"
    goal["block4"] = "block10"

    hand = None
    plan = []
    ok = True
    index = {b: i for i, b in enumerate(blocks)}

    def on(b):
        return [x for x in blocks if support[x] == b]

    def clear(b):
        return not on(b)

    def apply(action, args):
        nonlocal hand, ok
        if not ok:
            return
        if action == "pickup":
            b = args[0]
            if hand is None and support[b] == table and clear(b):
                hand = b
                support[b] = None
            else:
                ok = False
        elif action == "putdown":
            b = args[0]
            if hand == b and clear(b):
                hand = None
                support[b] = table
            else:
                ok = False
        elif action == "unstack":
            x, y = args
            if hand is None and support[x] == y and clear(x):
                hand = x
                support[x] = None
            else:
                ok = False
        elif action == "stack":
            x, y = args
            if hand == x and clear(x) and clear(y) and support[y] is not None:
                hand = None
                support[x] = y
            else:
                ok = False
        else:
            ok = False

    while ok:
        moved = False
        for b in blocks:
            if support[b] not in (table, None):
                if clear(b):
                    below = support[b]
                    plan.append(f"(unstack {b} {below})")
                    apply("unstack", (b, below))
                    plan.append(f"(putdown {b})")
                    apply("putdown", (b,))
                    moved = True
                    break
        if not moved:
            if any(support[b] not in (table, None) for b in blocks):
                ok = False
            break

    depth = {}

    def get_depth(b, seen):
        nonlocal ok
        if b in depth:
            return depth[b]
        below = goal[b]
        if below == table:
            depth[b] = 0
            return 0
        if below not in support or b in seen:
            ok = False
            return -1
        d = get_depth(below, seen | {b})
        if d < 0:
            return -1
        depth[b] = d + 1
        return d + 1

    for b in blocks:
        if not ok:
            break
        get_depth(b, set())

    if ok:
        placed = {b for b in blocks if goal[b] == table}
        to_place = [b for b in blocks if goal[b] != table]
        while to_place:
            candidates = [b for b in to_place if goal[b] in placed]
            if not candidates:
                ok = False
                break
            best = min(candidates, key=lambda b: (-depth[b], index[b]))
            below = goal[best]
            if (support[best] != table or not clear(best) or not clear(below)
                    or support[below] is None):
                ok = False
                break
            plan.append(f"(pickup {best})")
            apply("pickup", (best,))
            plan.append(f"(stack {best} {below})")
            apply("stack", (best, below))
            if not ok:
                break
            to_place.remove(best)
            placed.add(best)

    if ok and hand is None and all(support[b] == goal[b] for b in blocks):
        if plan:
            sys.stdout.write("\n".join(plan) + "\n")
    else:
        sys.stdout.write("No plan\n")

