from collections import deque

BLOCKS = ("block1", "block2", "block3")
N = len(BLOCKS)
TABLE = -2
HELD = -1
LIMIT = 5


def is_clear(support, i):
    return all(s != i for s in support)


def constraint_ok(support, depth):
    if depth == 0:
        return True

    for bottom in range(N):
        if support[bottom] != TABLE:
            continue

        total = 0
        current = bottom

        while True:
            total += current + 1
            if total > LIMIT:
                return False

            top = -1
            for b in range(N):
                if support[b] == current:
                    top = b
                    break

            if top == -1:
                break

            current = top

    return True


def successors(state):
    support, held = state

    for i in range(N):
        if held == -1 and support[i] == TABLE and is_clear(support, i):
            ns = list(support)
            ns[i] = HELD
            yield (tuple(ns), i), ("pickup", BLOCKS[i])

        if held == i:
            ns = list(support)
            ns[i] = TABLE
            yield (tuple(ns), -1), ("putdown", BLOCKS[i])

        if held == -1 and 0 <= support[i] < N and is_clear(support, i):
            j = support[i]
            ns = list(support)
            ns[i] = HELD
            yield (tuple(ns), i), ("unstack", BLOCKS[i], BLOCKS[j])

    if held != -1:
        for j in range(N):
            if j == held or support[j] == HELD:
                continue
            if is_clear(support, j):
                ns = list(support)
                ns[held] = j
                yield (tuple(ns), -1), ("stack", BLOCKS[held], BLOCKS[j])


def main():
    initial = ((1, TABLE, TABLE), -1)
    goal = ((1, 2, TABLE), -1)

    if initial == goal:
        return

    parent = {initial: (None, None)}
    depth = {initial: 0}
    queue = deque([initial])

    while queue:
        state = queue.popleft()

        if state == goal:
            actions = []
            current = state
            while parent[current][0] is not None:
                prev, action = parent[current]
                actions.append(action)
                current = prev

            for action in reversed(actions):
                print(f"({action[0]} {' '.join(action[1:])})")
            return

        for next_state, action in successors(state):
            if next_state in parent:
                continue

            d = depth[state] + 1
            if not constraint_ok(next_state[0], d):
                continue

            parent[next_state] = (state, action)
            depth[next_state] = d
            queue.append(next_state)

    print("No plan")


if __name__ == "__main__":
    main()

BLOCKS = [chr(ord('a') + i) for i in range(14)]
GOAL = BLOCKS

INITIAL_ON = {
    'a': None, 'b': 'a',
    'c': None, 'd': 'c',
    'e': None, 'f': 'e',
    'g': None, 'h': 'g',
    'i': None, 'j': 'i',
    'k': None, 'l': 'k',
    'm': None, 'n': 'm',
}

START_HELD = 'b'


def make_state(on):
    on = dict(on)
    top = {b: None for b in BLOCKS}
    for b, s in on.items():
        if s is not None:
            top[s] = b
    return {'on': on, 'top': top, 'arm': None}


def apply_action(state, action):
    kind = action[0]
    on = state['on']
    top = state['top']
    arm = state['arm']

    if kind == 'pickup':
        x = action[1]
        if arm is not None or on[x] is not None or top[x] is not None:
            return None
        on2 = on.copy()
        top2 = top.copy()
        on2[x] = None
        return {'on': on2, 'top': top2, 'arm': x}

    if kind == 'putdown':
        x = action[1]
        if arm != x or on[x] is not None or top[x] is not None:
            return None
        on2 = on.copy()
        top2 = top.copy()
        on2[x] = None
        return {'on': on2, 'top': top2, 'arm': None}

    if kind == 'unstack':
        x, y = action[1], action[2]
        if arm is not None or on[x] != y or top[x] is not None:
            return None
        on2 = on.copy()
        top2 = top.copy()
        on2[x] = None
        top2[y] = None
        return {'on': on2, 'top': top2, 'arm': x}

    if kind == 'stack':
        x, y = action[1], action[2]
        if arm != x or x == y or on[x] is not None or top[x] is not None or top[y] is not None:
            return None
        on2 = on.copy()
        top2 = top.copy()
        on2[x] = y
        top2[y] = x
        return {'on': on2, 'top': top2, 'arm': None}

    return None


def is_goal(state):
    if state['arm'] is not None:
        return False

    on = state['on']
    top = state['top']

    for i, b in enumerate(GOAL):
        expected = GOAL[i - 1] if i > 0 else None
        if on[b] != expected:
            return False
        if i > 0 and top[expected] != b:
            return False

    return top[GOAL[-1]] is None


def add_action(actions, state, action):
    new_state = apply_action(state, action)
    if new_state is None:
        return None
    actions.append(action)
    return new_state


def ensure_clear(actions, state, x):
    while state['top'][x] is not None:
        if state['arm'] == x:
            return None

        y = state['top'][x]

        state = ensure_clear(actions, state, y)
        if state is None:
            return None

        if state['arm'] is not None:
            state = add_action(actions, state, ('putdown', state['arm']))
            if state is None:
                return None

        state = add_action(actions, state, ('unstack', y, x))
        if state is None:
            return None

        state = add_action(actions, state, ('putdown', y))
        if state is None:
            return None

    return state


def solve():
    state = make_state(INITIAL_ON)
    actions = []

    # The plan must start by holding block b.
    if state['arm'] != START_HELD:
        if state['top'][START_HELD] is not None or state['arm'] is not None:
            return None

        support = state['on'][START_HELD]
        if support is None:
            action = ('pickup', START_HELD)
        else:
            action = ('unstack', START_HELD, support)

        state = add_action(actions, state, action)
        if state is None:
            return None

    # Place the initially held block b on a.
    if state['arm'] == START_HELD:
        state = ensure_clear(actions, state, 'a')
        if state is None:
            return None

        if state['arm'] != START_HELD:
            state = add_action(actions, state, ('pickup', START_HELD))
            if state is None:
                return None

        state = add_action(actions, state, ('stack', START_HELD, 'a'))
        if state is None:
            return None

    # Build the goal tower from bottom to top.
    for idx in range(1, len(GOAL)):
        target = GOAL[idx]
        support = GOAL[idx - 1]

        state = ensure_clear(actions, state, target)
        if state is None:
            return None

        if state['on'][target] == support and state['top'][support] == target:
            continue

        if state['arm'] == target:
            if state['top'][support] is not None:
                state = add_action(actions, state, ('putdown', target))
                if state is None:
                    return None

                state = ensure_clear(actions, state, support)
                if state is None:
                    return None

                state = add_action(actions, state, ('pickup', target))
                if state is None:
                    return None

            state = add_action(actions, state, ('stack', target, support))
            if state is None:
                return None
        else:
            if state['arm'] is not None:
                state = add_action(actions, state, ('putdown', state['arm']))
                if state is None:
                    return None

            if state['on'][target] is None:
                state = add_action(actions, state, ('pickup', target))
            else:
                state = add_action(actions, state, ('unstack', target, state['on'][target]))

            if state is None:
                return None

            if state['top'][support] is not None:
                state = add_action(actions, state, ('putdown', target))
                if state is None:
                    return None

                state = ensure_clear(actions, state, support)
                if state is None:
                    return None

                state = add_action(actions, state, ('pickup', target))
                if state is None:
                    return None

            state = add_action(actions, state, ('stack', target, support))
            if state is None:
                return None

    if is_goal(state):
        return actions

    return None


def main():
    plan = solve()

    if plan is None:
        print("No plan")
        return

    # Validate the generated plan before printing it.
    state = make_state(INITIAL_ON)
    for i, action in enumerate(plan):
        state = apply_action(state, action)
        if state is None:
            print("No plan")
            return
        if i == 0 and state['arm'] != START_HELD:
            print("No plan")
            return

    if not is_goal(state):
        print("No plan")
        return

    for action in plan:
        if len(action) == 2:
            print(f"({action[0]} {action[1]})")
        else:
            print(f"({action[0]} {action[1]} {action[2]})")


