        while support != 0 and support != -1:
            above[support] += WEIGHT[b]
            support = on[support]
    return above


def weight_ok(on, arm):
    above = above_weights(on, arm)
    for b in BLOCKS:
        if above[b] > WEIGHT[b]:
            return False
    return True


