                new_on[b] = -1
                yield tuple(new_on), b, f"(unstack block{b} block{below})"
    else:
        b = arm
        if on[b] != -1:
            return

        new_on = list(on)
        new_on[b] = 0
        yield tuple(new_on), 0, f"(putdown block{b})"

