import sys

def main():
    blocks = [f"block{i}" for i in range(1, 13)]

    goal_on = {
        "block1": "block8",
        "block2": "table",
        "block3": "block2",
        "block4": "block7",
        "block5": "block10",
        "block6": "table",
        "block7": "block3",
        "block8": "block12",
        "block9": "block6",
        "block10": "block1",
        "block11": "block4",
        "block12": "block11",
    }

    goal_above = {b: None for b in blocks}
    for b, support in goal_on.items():
        if support != "table":
            if goal_above[support] is not None:
                print("No plan")
                return
            goal_above[support] = b

    on = {b: "table" for b in blocks}
    above = {b: None for b in blocks}
    arm = None
    plan = []

    def apply_action(action, args):
        nonlocal arm

        if action == "pickup":
            (x,) = args
            if arm is not None or on[x] != "table" or above[x] is not None:
                return False
            arm = x
            on[x] = None
            above[x] = None

        elif action == "putdown":
            (x,) = args
            if arm != x or on[x] is not None or above[x] is not None:
                return False
            arm = None
            on[x] = "table"
            above[x] = None

        elif action == "unstack":
            x, y = args
            if (
                arm is not None
                or on[x] != y
                or above[x] is not None
                or y not in on
                or on[y] is None
            ):
                return False
            arm = x
            on[x] = None
            above[x] = None
            above[y] = None

        elif action == "stack":
            x, y = args
            if (
                arm != x
                or on[x] is not None
                or above[x] is not None
                or y not in on
                or on[y] is None
                or above[y] is not None
            ):
                return False
            arm = None
            on[x] = y
            above[x] = None
            above[y] = x

        else:
            return False

        plan.append(f"({action} {' '.join(args)})")
        return True

    depth = {}

    def compute_depth(b):
        if b in depth:
            return depth[b]
        support = goal_on[b]
        if support == "table":
            d = 1
        else:
            d = compute_depth(support) + 1
        depth[b] = d
        return d

    for b in blocks:
        compute_depth(b)

    order = sorted(blocks, key=lambda b: depth[b])
    ok = True

    for b in order:
        if above[b] is not None:
            ok = False
            break

        support = goal_on[b]

        if support == "table":
            if on[b] != "table":
                if on[b] is None:
                    if not apply_action("putdown", (b,)):
                        ok = False
                        break
                else:
                    if not apply_action("unstack", (b, on[b])):
                        ok = False
                        break
                    if not apply_action("putdown", (b,)):
                        ok = False
                        break
        else:
            if on[b] != support:
                if on[b] is None:
                    if not apply_action("putdown", (b,)):
                        ok = False
                        break
                elif on[b] == "table":
                    if not apply_action("pickup", (b,)):
                        ok = False
                        break
                else:
                    if not apply_action("unstack", (b, on[b])):
                        ok = False
                        break

                if arm is None:
                    if on[b] != "table":
                        ok = False
                        break
                    if not apply_action("pickup", (b,)):
                        ok = False
                        break

                if not apply_action("stack", (b, support)):
                    ok = False
                    break

        if above[b] is not None:
            ok = False
            break

    if (
        ok
        and arm is None
        and all(on[b] == goal_on[b] for b in blocks)
        and all(above[b] == goal_above[b] for b in blocks)
    ):
        for line in plan:
            print(line)
    else:
        print("No plan")

