from collections import deque

blocks = [f"block{i}" for i in range(1, 7)]

initial = {
    "block1": "table",
    "block2": "block6",
    "block3": "block4",
    "block4": "table",
    "block5": "table",
    "block6": "table",
}

goal = {
    "block1": "table",
    "block2": "table",
    "block3": "table",
    "block4": "block3",
    "block5": "table",
    "block6": "table",
}

start_state = tuple(initial[b] for b in blocks)
goal_state = tuple(goal[b] for b in blocks)


def held_block(loc):
    for b, l in zip(blocks, loc):
        if l == "held":
            return b
    return None


def is_clear(loc, b):
    return all(l != b for l in loc)


def successors(loc, stacked):
    held = held_block(loc)
    result = []

    if held is None:
        for i, b in enumerate(blocks):
            if loc[i] == "table" and is_clear(loc, b):
                nxt = list(loc)
                nxt[i] = "held"
                result.append((tuple(nxt), stacked, f"(pickup {b})"))

    if held is not None:
        i = blocks.index(held)
        nxt = list(loc)
        nxt[i] = "table"
        result.append((tuple(nxt), stacked, f"(putdown {held})"))

    if held is None:
        for i, b in enumerate(blocks):
            support = loc[i]
            if support not in ("table", "held") and is_clear(loc, b) and b not in stacked:
                nxt = list(loc)
                nxt[i] = "held"
                result.append((tuple(nxt), stacked, f"(unstack {b} {support})"))

    if held is not None:
        i = blocks.index(held)
        for j, y in enumerate(blocks):
            if loc[j] != "held" and is_clear(loc, y):
                nxt = list(loc)
                nxt[i] = y
                result.append((tuple(nxt), stacked | {held}, f"(stack {held} {y})"))

    return result


def solve():
    queue = deque()
    start = (start_state, frozenset())
    queue.append((start_state, frozenset(), []))
    visited = {start}

    while queue:
        loc, stacked, plan = queue.popleft()

        if loc == goal_state:
            return plan

        for nloc, nstacked, action in successors(loc, stacked):
            state = (nloc, nstacked)
            if state not in visited:
                visited.add(state)
                queue.append((nloc, nstacked, plan + [action]))

    return None


plan = solve()
if plan is None:
    print("No plan")
else:
    print("\n".join(plan))

import sys

N = 9
TABLE = -1


def name(b):
    return f"block{b}"


def main():
    initial = [0] * (N + 1)
    # Initial tower from bottom to top:
    # block7 on table, block2 on 7, block9 on 2, block1 on 9,
    # block4 on 1, block6 on 4, block5 on 6, block3 on 5, block8 on 3.
    initial[7] = TABLE
    initial[2] = 7
    initial[9] = 2
    initial[1] = 9
    initial[4] = 1
    initial[6] = 4
    initial[5] = 6
    initial[3] = 5
    initial[8] = 3

    goal = [0] * (N + 1)
    # Goal towers:
    # block9 on block8 on table
    # block7 on block3 on block4 on block2 on table
    # block6 on table
    # block5 on block1 on table
    goal[8] = TABLE
    goal[9] = 8
    goal[2] = TABLE
    goal[4] = 2
    goal[3] = 4
    goal[7] = 3
    goal[6] = TABLE
    goal[1] = TABLE
    goal[5] = 1

    class State:
        def __init__(self, support):
            self.support = support[:]
            self.held = 0
            self.actions = []

        def top_of(self, b):
            for c in range(1, N + 1):
                if self.support[c] == b:
                    return c
            return 0

        def clear(self, b):
            return self.top_of(b) == 0

        def do(self, action, x, y=0):
            if action == "pickup":
                self.held = x
                self.support[x] = 0
            elif action == "putdown":
                self.support[x] = TABLE
                self.held = 0
            elif action == "unstack":
                self.support[x] = 0
                self.held = x
            elif action == "stack":
                self.support[x] = y
                self.held = 0
            self.actions.append((action, x, y))

        def clear_block(self, b):
            # Assumes the arm is empty.
            while True:
                top = self.top_of(b)
                if top == 0:
                    return
                self.clear_block(top)
                self.do("unstack", top, b)
                self.do("putdown", top)

        def move_to_table(self, b):
            # Assumes the arm is empty.
            self.clear_block(b)
            if self.support[b] != TABLE:
                s = self.support[b]
                if s > 0:
                    self.do("unstack", b, s)
                    self.do("putdown", b)

        def move_to_block(self, b, target):
            # Assumes the arm is empty.
            if b == target:
                return

            self.clear_block(b)

            if self.support[b] == target:
                return

            if not self.clear(target):
                self.clear_block(target)

            if self.support[b] == TABLE:
                self.do("pickup", b)
            elif self.support[b] > 0:
                self.do("unstack", b, self.support[b])
            else:
                return

            self.do("stack", b, target)

    state = State(initial)

    # Goal towers in bottom-to-top order, following the described arrangement.
    goal_towers = [
        (8, 9),
        (2, 4, 3, 7),
        (6,),
        (1, 5),
    ]

    # A few passes make the constructive planner robust if an earlier move
    # temporarily disturbs a block that is processed later.
    for _ in range(3):
        for tower in goal_towers:
            for b in tower:
                if goal[b] == TABLE:
                    state.move_to_table(b)
                else:
                    state.move_to_block(b, goal[b])

        if state.held == 0 and state.support == goal:
            break

    if state.held == 0 and state.support == goal:
        for action, x, y in state.actions:
            if action == "pickup" or action == "putdown":
                print(f"({action} {name(x)})")
            else:
                print(f"({action} {name(x)} {name(y)})")
    else:
        print("No plan")


if __name__ == "__main__":
    main()

import sys
import heapq


def format_plan(plan):
    lines = []
    for a in plan:
        if a[0] in ("pickup", "putdown"):
            lines.append(f"({a[0]} block{a[1]})")
        else:
            lines.append(f"({a[0]} block{a[1]} block{a[2]})")
    return "\n".join(lines)


def validate(plan, initial, goal_pos, blocks):
    pos = dict(initial)
    held = 0

    def clear(b):
        for x in blocks:
            if x != b and pos[x] == b:
                return False
        return True

    for a in plan:
        action = a[0]
        if action == "pickup":
            b = a[1]
            if held != 0 or pos[b] != 0 or not clear(b):
                return False
            held = b
            pos[b] = -1
        elif action == "putdown":
            b = a[1]
            if held != b:
                return False
            held = 0
            pos[b] = 0
        elif action == "unstack":
            x, y = a[1], a[2]
            if held != 0 or pos[x] != y or not clear(x):
                return False
            held = x
            pos[x] = -1
        elif action == "stack":
            x, y = a[1], a[2]
            if held != x or pos[y] == -1 or not clear(y):
                return False
            held = 0
            pos[x] = y
        else:
            return False

    if held != 0:
        return False
    return all(pos[b] == goal_pos[b] for b in blocks)


def plan_one_move(initial, goal_pos, blocks):
    needs = {b: initial[b] != goal_pos[b] for b in blocks}
    nodes = [b for b in blocks if needs[b]]
    edges = {b: set() for b in nodes}
    impossible = False

    for b in nodes:
        for c in blocks:
            if initial[c] == b:
                if not needs[c]:
                    impossible = True
                else:
                    edges[c].add(b)

        t = goal_pos[b]
        if t != 0:
            if needs[t]:
                edges[t].add(b)
            else:
                for c in blocks:
                    if initial[c] == t and c != b:
                        if not needs[c]:
                            impossible = True
                        else:
                            edges[c].add(b)

    if impossible:
        return None

    indeg = {b: 0 for b in nodes}
    for b in nodes:
        for v in edges[b]:
            if v in indeg:
                indeg[v] += 1
            else:
                return None

    heap = [b for b in nodes if indeg[b] == 0]
    heapq.heapify(heap)
    order = []

    while heap:
        b = heapq.heappop(heap)
        order.append(b)
        for v in sorted(edges[b]):
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)

    if len(order) != len(nodes):
        return None

    plan = []
    for b in order:
        s = initial[b]
        t = goal_pos[b]
        if s == 0:
            plan.append(("pickup", b))
        else:
            plan.append(("unstack", b, s))
        if t == 0:
            plan.append(("putdown", b))
        else:
            plan.append(("stack", b, t))

    if not validate(plan, initial, goal_pos, blocks):
        return None
    return plan


def plan_clear_build(initial, goal_stacks, blocks, goal_pos):
    pos = dict(initial)
    held = 0
    plan = []

    def clear(b):
        for x in blocks:
            if x != b and pos[x] == b:
                return False
        return True

    def pickup(b):
        nonlocal held
        if held != 0 or pos[b] != 0 or not clear(b):
            return False
        held = b
        pos[b] = -1
        plan.append(("pickup", b))
        return True

    def putdown(b):
        nonlocal held
        if held != b:
            return False
        held = 0
        pos[b] = 0
        plan.append(("putdown", b))
        return True

    def unstack(x, y):
        nonlocal held
        if held != 0 or pos[x] != y or not clear(x):
            return False
        held = x
        pos[x] = -1
        plan.append(("unstack", x, y))
        return True

    def stack(x, y):
        nonlocal held
        if held != x or pos[y] == -1 or not clear(y):
            return False
        held = 0
        pos[x] = y
        plan.append(("stack", x, y))
        return True

    while True:
        b = None
        for x in blocks:
            if pos[x] != 0 and pos[x] != -1 and clear(x):
                b = x
                break
        if b is None:
            break
        s = pos[b]
        if not unstack(b, s) or not putdown(b):
            return None

    for st in goal_stacks:
        if not st:
            continue
        bottom = st[0]
        if pos[bottom] != 0 or not clear(bottom):
            return None
        prev = bottom
        for b in st[1:]:
            if pos[b] != 0 or not clear(b) or held != 0:
                return None
            if not pickup(b) or not stack(b, prev):
                return None
            prev = b

    if held != 0:
        return None
    for b in blocks:
        if pos[b] != goal_pos[b]:
            return None
    return plan


def main():
    blocks = tuple(range(1, 14))

    initial = {b: 0 for b in blocks}
    initial[10] = 12
    initial[7] = 10
    initial[13] = 7
    initial[9] = 3

    goal_stacks = (
        (13, 3, 2, 4, 12),
        (11, 6, 7, 8),
        (10, 1, 5, 9),
    )

    goal_pos = {b: 0 for b in blocks}
    for st in goal_stacks:
        for i in range(1, len(st)):
            goal_pos[st[i]] = st[i - 1]

    seen = []
    for st in goal_stacks:
        seen.extend(st)
    if sorted(seen) != sorted(blocks):
        print("No plan")
        return

    plan = plan_one_move(initial, goal_pos, blocks)
    if plan is None:
        plan = plan_clear_build(initial, goal_stacks, blocks, goal_pos)

    if plan is None or not validate(plan, initial, goal_pos, blocks):
        print("No plan")
        return

    sys.stdout.write(format_plan(plan))


if __name__ == "__main__":
    main()

import heapq

N = 14
TABLE = -1
ARM = -2

# block index = block number - 1
desired = [TABLE] * N
desired[13] = 2  # block14 on block3

initial = [TABLE] * N

# Blocks initially on the table:
# 5, 12, 11, 3, 7, 2, 10, 4, 1
for b in (5, 12, 11, 3, 7, 2, 10, 4, 1):
    initial[b - 1] = TABLE

# Stacks:
# 6 on 12, 9 on 6
initial[6 - 1] = 12 - 1
initial[9 - 1] = 6 - 1

# 13 on 11, 14 on 13
initial[13 - 1] = 11 - 1
initial[14 - 1] = 13 - 1

# 8 on 4
initial[8 - 1] = 4 - 1

start = tuple(initial)
goal = tuple(desired)


def is_clear(state, b):
    for i in range(N):
        if state[i] == b:
            return False
    return True


def arm_block(state):
    for i in range(N):
        if state[i] == ARM:
            return i
    return None


def successors(state):
    arm = arm_block(state)

    if arm is None:
        # Pickup a clear block from the table.
        for b in range(N):
            if state[b] == TABLE and is_clear(state, b):
                ns = list(state)
                ns[b] = ARM
                yield tuple(ns), ("pickup", b)

        # Unstack a clear block from another block.
        for x in range(N):
            y = state[x]
            if y != TABLE and y != ARM and is_clear(state, x):
                ns = list(state)
                ns[x] = ARM
                yield tuple(ns), ("unstack", x, y)
    else:
        b = arm

        # Putdown the held block.
        ns = list(state)
        ns[b] = TABLE
        yield tuple(ns), ("putdown", b)

        # Stack the held block on a clear block.
        for y in range(N):
            if y != b and state[y] != ARM and is_clear(state, y):
                ns = list(state)
                ns[b] = y
                yield tuple(ns), ("stack", b, y)


def heuristic(state):
    total = 0
    for b in range(N):
        current = state[b]
        target = desired[b]
        if current != target:
            if current == ARM:
                total += 1
            else:
                total += 2
    return total


def format_action(action):
    if action[0] in ("pickup", "putdown"):
        return f"({action[0]} block{action[1] + 1})"
    return f"({action[0]} block{action[1] + 1} block{action[2] + 1})"


def main():
    if start == goal:
        return

    h0 = heuristic(start)
    counter = 0
    heap = [(h0, h0, 0, counter, start)]
    best_g = {start: 0}
    parent = {start: (None, None)}

    while heap:
        f, h, g, _, state = heapq.heappop(heap)

        if g != best_g.get(state):
            continue

        if state == goal:
            actions = []
            cur = state
            while parent[cur][0] is not None:
                prev, act = parent[cur]
                actions.append(act)
                cur = prev
            actions.reverse()
            print("\n".join(format_action(a) for a in actions))
            return

        for ns, act in successors(state):
            ng = g + 1
            if ng < best_g.get(ns, 10**9):
                best_g[ns] = ng
                parent[ns] = (state, act)
                nh = heuristic(ns)
                counter += 1
                heapq.heappush(heap, (ng + nh, nh, ng, counter, ns))

    print("No plan")


if __name__ == "__main__":
    main()

import heapq
from itertools import count

N = 9
TABLE = -1
HELD = -2
B1 = 0
B2 = 1

goal_order = [7, 2, 5, 4, 1, 0, 8, 3, 6]
goal_on = [TABLE] * N
for i, b in enumerate(goal_order):
    if i == 0:
        goal_on[b] = TABLE
    else:
        goal_on[b] = goal_order[i - 1]
top_block = goal_order[-1]


def next_status(status, m1, m2):
    if status == 0:
        return 4 if m1 else 0
    if status == 2:
        return 2
    if m2:
        return 2
    if status == 1:
        return None
    return status - 1


def heuristic(state):
    on, clear, held, status = state
    in_pref = [False] * N
    for i, b in enumerate(goal_order):
        if i == 0:
            if on[b] == TABLE:
                in_pref[b] = True
            else:
                break
        else:
            if in_pref[goal_order[i - 1]] and on[b] == goal_order[i - 1]:
                in_pref[b] = True
            else:
                break

    h = 0
    for b in range(N):
        if in_pref[b]:
            continue
        if held == b:
            h += 1
        elif on[b] == TABLE:
            if goal_on[b] != TABLE:
                h += 2
        else:
            h += 2

    if 1 <= status <= 4 and in_pref[B2]:
        h += 1
    return h


def apply_action(state, action):
    on, clear, held, status = state
    on = list(on)
    clear = list(clear)
    a = action[0]

    if a == 'pickup':
        b = action[1]
        held = b
        on[b] = HELD
        clear[b] = True
    elif a == 'putdown':
        b = action[1]
        on[b] = TABLE
        clear[b] = True
        held = -1
    elif a == 'unstack':
        b, c = action[1], action[2]
        held = b
        on[b] = HELD
        clear[b] = True
        clear[c] = True
    elif a == 'stack':
        b, c = action[1], action[2]
        on[b] = c
        clear[b] = False
        clear[c] = False
        held = -1
    else:
        return None

    m1 = action[1] == B1
    m2 = action[1] == B2
    ns = next_status(status, m1, m2)
    if ns is None:
        return None

    return (tuple(on), tuple(clear), held, ns)


def generate_actions(state):
    on, clear, held, status = state
    actions = []

    if held == -1:
        for b in range(N):
            if clear[b]:
                loc = on[b]
                if loc == TABLE:
                    actions.append(('pickup', b))
                elif loc != HELD:
                    actions.append(('unstack', b, loc))
    else:
        b = held
        actions.append(('putdown', b))
        for c in range(N):
            if c != b and clear[c]:
                actions.append(('stack', b, c))

    return actions


def is_goal(state):
    on, clear, held, status = state
    if held != -1 or status != 2:
        return False

    for b in range(N):
        if on[b] != goal_on[b]:
            return False
        if clear[b] != (b == top_block):
            return False

    return True


def solve_astar(limit=20000):
    start = (tuple([TABLE] * N), tuple([True] * N), -1, 0)
    if is_goal(start):
        return []

    counter = count()
    heap = [(heuristic(start), 0, next(counter), start)]
    dist = {start: 0}
    parent = {}
    expansions = 0

    while heap:
        f, g, _, state = heapq.heappop(heap)

        if g != dist.get(state):
            continue

        if is_goal(state):
            path = []
            cur = state
            while cur in parent:
                prev, action = parent[cur]
                path.append(action)
                cur = prev
            path.reverse()
            return path

        expansions += 1
        if expansions > limit:
            return None

        for action in generate_actions(state):
            ns = apply_action(state, action)
            if ns is None:
                continue

            ng = g + 1
            if ng < dist.get(ns, 10**9):
                dist[ns] = ng
                parent[ns] = (state, action)
                h = heuristic(ns)
                heapq.heappush(heap, (ng + h, ng, next(counter), ns))

    return None


def validate_plan(plan):
    on = [TABLE] * N
    clear = [True] * N
    held = -1
    status = 0

    for action in plan:
        a = action[0]

        if a == 'pickup':
            b = action[1]
            if held != -1 or not clear[b] or on[b] != TABLE:
                return False
            held = b
            on[b] = HELD
            clear[b] = True
        elif a == 'putdown':
            b = action[1]
            if held != b or on[b] != HELD:
                return False
            on[b] = TABLE
            clear[b] = True
            held = -1
        elif a == 'unstack':
            b, c = action[1], action[2]
            if held != -1 or not clear[b] or on[b] != c or c == TABLE:
                return False
            held = b
            on[b] = HELD
            clear[b] = True
            clear[c] = True
        elif a == 'stack':
            b, c = action[1], action[2]
            if held != b or not clear[c] or c == b or on[c] == HELD:
                return False
            on[b] = c
            clear[b] = False
            clear[c] = False
            held = -1
        else:
            return False

        m1 = action[1] == B1
        m2 = action[1] == B2
        status = next_status(status, m1, m2)
        if status is None:
            return False

    return is_goal((tuple(on), tuple(clear), held, status))


def constructive_plan():
    actions = []
    idx2 = goal_order.index(B2)
    idx1 = goal_order.index(B1)

    for b in goal_order[:idx2]:
        if b == goal_order[0]:
            continue
        actions.append(('pickup', b))
        actions.append(('stack', b, goal_on[b]))

    actions.append(('pickup', B1))
    actions.append(('putdown', B1))
    actions.append(('pickup', B2))
    actions.append(('stack', B2, goal_on[B2]))
    actions.append(('pickup', B1))
    actions.append(('stack', B1, B2))

    for b in goal_order[idx1 + 1:]:
        actions.append(('pickup', b))
        actions.append(('stack', b, goal_on[b]))

    return actions


def format_action(action):
    args = ' '.join(f"block{b + 1}" for b in action[1:])
    return f"({action[0]} {args})"


def main():
    plan = solve_astar(limit=20000)
    if plan is not None and not validate_plan(plan):
        plan = None

    fallback = constructive_plan()
    if validate_plan(fallback):
        if plan is None or len(fallback) < len(plan):
            plan = fallback

    if plan is not None and validate_plan(plan):
        for action in plan:
            print(format_action(action))
    else:
        print("No plan")


if __name__ == "__main__":
    main()

import sys
from collections import deque

BLOCKS = tuple(range(1, 8))
TABLE = 0


def encode(on, holding):
    return (tuple(on[b] for b in BLOCKS), holding)


def is_clear(block, on):
    for other in BLOCKS:
        if other != block and on[other] == block:
            return False
    return True


def successors(state):
    on_values, holding = state
    on = dict(zip(BLOCKS, on_values))

    for block in BLOCKS:
        if holding == TABLE:
            if on[block] == TABLE and is_clear(block, on):
                new_on = on.copy()
                new_on[block] = None
                yield ("pickup", block, TABLE), encode(new_on, block)

            support = on[block]
            if support is not None and support != TABLE and is_clear(block, on):
                new_on = on.copy()
                new_on[block] = None
                yield ("unstack", block, support), encode(new_on, block)

        elif holding == block:
            new_on = on.copy()
            new_on[block] = TABLE
            yield ("putdown", block, TABLE), encode(new_on, TABLE)

            for target in BLOCKS:
                if target == block or on[target] is None:
                    continue
                if is_clear(target, on):
                    new_on = on.copy()
                    new_on[block] = target
                    yield ("stack", block, target), encode(new_on, TABLE)


def solve():
    initial_on = {
        1: 4,
        2: 1,
        3: 7,
        4: 5,
        5: TABLE,
        6: TABLE,
        7: 6,
    }

    goal_on = {
        1: 5,
        2: TABLE,
        3: TABLE,
        4: 7,
        5: 2,
        6: 3,
        7: 1,
    }

    start = encode(initial_on, TABLE)
    goal = encode(goal_on, TABLE)

    if start == goal:
        return []

    parent = {start: None}
    queue = deque([start])

    while queue:
        state = queue.popleft()

        for action, next_state in successors(state):
            if next_state in parent:
                continue

            parent[next_state] = (state, action)

            if next_state == goal:
                plan = []
                current = next_state
                while parent[current] is not None:
                    previous, act = parent[current]
                    plan.append(act)
                    current = previous
                plan.reverse()
                return plan

            queue.append(next_state)

    return None


def format_action(action):
    verb = action[0]
    if verb == "pickup" or verb == "putdown":
        return f"({verb} block{action[1]})"
    return f"({verb} block{action[1]} block{action[2]})"


if __name__ == "__main__":
    plan = solve()
    if plan is None:
        print("No plan")
    else:
        for action in plan:
            print(format_action(action))

BLOCKS = [f"block{i}" for i in range(1, 14)]
TABLE = "table"
HELD = "held"
FRAGILE = {"block4"}


def bname(i):
    return f"block{i}"


initial_support = {b: TABLE for b in BLOCKS}
for top, bottom in [(10, 12), (7, 10), (13, 7), (9, 3)]:
    initial_support[bname(top)] = bname(bottom)

goal_support = {b: TABLE for b in BLOCKS}
for top, bottom in [
    (3, 13), (2, 3), (4, 2), (12, 4),
    (6, 11), (7, 6), (8, 7),
    (1, 10), (5, 1), (9, 5)
]:
    goal_support[bname(top)] = bname(bottom)


def state_valid(support):
    for block in BLOCKS:
        if support[block] in FRAGILE:
            return False
    return True


def goal_valid(goal):
    for block in BLOCKS:
        support = goal[block]
        if support != TABLE and support not in BLOCKS:
            return False

    if not state_valid(goal):
        return False

    children = {block: [] for block in BLOCKS}
    for block in BLOCKS:
        support = goal[block]
        if support != TABLE:
            children[support].append(block)

    for block in BLOCKS:
        if len(children[block]) > 1:
            return False

    for block in BLOCKS:
        seen = set()
        current = block
        while current != TABLE:
            if current in seen:
                return False
            seen.add(current)
            current = goal[current]

    return True


def goal_stacks(goal):
    children = {block: [] for block in BLOCKS}
    for block in BLOCKS:
        support = goal[block]
        if support != TABLE:
            children[support].append(block)

    stacks = []
    for block in BLOCKS:
        if goal[block] == TABLE:
            stack = [block]
            while children[stack[-1]]:
                stack.append(children[stack[-1]][0])
            stacks.append(stack)

    if sum(len(stack) for stack in stacks) != len(BLOCKS):
        return None

    return stacks


def dismantle(support, plan):
    while True:
        top = None
        for block in BLOCKS:
            if support[block] != TABLE and support[block] != HELD:
                if all(support[other] != block for other in BLOCKS):
                    top = block
                    break

        if top is None:
            break

        below = support[top]
        plan.append(f"(unstack {top} {below})")
        support[top] = HELD
        plan.append(f"(putdown {top})")
        support[top] = TABLE


def build(support, stacks, plan):
    for stack in stacks:
        for i in range(1, len(stack)):
            block = stack[i]
            target = stack[i - 1]
            plan.append(f"(pickup {block})")
            support[block] = HELD
            plan.append(f"(stack {block} {target})")
            support[block] = target


def is_clear(support, block):
    return all(support[other] != block for other in BLOCKS)


def simulate(plan, start_support, goal):
    support = dict(start_support)
    held = None

    for action in plan:
        if not action.startswith("(") or not action.endswith(")"):
            return False

        parts = action[1:-1].split()
        if not parts:
            return False

        verb = parts[0]

        if verb == "pickup":
            if len(parts) != 2:
                return False
            block = parts[1]
            if block not in BLOCKS:
                return False
            if held is not None or support[block] != TABLE or not is_clear(support, block):
                return False
            held = block
            support[block] = HELD

        elif verb == "putdown":
            if len(parts) != 2:
                return False
            block = parts[1]
            if block not in BLOCKS:
                return False
            if held != block:
                return False
            held = None
            support[block] = TABLE

        elif verb == "unstack":
            if len(parts) != 3:
                return False
            block, below = parts[1], parts[2]
            if block not in BLOCKS or below not in BLOCKS:
                return False
            if held is not None or support[block] != below or not is_clear(support, block):
                return False
            held = block
            support[block] = HELD

        elif verb == "stack":
            if len(parts) != 3:
                return False
            block, target = parts[1], parts[2]
            if block not in BLOCKS or target not in BLOCKS:
                return False
            if held != block or support[target] == HELD or not is_clear(support, target):
                return False
            if target in FRAGILE:
                return False
            support[block] = target
            held = None

        else:
            return False

        if not state_valid(support):
            return False

    if held is not None:
        return False

    return all(support[block] == goal[block] for block in BLOCKS)


def main():
    if not state_valid(initial_support):
        print("No plan")
        return

    if not goal_valid(goal_support):
        print("No plan")
        return

    stacks = goal_stacks(goal_support)
    if stacks is None:
        print("No plan")
        return

    plan = []
    support = dict(initial_support)

    dismantle(support, plan)
    build(support, stacks, plan)

    if simulate(plan, initial_support, goal_support):
        print("\n".join(plan))
    else:
        print("No plan")


if __name__ == "__main__":
    main()

from collections import deque


def main():
    names = [f"block{i}" for i in range(1, 7)]
    n = len(names)
    name_to_index = {name: i for i, name in enumerate(names)}
    block_name_set = set(names)

    initial_loc = ["block4", "block1", "table", "block5", "block6", "block3"]
    goal_loc = ["table", "table", "block4", "table", "table", "block2"]

    start = (tuple(initial_loc), -1)
    goal = (tuple(goal_loc), -1)

    def is_clear(i, loc):
        name = names[i]
        for j in range(n):
            if loc[j] == name:
                return False
        return True

    def neighbors(state):
        loc = list(state[0])
        arm = state[1]

        if arm == -1:
            for i in range(n):
                if loc[i] == "table" and is_clear(i, loc):
                    new_loc = loc[:]
                    new_loc[i] = "held"
                    yield ("pickup", i), (tuple(new_loc), i)

            for i in range(n):
                if loc[i] in block_name_set:
                    j = name_to_index[loc[i]]
                    if loc[j] != "held" and is_clear(i, loc):
                        new_loc = loc[:]
                        new_loc[i] = "held"
                        yield ("unstack", i, j), (tuple(new_loc), i)
        else:
            i = arm

            new_loc = loc[:]
            new_loc[i] = "table"
            yield ("putdown", i), (tuple(new_loc), -1)

            for j in range(n):
                if loc[j] != "table" and loc[j] != "held" and is_clear(j, loc):
                    new_loc = loc[:]
                    new_loc[i] = names[j]
                    yield ("stack", i, j), (tuple(new_loc), -1)

    if start == goal:
        return

    parent = {start: None}
    queue = deque([start])

    while queue:
        state = queue.popleft()

        if state == goal:
            actions = []
            while parent[state] is not None:
                prev_state, action = parent[state]
                actions.append(action)
                state = prev_state

            actions.reverse()

            for action in actions:
                if action[0] in ("pickup", "putdown"):
                    print(f"({action[0]} {names[action[1]]})")
                else:
                    print(f"({action[0]} {names[action[1]]} {names[action[2]]})")
            return

        for action, next_state in neighbors(state):
            if next_state not in parent:
                parent[next_state] = (state, action)
                queue.append(next_state)

    print("No plan")


if __name__ == "__main__":
    main()

import sys

TABLE = 0
HELD = -1
NONE = -1

BLOCKS = tuple(range(1, 11))

GOAL_ON = {
    1: TABLE, 10: 1,
    4: TABLE, 8: 4,
    3: TABLE, 9: 3, 2: 9,
    5: TABLE, 6: 5, 7: 6,
}
GOAL_ON_TOP = {
    1: 10, 10: NONE,
    4: 8, 8: NONE,
    3: 9, 9: 2, 2: NONE,
    5: 6, 6: 7, 7: NONE,
}
GOAL_ON_TUPLE = tuple(GOAL_ON[b] for b in BLOCKS)
GOAL_ON_TOP_TUPLE = tuple(GOAL_ON_TOP[b] for b in BLOCKS)

INITIAL_ON_TUPLE = tuple(TABLE for _ in BLOCKS)
INITIAL_ON_TOP_TUPLE = tuple(NONE for _ in BLOCKS)


def required_after(block):
    if block == 2:
        return 4
    if block == 4:
        return 6
    return NONE


must_move = set()
for b in BLOCKS:
    if INITIAL_ON_TUPLE[b - 1] != GOAL_ON[b]:
        must_move.add(b)

queue = list(must_move)
while queue:
    b = queue.pop()
    c = required_after(b)
    if c is not None and c not in must_move:
        must_move.add(c)
        queue.append(c)


def is_clear(on_top, b):
    return on_top[b - 1] == NONE


def move_to_table(on, on_top, b):
    current = on[b - 1]
    new_on = list(on)
    new_on_top = list(on_top)

    if current == TABLE:
        actions = [("pickup", b, NONE), ("putdown", b, NONE)]
    else:
        actions = [("unstack", b, current), ("putdown", b, NONE)]
        new_on_top[current - 1] = NONE

    new_on[b - 1] = TABLE
    return tuple(new_on), tuple(new_on_top), actions


def move_to_target(on, on_top, b, target):
    current = on[b - 1]
    new_on = list(on)
    new_on_top = list(on_top)

    if current == TABLE:
        actions = [("pickup", b, NONE), ("stack", b, target)]
    else:
        actions = [("unstack", b, current), ("stack", b, target)]
        new_on_top[current - 1] = NONE

    new_on[b - 1] = target
    new_on_top[target - 1] = b
    return tuple(new_on), tuple(new_on_top), actions


def move_same_target(on, on_top, b, target):
    actions = [("unstack", b, target), ("stack", b, target)]
    return on, on_top, actions


def dfs(on, on_top, remaining, pending, plan, failed):
    key = (on, on_top, remaining, pending)
    if key in failed:
        return False

    if not remaining:
        if pending == NONE and on == GOAL_ON_TUPLE and on_top == GOAL_ON_TOP_TUPLE:
            return True
        failed.add(key)
        return False

    for b in sorted(remaining):
        if pending != NONE and b != pending:
            continue

        if pending == NONE:
            blocked = False
            for d in remaining:
                if d != b and required_after(d) == b:
                    blocked = True
                    break
            if blocked:
                continue

        if not is_clear(on_top, b):
            continue

        target = GOAL_ON[b]

        if target == TABLE:
            new_on, new_on_top, actions = move_to_table(on, on_top, b)
        else:
            current = on[b - 1]
            if current == target:
                new_on, new_on_top, actions = move_same_target(on, on_top, b, target)
            else:
                if target in remaining:
                    continue
                if not is_clear(on_top, target):
                    continue
                if on[target - 1] != GOAL_ON[target]:
                    continue
                new_on, new_on_top, actions = move_to_target(on, on_top, b, target)

        new_remaining = frozenset(remaining - {b})
        new_pending = required_after(b)

        if new_pending != NONE and new_pending not in new_remaining:
            continue

        plan.extend(actions)
        if dfs(new_on, new_on_top, new_remaining, new_pending, plan, failed):
            return True
        del plan[-len(actions):]

    failed.add(key)
    return False


def format_action(action):
    kind, b, y = action
    if kind in ("pickup", "putdown"):
        return f"({kind} block{b})"
    return f"({kind} block{b} block{y})"


def main():
    plan = []
    failed = set()
    start_remaining = frozenset(must_move)

    dfs(
        INITIAL_ON_TUPLE,
        INITIAL_ON_TOP_TUPLE,
        start_remaining,
        NONE,
        plan,
        failed,
    )

    if not plan:
        print("No plan")
    else:
        print("\n".join(format_action(action) for action in plan))


if __name__ == "__main__":
    main()

import sys
import heapq

TABLE = -1
HELD = -2
N = 12
BLOCKS = [f"block{i}" for i in range(1, N + 1)]


def bidx(num):
    return num - 1


initial = [TABLE] * N
for top, bottom in [(9, 10), (2, 9), (1, 2), (11, 1), (12, 11), (5, 12), (6, 5), (3, 7)]:
    initial[bidx(top)] = bidx(bottom)

goal = [TABLE] * N
for top, bottom in [(11, 3), (10, 11), (7, 10), (12, 5), (9, 2), (8, 9)]:
    goal[bidx(top)] = bidx(bottom)

FINAL_HOLDING = bidx(1)

if goal[FINAL_HOLDING] != HELD:
    print("No plan")
    sys.exit()

goal[FINAL_HOLDING] = HELD


def valid_config(supports):
    n = len(supports)
    helds = [i for i, s in enumerate(supports) if s == HELD]
    if len(helds) > 1:
        return False

    if helds:
        h = helds[0]
        for s in supports:
            if s == h:
                return False

    counts = {}
    for i, s in enumerate(supports):
        if s == i:
            return False
        if s >= 0:
            counts[s] = counts.get(s, 0) + 1
            if counts[s] > 1:
                return False

    for i in range(n):
        seen = set()
        cur = i
        while 0 <= cur < n:
            if cur in seen:
                return False
            seen.add(cur)
            cur = supports[cur]

    return True


if not valid_config(initial) or not valid_config(goal):
    print("No plan")
    sys.exit()


def generate_actions(state):
    n = len(state)
    above = [False] * n
    for i, s in enumerate(state):
        if s >= 0:
            above[s] = True

    held = -1
    for i, s in enumerate(state):
        if s == HELD:
            held = i
            break

    if held == -1:
        for b in range(n):
            if above[b]:
                continue
            if state[b] == TABLE:
                ns = list(state)
                ns[b] = HELD
                yield ("pickup", b), tuple(ns)
            elif state[b] >= 0:
                c = state[b]
                ns = list(state)
                ns[b] = HELD
                yield ("unstack", b, c), tuple(ns)
    else:
        b = held
        ns = list(state)
        ns[b] = TABLE
        yield ("putdown", b), tuple(ns)

        for c in range(n):
            if c == b or state[c] == HELD or above[c]:
                continue
            ns = list(state)
            ns[b] = c
            yield ("stack", b, c), tuple(ns)


def heuristic(state, goal):
    return sum(1 for a, b in zip(state, goal) if a != b)


def solve(start, goal):
    start = tuple(start)
    goal = tuple(goal)

    if start == goal:
        return []

    counter = 0
    heap = [(heuristic(start, goal), 0, counter, start)]
    best = {start: 0}
    parent = {start: None}

    while heap:
        f, g, _, state = heapq.heappop(heap)

        if g != best.get(state):
            continue

        if state == goal:
            plan = []
            cur = state
            while parent[cur] is not None:
                prev, action = parent[cur]
                plan.append(action)
                cur = prev
            plan.reverse()
            return plan

        for action, ns in generate_actions(state):
            ng = g + 1
            if ng < best.get(ns, float("inf")):
                best[ns] = ng
                parent[ns] = (state, action)
                counter += 1
                heapq.heappush(heap, (ng + heuristic(ns, goal), ng, counter, ns))

    return None


def format_action(action):
    if action[0] in ("pickup", "putdown"):
        return f"({action[0]} {BLOCKS[action[1]]})"
    return f"({action[0]} {BLOCKS[action[1]]} {BLOCKS[action[2]]})"


plan = solve(initial, goal)

if plan is None:
    print("No plan")
else:
    for action in plan:
        print(format_action(action))

def main():
    blocks = [f"block{i}" for i in range(1, 15)]

    initial = {b: None for b in blocks}
    initial["block14"] = "block8"

    goal = {b: None for b in blocks}
    goal["block10"] = "block9"
    goal["block7"] = "block2"
    goal["block13"] = "block7"

    order = []
    visited = set()
    visiting = set()
    cycle = False

    def visit(b):
        nonlocal cycle
        if b in visited:
            return
        if b in visiting:
            cycle = True
            return
        visiting.add(b)
        support = goal[b]
        if support is not None:
            visit(support)
        visiting.discard(b)
        visited.add(b)
        order.append(b)

    for b in blocks:
        visit(b)

    class Planner:
        def __init__(self, blocks, initial, goal):
            self.blocks = blocks
            self.loc = dict(initial)
            self.goal = dict(goal)
            self.held = None
            self.actions = []
            self.ok = True

        def top(self, b):
            if self.loc[b] == "held":
                return None
            for x in self.blocks:
                if self.loc[x] == b:
                    return x
            return None

        def clear(self, b):
            return self.top(b) is None

        def _pickup(self, b):
            if not self.ok:
                return
            if self.held is not None:
                self.ok = False
                return
            if self.loc[b] is not None:
                self.ok = False
                return
            if not self.clear(b):
                self.ok = False
                return
            self.held = b
            self.loc[b] = "held"
            self.actions.append(("pickup", b))

        def _unstack(self, b, s):
            if not self.ok:
                return
            if self.held is not None:
                self.ok = False
                return
            if self.loc[b] != s:
                self.ok = False
                return
            if self.loc[s] == "held":
                self.ok = False
                return
            if not self.clear(b):
                self.ok = False
                return
            self.held = b
            self.loc[b] = "held"
            self.actions.append(("unstack", b, s))

        def _putdown(self, b):
            if not self.ok:
                return
            if self.held != b:
                self.ok = False
                return
            self.held = None
            self.loc[b] = None
            self.actions.append(("putdown", b))

        def _stack(self, b, s):
            if not self.ok:
                return
            if self.held != b:
                self.ok = False
                return
            if s == b:
                self.ok = False
                return
            if self.loc[s] == "held":
                self.ok = False
                return
            if not self.clear(s):
                self.ok = False
                return
            self.loc[b] = s
            self.held = None
            self.actions.append(("stack", b, s))

        def _ensure_empty(self):
            if self.held is not None:
                self._putdown(self.held)

        def _move_to_table(self, b):
            if not self.ok:
                return
            self._ensure_empty()
            if not self.ok:
                return
            self._make_clear(b)
            if not self.ok:
                return
            if self.loc[b] == "held":
                self._putdown(b)
            elif self.loc[b] is not None:
                s = self.loc[b]
                self._unstack(b, s)
                self._putdown(b)

        def _make_clear(self, b):
            if not self.ok:
                return
            self._ensure_empty()
            if not self.ok:
                return
            while self.ok:
                t = self.top(b)
                if t is None:
                    break
                self._move_to_table(t)

        def _make_on_table(self, b):
            if not self.ok:
                return
            self._move_to_table(b)

        def make_goal(self, b):
            if not self.ok:
                return
            self._ensure_empty()
            if not self.ok:
                return
            s = self.goal[b]
            if s is None:
                self._make_on_table(b)
            else:
                self.make_goal(s)
                if not self.ok:
                    return
                self._make_clear(b)
                if not self.ok:
                    return
                if self.loc[b] == s:
                    return
                if self.loc[b] is None:
                    self._pickup(b)
                elif self.loc[b] == "held":
                    pass
                else:
                    self._unstack(b, self.loc[b])
                if not self.ok:
                    return
                self._stack(b, s)

    planner = Planner(blocks, initial, goal)
    if not cycle:
        for b in order:
            planner.make_goal(b)

    def final_ok(p):
        if p.held is not None:
            return False
        for b in p.blocks:
            if p.loc[b] == "held":
                return False
            if p.loc[b] != p.goal[b]:
                return False
        return True

    if cycle or not planner.ok or not final_ok(planner):
        print("No plan")
        return

    for action in planner.actions:
        if len(action) == 2:
            print(f"({action[0]} {action[1]})")
        else:
            print(f"({action[0]} {action[1]} {action[2]})")


if __name__ == "__main__":
    main()

import heapq

BLOCKS = tuple(range(1, 14))
TABLE = 0
ARM = -1


def block_name(b):
    return f"block{b}"


init = [TABLE] * 14


def set_init(b, s):
    init[b] = s


set_init(2, TABLE)
set_init(10, TABLE)
set_init(13, 10)
set_init(9, 13)
set_init(1, 9)
set_init(4, TABLE)
set_init(7, 4)
set_init(11, TABLE)
set_init(5, TABLE)
set_init(12, 5)
set_init(8, TABLE)
set_init(6, 8)
set_init(3, 6)

goal_stacks = [
    [1, 6, 3, 9, 5],
    [13, 7],
    [11],
    [12, 10, 8, 2, 4],
]

goal_support = [TABLE] * 14
for stack in goal_stacks:
    prev = TABLE
    for b in stack:
        goal_support[b] = prev
        prev = b

seen = [b for stack in goal_stacks for b in stack]
if sorted(seen) != list(BLOCKS):
    print("No plan")
    raise SystemExit

start_state = tuple(init[b] for b in BLOCKS) + (TABLE,)
goal_state = tuple(goal_support[b] for b in BLOCKS) + (TABLE,)


def heuristic(state):
    loc = state[:13]
    arm = state[13]
    stable = [None] * 14
    stable[0] = True

    def is_stable(b):
        if b == 0:
            return True
        if stable[b] is not None:
            return stable[b]

        stable[b] = False
        s = loc[b - 1]

        if s == ARM:
            res = False
        elif s == TABLE:
            res = (goal_support[b] == TABLE)
        else:
            res = (goal_support[b] == s) and is_stable(s)

        stable[b] = res
        return res

    h = 0
    for b in BLOCKS:
        if not is_stable(b):
            if arm == b:
                h += 1
            else:
                h += 2
    return h


def generate_actions(state):
    loc = state[:13]
    arm = state[13]

    clear = [True] * 14
    for b in BLOCKS:
        s = loc[b - 1]
        if s != TABLE and s != ARM:
            clear[s] = False

    actions = []

    if arm == TABLE:
        for b in BLOCKS:
            if not clear[b]:
                continue
            s = loc[b - 1]
            if s == TABLE:
                actions.append(("pickup", b))
            elif s != ARM:
                actions.append(("unstack", b, s))
    else:
        b = arm
        actions.append(("putdown", b))
        for y in BLOCKS:
            if y == b:
                continue
            if clear[y] and loc[y - 1] != ARM:
                actions.append(("stack", b, y))

    return actions


def apply_action(state, action):
    loc = list(state[:13])
    arm = state[13]
    verb = action[0]

    if verb == "pickup" or verb == "unstack":
        b = action[1]
        loc[b - 1] = ARM
        arm = b
    elif verb == "putdown":
        b = action[1]
        loc[b - 1] = TABLE
        arm = TABLE
    elif verb == "stack":
        b = action[1]
        y = action[2]
        loc[b - 1] = y
        arm = TABLE

    return tuple(loc) + (arm,)


def print_plan(plan):
    for action in plan:
        verb = action[0]
        if verb in ("pickup", "putdown"):
            print(f"({verb} {block_name(action[1])})")
        else:
            print(f"({verb} {block_name(action[1])} {block_name(action[2])})")


def solve():
    if start_state == goal_state:
        return

    h0 = heuristic(start_state)
    counter = 0
    open_heap = [(h0, h0, counter, start_state, 0)]
    g_score = {start_state: 0}
    came = {start_state: None}

    while open_heap:
        f, h, _, state, g = heapq.heappop(open_heap)

        if g != g_score.get(state):
            continue

        if state == goal_state:
            plan = []
            cur = state
            while came[cur] is not None:
                prev, action = came[cur]
                plan.append(action)
                cur = prev
            plan.reverse()
            print_plan(plan)
            return

        for action in generate_actions(state):
            new_state = apply_action(state, action)
            ng = g + 1
            old = g_score.get(new_state)

            if old is None or ng < old:
                g_score[new_state] = ng
                came[new_state] = (state, action)
                nh = heuristic(new_state)
                counter += 1
                heapq.heappush(open_heap, (ng + nh, nh, counter, new_state, ng))

    print("No plan")


if __name__ == "__main__":
    solve()

def main():
    n = 8
    TABLE = -1
    HELD = -2

    state = [5, 2, -1, 6, 7, -1, 4, 1]
    goal = [3, 0, -1, 7, 5, 6, 1, 2]
    actions = []

    def add(op, a, b=0):
        actions.append((op, a, b))

    def child(b):
        for i, p in enumerate(state):
            if p == b:
                return i
        return -1

    def top_above(b):
        c = child(b)
        if c == -1:
            return -1
        while True:
            d = child(c)
            if d == -1:
                return c
            c = d

    def move_to_table(x):
        if state[x] == TABLE:
            return True
        p = state[x]
        if p >= 0:
            add(3, x, p)
            state[x] = HELD
        elif p == HELD:
            pass
        else:
            return False
        add(1, x)
        state[x] = TABLE
        return True

    def move_to_parent(x, parent):
        if state[x] == parent:
            return True
        p = state[x]
        if p == TABLE:
            add(0, x)
            state[x] = HELD
        elif p >= 0:
            add(3, x, p)
            state[x] = HELD
        elif p == HELD:
            pass
        else:
            return False
        if parent == TABLE:
            add(1, x)
            state[x] = TABLE
        else:
            add(2, x, parent)
            state[x] = parent
        return True

    root = -1
    child_of = {}
    for i, p in enumerate(goal):
        if p == TABLE:
            root = i
        else:
            child_of[p] = i

    order = []
    cur = root
    while cur != -1:
        order.append(cur)
        cur = child_of.get(cur, -1)

    if len(order) != n:
        print("No plan")
        return

    for i, b in enumerate(order):
        parent = order[i - 1] if i > 0 else TABLE
        while True:
            top = top_above(b)
            if top == -1:
                break
            if not move_to_table(top):
                print("No plan")
                return
        if not move_to_parent(b, parent):
            print("No plan")
            return

    if tuple(state) != tuple(goal):
        print("No plan")
        return

    for op, a, b in actions:
        if op == 0:
            print(f"(pickup block{a + 1})")
        elif op == 1:
            print(f"(putdown block{a + 1})")
        elif op == 2:
            print(f"(stack block{a + 1} block{b + 1})")
        else:
            print(f"(unstack block{a + 1} block{b + 1})")

if __name__ == "__main__":
    main()

import sys
from collections import deque

BLOCKS = tuple(range(1, 16))
TABLE = 0
HOLD = 16
MULT4 = {4, 8, 12}


def block_name(b):
    return f"block{b}"


def initial_state():
    s = [TABLE] * 16

    s[1] = TABLE
    s[13] = 1
    s[15] = 13
    s[4] = 15
    s[12] = 4

    s[14] = TABLE
    s[8] = 14
    s[3] = 8
    s[5] = 3
    s[10] = 5
    s[9] = 10
    s[6] = 9
    s[11] = 6
    s[7] = 11
    s[2] = 7

    return tuple(s)


def goal_state():
    g = [TABLE] * 16

    g[15] = TABLE
    g[12] = 15

    g[4] = TABLE

    g[14] = TABLE
    g[6] = 14
    g[3] = 6
    g[2] = 3

    g[1] = TABLE
    g[7] = 1
    g[10] = 7

    g[13] = TABLE
    g[5] = 13
    g[8] = 5

    g[11] = TABLE
    g[9] = 11

    return tuple(g)


def get_hand(s):
    for b in BLOCKS:
        if s[b] == HOLD:
            return b
    return 0


def is_clear(s, b):
    for x in BLOCKS:
        if s[x] == b:
            return False
    return True


def successors(s, parity):
    even_move = (parity == 1)
    hand = get_hand(s)
    result = []

    if hand == 0:
        for b in BLOCKS:
            if s[b] == HOLD:
                continue
            if not is_clear(s, b):
                continue
            if even_move and b not in MULT4:
                continue

            ns = list(s)
            ns[b] = HOLD

            if s[b] == TABLE:
                action = f"pickup {block_name(b)}"
            else:
                action = f"unstack {block_name(b)} {block_name(s[b])}"

            result.append((tuple(ns), action))

    else:
        b = hand
        if even_move and b not in MULT4:
            return result

        ns = list(s)
        ns[b] = TABLE
        result.append((tuple(ns), f"putdown {block_name(b)}"))

        for c in BLOCKS:
            if c == b or s[c] == HOLD:
                continue
            if not is_clear(s, c):
                continue

            ns = list(s)
            ns[b] = c
            result.append((tuple(ns), f"stack {block_name(b)} {block_name(c)}"))

    return result


def main():
    start = initial_state()
    goal = goal_state()

    if start == goal:
        return

    start_key = (start, 0)
    visited = {start_key}
    parent = {start_key: (None, None)}
    queue = deque([start_key])

    while queue:
        s, parity = queue.popleft()

        for ns, action in successors(s, parity):
            nparity = 1 - parity
            h = get_hand(ns)

            if nparity == 1 and h != 0 and h not in MULT4:
                continue

            key = (ns, nparity)
            if key in visited:
                continue

            visited.add(key)
            parent[key] = ((s, parity), action)

            if ns == goal:
                actions = []
                cur = key
                while parent[cur][0] is not None:
                    actions.append(parent[cur][1])
                    cur = parent[cur][0]
                actions.reverse()

                for i, a in enumerate(actions):
                    if i:
                        sys.stdout.write("\n")
                    sys.stdout.write(f"({a})")
                if actions:
                    sys.stdout.write("\n")
                return

            queue.append(key)

    sys.stdout.write("No plan\n")


if __name__ == "__main__":
    main()

from collections import Counter

TABLE = 0
BLOCKS = tuple(range(1, 16))


def block_name(b):
    return f"block{b}"


initial_support = {b: TABLE for b in BLOCKS}
initial_support[15] = 2
initial_support[4] = 15
initial_support[13] = 1
initial_support[8] = 13

explicit_on_table = (7, 8, 13)
explicit_on = (
    (5, 8),
    (15, 5),
    (6, 15),
    (4, 6),
    (11, 4),
    (10, 11),
    (3, 10),
    (14, 3),
    (9, 13),
    (12, 9),
    (1, 12),
    (2, 1),
)


def additional_candidate_states():
    multiples = tuple(sorted(b for b in BLOCKS if b % 3 == 0))
    non_multiples = tuple(sorted(b for b in BLOCKS if b % 3 != 0))
    candidates = []

    for first, second in ((multiples, non_multiples), (non_multiples, multiples)):
        support = {}
        for tower in (first, second):
            if not tower:
                continue
            support[tower[0]] = TABLE
            for i in range(1, len(tower)):
                support[tower[i]] = tower[i - 1]
        candidates.append(support)

    return candidates


def valid_additional_state(support):
    if set(support) != set(BLOCKS):
        return False

    for b, s in support.items():
        if s is None or s == b:
            return False
        if s != TABLE and s not in BLOCKS:
            return False

    counts = Counter(s for s in support.values() if s != TABLE)
    if any(c > 1 for c in counts.values()):
        return False

    for b in BLOCKS:
        seen = set()
        cur = b
        while cur != TABLE:
            if cur is None or cur in seen:
                return False
            seen.add(cur)
            cur = support[cur]

    if sum(1 for s in support.values() if s == TABLE) != 2:
        return False

    bases = [b for b in BLOCKS if support[b] == TABLE]
    towers = []

    for base in bases:
        tower = []
        cur = base
        while True:
            tower.append(cur)
            child = next((c for c in BLOCKS if support[c] == cur), None)
            if child is None:
                break
            cur = child
        towers.append(tower)

    def all_multiples(tower):
        return all(b % 3 == 0 for b in tower)

    def all_non_multiples(tower):
        return all(b % 3 != 0 for b in tower)

    if len(towers) != 2:
        return False

    if not (
        (all_multiples(towers[0]) and all_non_multiples(towers[1]))
        or (all_non_multiples(towers[0]) and all_multiples(towers[1]))
    ):
        return False

    for tower in towers:
        for i in range(len(tower) - 1):
            if tower[i] >= tower[i + 1]:
                return False

    return True


def satisfies_explicit_goal(support):
    for b in explicit_on_table:
        if support.get(b) != TABLE:
            return False

    for x, y in explicit_on:
        if support.get(x) != y:
            return False

    return True


def make_plan(initial, goal):
    support = dict(initial)
    holding = None
    actions = []

    def is_clear(b):
        return not any(support[c] == b for c in BLOCKS)

    def do_pickup(b):
        nonlocal holding
        if holding is not None or support.get(b) != TABLE or not is_clear(b):
            return False
        holding = b
        actions.append(("pickup", b))
        return True

    def do_putdown(b):
        nonlocal holding
        if holding != b:
            return False
        holding = None
        support[b] = TABLE
        actions.append(("putdown", b))
        return True

    def do_unstack(x, y):
        nonlocal holding
        if holding is not None or support.get(x) != y or not is_clear(x):
            return False
        if support.get(y) is None:
            return False
        holding = x
        support[x] = None
        actions.append(("unstack", x, y))
        return True

    def do_stack(x, y):
        nonlocal holding
        if holding != x or support.get(y) is None or not is_clear(y):
            return False
        holding = None
        support[x] = y
        actions.append(("stack", x, y))
        return True

    while True:
        movable = [b for b in BLOCKS if support[b] not in (TABLE, None) and is_clear(b)]
        if not movable:
            break
        x = movable[0]
        y = support[x]
        if not do_unstack(x, y) or not do_putdown(x):
            return None

    def goal_stacks(s):
        bases = [b for b in BLOCKS if s[b] == TABLE]
        stacks = []
        for base in bases:
            stack = []
            cur = base
            while True:
                stack.append(cur)
                child = next((c for c in BLOCKS if s[c] == cur), None)
                if child is None:
                    break
                cur = child
            stacks.append(stack)
        return stacks

    for stack in goal_stacks(goal):
        for b in stack:
            target = goal[b]
            if support[b] == target:
                continue

            if support[b] != TABLE or not is_clear(b):
                while support[b] != TABLE or not is_clear(b):
                    if support[b] is None:
                        return None

                    if not is_clear(b):
                        child = next((c for c in BLOCKS if support[c] == b), None)
                        if child is None:
                            return None
                        if not do_unstack(child, b) or not do_putdown(child):
                            return None
                        continue

                    y = support[b]
                    if not do_unstack(b, y) or not do_putdown(b):
                        return None

            if not do_pickup(b):
                return None

            if target == TABLE:
                if not do_putdown(b):
                    return None
            else:
                if not do_stack(b, target):
                    return None

    if holding is not None or support != goal:
        return None

    return actions


def main():
    goal = None
    for candidate in additional_candidate_states():
        if valid_additional_state(candidate) and satisfies_explicit_goal(candidate):
            goal = candidate
            break

    if goal is None:
        print("No plan")
        return

    plan = make_plan(initial_support, goal)

    if plan is None:
        print("No plan")
        return

    for action in plan:
        print("(" + action[0] + " " + " ".join(block_name(b) for b in action[1:]) + ")")


if __name__ == "__main__":
    main()

import sys

TABLE = "table"
BLOCKS = tuple(f"block{i}" for i in range(1, 16))


def build_support(stacks):
    support = {}
    seen = set()

    for stack in stacks:
        prev = TABLE
        for b in stack:
            if b not in BLOCKS or b in seen:
                return None
            seen.add(b)
            support[b] = prev
            prev = b

    if seen != set(BLOCKS):
        return None

    return support


def solve():
    initial_stacks = [
        ["block6", "block3", "block5"],
        ["block11"],
        [
            "block14",
            "block8",
            "block7",
            "block9",
            "block4",
            "block15",
            "block12",
            "block2",
            "block13",
            "block10",
        ],
        ["block1"],
    ]

    goal_stacks = [
        ["block8", "block7", "block12", "block5", "block13"],
        ["block15", "block4"],
        [
            "block3",
            "block11",
            "block2",
            "block9",
            "block14",
            "block10",
            "block6",
            "block1",
        ],
    ]

    support = build_support(initial_stacks)
    goal_support = build_support(goal_stacks)

    if support is None or goal_support is None:
        print("No plan")
        return

    held = None
    plan = []

    def clear(b):
        for c in BLOCKS:
            if support[c] == b:
                return False
        return True

    def pickup(b):
        nonlocal held
        if held is not None or support[b] != TABLE or not clear(b):
            raise RuntimeError
        plan.append(f"(pickup {b})")
        support[b] = None
        held = b

    def putdown(b):
        nonlocal held
        if held is not b or not clear(b):
            raise RuntimeError
        plan.append(f"(putdown {b})")
        support[b] = TABLE
        held = None

    def unstack(b, c):
        nonlocal held
        if held is not None or support[b] != c or c == TABLE or c is None or not clear(b):
            raise RuntimeError
        plan.append(f"(unstack {b} {c})")
        support[b] = None
        held = b

    def stack(b, c):
        nonlocal held
        if held is not b or support[c] is None or c == TABLE or not clear(c):
            raise RuntimeError
        plan.append(f"(stack {b} {c})")
        support[b] = c
        held = None

    try:
        # Move every block that is not on the table onto the table.
        while True:
            moved = False
            for b in BLOCKS:
                if support[b] != TABLE and support[b] is not None:
                    if clear(b):
                        unstack(b, support[b])
                        putdown(b)
                        moved = True
                        break
            if not moved:
                break

        # Build each goal stack from bottom to top.
        for stack in goal_stacks:
            for i, b in enumerate(stack):
                if support[b] != TABLE:
                    if support[b] is None or not clear(b):
                        raise RuntimeError
                    unstack(b, support[b])
                    putdown(b)

                if i == 0:
                    continue

                pickup(b)
                stack(b, stack[i - 1])

        if held is not None or support != goal_support:
            raise RuntimeError

    except RuntimeError:
        print("No plan")
        return

    if plan:
        sys.stdout.write("\n".join(plan) + "\n")


