    solve()

import sys

def main():
    blocks = [f"block{i}" for i in range(1, 16)]

    initial_stacks = [
        ["block1", "block13", "block15", "block4", "block12"],
        ["block14", "block8", "block3", "block5", "block10", "block9", "block6", "block11", "block7", "block2"],
    ]

    goal_stacks = [
        ["block15", "block12"],
        ["block4"],
        ["block14", "block6", "block3", "block2"],
        ["block1", "block7", "block10"],
        ["block13", "block5", "block8"],
        ["block11", "block9"],
    ]

    init_blocks = [b for stack in initial_stacks for b in stack]
    goal_blocks = [b for stack in goal_stacks for b in stack]
    if sorted(init_blocks) != sorted(blocks) or sorted(goal_blocks) != sorted(blocks):
        print("No plan")
        return

    support = {b: 0 for b in blocks}
    for stack in initial_stacks:
        for i, b in enumerate(stack):
            support[b] = 0 if i == 0 else stack[i - 1]

    hand = None
    plan = []

    def is_clear(b):
        return not any(s == b for s in support.values())

    def apply_action(action, *args):
        nonlocal hand
        if action == "pickup":
            (b,) = args
            if hand is not None or support[b] != 0 or not is_clear(b):
                return False
            hand = b
            support[b] = -1
        elif action == "putdown":
            (b,) = args
            if hand != b or support[b] != -1:
                return False
            hand = None
            support[b] = 0
        elif action == "unstack":
            (b, under) = args
            if hand is not None or support[b] != under or under == 0 or not is_clear(b):
                return False
            hand = b
            support[b] = -1
        elif action == "stack":
            (b, under) = args
            if hand != b or support[b] != -1 or under == b or not is_clear(under) or support[under] == -1:
                return False
            support[b] = under
            hand = None
        else:
            return False

        plan.append(f"({action} " + " ".join(args) + ")")
        return True

    for stack in initial_stacks:
        for b in reversed(stack[1:]):
            under = support[b]
            if not apply_action("unstack", b, under) or not apply_action("putdown", b):
                print("No plan")
                return

    for stack in goal_stacks:
        bottom = stack[0]
        if support[bottom] != 0 or not is_clear(bottom):
            print("No plan")
            return

        current = bottom
        for b in stack[1:]:
            if support[b] != 0 or not is_clear(b):
                print("No plan")
                return
            if not apply_action("pickup", b) or not apply_action("stack", b, current):
                print("No plan")
                return
            current = b

    goal_support = {b: 0 for b in blocks}
    for stack in goal_stacks:
        for i, b in enumerate(stack):
            goal_support[b] = 0 if i == 0 else stack[i - 1]

    if hand is not None or any(support[b] != goal_support[b] for b in blocks):
        print("No plan")
        return

    sys.stdout.write("\n".join(plan))
    if plan:
        sys.stdout.write("\n")

