from collections import deque

BLOCKS = [f"block{i}" for i in range(1, 9)]
IDX = {b: i for i, b in enumerate(BLOCKS)}


def make_state(assignments):
    state = ["table"] * len(BLOCKS)
    for block, support in assignments:
        state[IDX[block]] = support
    return tuple(state)


INITIAL = make_state([
    ("block4", "table"),
    ("block7", "table"),
    ("block5", "table"),
    ("block3", "block5"),
    ("block6", "block3"),
    ("block2", "table"),
    ("block8", "block2"),
    ("block1", "table"),
])

GOAL = make_state([
    ("block8", "table"),
    ("block7", "block8"),
    ("block2", "block7"),
    ("block4", "block2"),
    ("block5", "block4"),
    ("block3", "block5"),
    ("block6", "table"),
    ("block1", "block6"),
])

REQUIRED_FINAL_ARM = "block3"


def held_block(state):
    for i, support in enumerate(state):
        if support == "arm":
            return BLOCKS[i]
    return None


def is_clear(state, block):
    i = IDX[block]
    return not any(support == block for support in state)


def valid_state(state):
    held = None
    for i, support in enumerate(state):
        if support == "arm":
            if held is not None:
                return False
            held = BLOCKS[i]
        elif support != "table" and support not in IDX:
            return False

    if held is not None and any(support == held for support in state):
        return False

    for i, support in enumerate(state):
        if support == BLOCKS[i]:
            return False

    block_supports = [support for support in state if support in IDX]
    if len(block_supports) != len(set(block_supports)):
        return False

    return True


def consistent_goal():
    if REQUIRED_FINAL_ARM is not None:
        if GOAL[IDX[REQUIRED_FINAL_ARM]] != "arm":
            return False
        for block in BLOCKS:
            if block != REQUIRED_FINAL_ARM and GOAL[IDX[block]] == "arm":
                return False
    else:
        if any(support == "arm" for support in GOAL):
            return False

    return valid_state(GOAL)


def is_goal(state):
    if state != GOAL:
        return False
    if REQUIRED_FINAL_ARM is not None:
        return held_block(state) == REQUIRED_FINAL_ARM
    return held_block(state) is None


def solve():
    if not consistent_goal():
        print("No plan")
        return

    if not valid_state(INITIAL):
        print("No plan")
        return

    if is_goal(INITIAL):
        return

    parent = {INITIAL: None}
    queue = deque([INITIAL])

    while queue:
        state = queue.popleft()

        if is_goal(state):
            actions = []
            current = state
            while parent[current] is not None:
                previous, action = parent[current]
                actions.append(action)
                current = previous
            for action in reversed(actions):
                print(action)
            return

        held = held_block(state)

        for block in BLOCKS:
            i = IDX[block]

            if held is None and state[i] == "table" and is_clear(state, block):
                new_state = list(state)
                new_state[i] = "arm"
                ns = tuple(new_state)
                if ns not in parent:
                    parent[ns] = (state, f"(pickup {block})")
                    queue.append(ns)

            if held == block:
                new_state = list(state)
                new_state[i] = "table"
                ns = tuple(new_state)
                if ns not in parent:
                    parent[ns] = (state, f"(putdown {block})")
                    queue.append(ns)

            if held is None and state[i] in IDX and is_clear(state, block):
                below = state[i]
                new_state = list(state)
                new_state[i] = "arm"
                ns = tuple(new_state)
                if ns not in parent:
                    parent[ns] = (state, f"(unstack {block} {below})")
                    queue.append(ns)

            if held == block:
                for other in BLOCKS:
                    if other == block:
                        continue
                    j = IDX[other]
                    if state[j] == "arm":
                        continue
                    if is_clear(state, other):
                        new_state = list(state)
                        new_state[i] = other
                        ns = tuple(new_state)
                        if ns not in parent:
                            parent[ns] = (state, f"(stack {block} {other})")
                            queue.append(ns)

    print("No plan")


