    solve()

import sys

TABLE = -2
HELD = -1


def main():
    blocks = [chr(ord('a') + i) for i in range(13)]
    idx = {b: i for i, b in enumerate(blocks)}
    n = len(blocks)
    goal = blocks[:]

    def build_initial():
        on = [TABLE] * n

        def put(b, support):
            if support == TABLE:
                on[idx[b]] = TABLE
            else:
                on[idx[b]] = idx[support]

        put('a', TABLE)
        put('b', 'a')
        put('c', 'b')

        put('d', TABLE)
        put('e', 'd')
        put('f', 'e')
        on[idx['g']] = HELD

        put('h', TABLE)
        put('i', 'h')
        put('j', 'i')
        put('k', 'j')
        put('l', 'k')
        put('m', TABLE)

        return on, idx['g']

    init_on, init_held = build_initial()
    on = init_on.copy()
    held = init_held
    actions = []

    def name(i):
        return blocks[i]

    def add(action, *args):
        actions.append((action,) + args)

    def is_clear(i):
        for j in range(n):
            if on[j] == i:
                return False
        return True

    def free_hand():
        nonlocal held
        if held != -1:
            add('putdown', name(held))
            on[held] = TABLE
            held = -1

    def move_to_table(i):
        nonlocal held

        if held == i:
            add('putdown', name(i))
            on[i] = TABLE
            held = -1
            return

        while True:
            above = -1
            for j in range(n):
                if on[j] == i:
                    above = j
                    break
            if above == -1:
                break
            move_to_table(above)

        if on[i] == TABLE:
            free_hand()
            return

        free_hand()
        support = on[i]
        add('unstack', name(i), name(support))
        on[i] = HELD
        held = i
        add('putdown', name(i))
        on[i] = TABLE
        held = -1

    def clear_support(support):
        if support == TABLE:
            return

        while True:
            above = -1
            for j in range(n):
                if on[j] == support:
                    above = j
                    break
            if above == -1:
                break
            move_to_table(above)

    def place_block(i, support):
        nonlocal held

        if held != i and on[i] == support:
            return

        if held == i:
            if support == TABLE:
                add('putdown', name(i))
                on[i] = TABLE
                held = -1
            else:
                if not is_clear(support):
                    add('putdown', name(i))
                    on[i] = TABLE
                    held = -1
                    clear_support(support)
                    add('pickup', name(i))
                    on[i] = HELD
                    held = i
                add('stack', name(i), name(support))
                on[i] = support
                held = -1
            return

        if support == TABLE:
            move_to_table(i)
            return

        while True:
            above = -1
            for j in range(n):
                if on[j] == i:
                    above = j
                    break
            if above == -1:
                break
            move_to_table(above)

        clear_support(support)
        free_hand()

        if on[i] == TABLE:
            add('pickup', name(i))
            on[i] = HELD
            held = i
        else:
            old_support = on[i]
            add('unstack', name(i), name(old_support))
            on[i] = HELD
            held = i

        add('stack', name(i), name(support))
        on[i] = support
        held = -1

    for pos, b in enumerate(goal):
        bi = idx[b]
        support = TABLE if pos == 0 else idx[goal[pos - 1]]
        place_block(bi, support)

    def validate(plan):
        on2 = init_on.copy()
        held2 = init_held

        def clear2(i):
            for j in range(n):
                if on2[j] == i:
                    return False
            return True

        for act in plan:
            if not act:
                return False

            if act[0] == 'pickup':
                if len(act) != 2:
                    return False
                x = idx.get(act[1])
                if x is None:
                    return False
                if held2 != -1 or on2[x] != TABLE or not clear2(x):
                    return False
                held2 = x
                on2[x] = HELD

            elif act[0] == 'putdown':
                if len(act) != 2:
                    return False
                x = idx.get(act[1])
                if x is None or held2 != x:
                    return False
                held2 = -1
                on2[x] = TABLE

            elif act[0] == 'unstack':
                if len(act) != 3:
                    return False
                x = idx.get(act[1])
                y = idx.get(act[2])
                if x is None or y is None:
                    return False
                if held2 != -1 or on2[x] != y or not clear2(x):
                    return False
                held2 = x
                on2[x] = HELD

            elif act[0] == 'stack':
                if len(act) != 3:
                    return False
                x = idx.get(act[1])
                y = idx.get(act[2])
                if x is None or y is None:
                    return False
                if held2 != x or x == y or on2[y] == HELD or not clear2(y):
                    return False
                held2 = -1
                on2[x] = y

            else:
                return False

        if held2 != -1:
            return False
        if on2[idx[goal[0]]] != TABLE:
            return False
        for pos in range(1, n):
            if on2[idx[goal[pos]]] != idx[goal[pos - 1]]:
                return False
        return True

    if not validate(actions):
        sys.stdout.write("No plan")
        return

    out = []
    for act in actions:
        if len(act) == 2:
            out.append(f"({act[0]} {act[1]})")
        elif len(act) == 3:
            out.append(f"({act[0]} {act[1]} {act[2]})")
        else:
            sys.stdout.write("No plan")
            return

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

import collections

BLOCKS = tuple(f"block{i}" for i in range(1, 11))
INITIAL_TABLE = (
    "block10", "block4", "block3", "block2", "block9",
    "block7", "block8", "block6", "block5", "block1"
)
GOAL_TABLE = (
    "block8", "block5", "block3", "block10", "block9",
    "block2", "block6", "block7", "block4", "block1"
)


def initial_state():
    on_top = {b: None for b in BLOCKS}
    below = {b: None for b in BLOCKS}
    return (
        INITIAL_TABLE,
        None,
        frozenset(on_top.items()),
        frozenset(below.items()),
        frozenset(),
    )


def is_goal(state):
    table, held, _, _, _ = state
    return held is None and table == GOAL_TABLE


def successors(state):
    table, held, on_top_fs, below_fs, picked = state
    on_top = dict(on_top_fs)
    below = dict(below_fs)

    # The goal requires every block to be directly on the table.  A block in
    # `picked` can never be put down again, so it can never be on the table
    # in a goal state.
    if picked:
        return

    if held is None:
        for b in table:
            if on_top[b] is None:
                new_table = tuple(x for x in table if x != b)
                new_on_top = dict(on_top)
                new_on_top[b] = None
                new_below = dict(below)
                new_below[b] = None
                new_picked = picked | {b}
                yield (
                    ("pickup", b),
                    (
                        new_table,
                        b,
                        frozenset(new_on_top.items()),
                        frozenset(new_below.items()),
                        new_picked,
                    ),
                )

        for x in BLOCKS:
            y = below[x]
            if y is not None and on_top[x] is None:
                new_on_top = dict(on_top)
                new_on_top[y] = None
                new_on_top[x] = None
                new_below = dict(below)
                new_below[x] = None
                new_picked = picked | {x}
                yield (
                    ("unstack", x, y),
                    (
                        table,
                        x,
                        frozenset(new_on_top.items()),
                        frozenset(new_below.items()),
                        new_picked,
                    ),
                )
    else:
        x = held
        if x not in picked:
            new_table = table + (x,)
            new_on_top = dict(on_top)
            new_on_top[x] = None
            new_below = dict(below)
            new_below[x] = None
            yield (
                ("putdown", x),
                (
                    new_table,
                    None,
                    frozenset(new_on_top.items()),
                    frozenset(new_below.items()),
                    picked,
                ),
            )

        for y in BLOCKS:
            if y == x:
                continue
            if on_top[y] is not None:
                continue
            new_on_top = dict(on_top)
            new_on_top[y] = x
            new_on_top[x] = None
            new_below = dict(below)
            new_below[x] = y
            yield (
                ("stack", x, y),
                (
                    table,
                    None,
                    frozenset(new_on_top.items()),
                    frozenset(new_below.items()),
                    picked,
                ),
            )


def format_action(action):
    return "(" + " ".join(action) + ")"


def solve():
    start = initial_state()
    if is_goal(start):
        return []

    queue = collections.deque([start])
    parent = {start: (None, None)}

    while queue:
        state = queue.popleft()
        for action, nxt in successors(state):
            if nxt in parent:
                continue
            parent[nxt] = (state, action)
            if is_goal(nxt):
                plan = []
                cur = nxt
                while parent[cur][1] is not None:
                    plan.append(parent[cur][1])
                    cur = parent[cur][0]
                plan.reverse()
                return plan
            queue.append(nxt)

    return None


def main():
    plan = solve()
    if plan is None:
        print("No plan")
    else:
        for action in plan:
            print(format_action(action))


if __name__ == "__main__":
    main()

import heapq

BLOCKS = tuple(f"block{i}" for i in range(1, 13))
BLOCK_SET = frozenset(BLOCKS)


def num(block):
    return int(block[5:])


def initial_state():
    on_table = frozenset({
        "block10", "block5", "block7", "block9", "block3"
    })
    on = frozenset({
        ("block1", "block10"),
        ("block4", "block5"),
        ("block2", "block4"),
        ("block6", "block9"),
        ("block8", "block3"),
        ("block11", "block8"),
        ("block12", "block11"),
    })
    return (None, on_table, on)


REQUIRED_TABLE = frozenset({
    "block11", "block1", "block5", "block3", "block7",
    "block8", "block9", "block4", "block6", "block2", "block12"
})
REQUIRED_ON = frozenset({("block10", "block11")})


def first_goal(state):
    holding, on_table, on = state
    return holding is None and on_table == REQUIRED_TABLE and on == REQUIRED_ON


def additional_goal(state):
    holding, on_table, on = state
    if holding is not None:
        return False
    if len(on_table) != 3:
        return False

    on_bottom = frozenset(top for top, _ in on)
    if (on_table | on_bottom) != BLOCK_SET:
        return False
    if len(on) != len(on_bottom):
        return False
    if len({bottom for _, bottom in on}) != len(on):
        return False

    on_top = {bottom: top for top, bottom in on}
    stacks = []
    for base in on_table:
        stack = [base]
        current = base
        while current in on_top:
            current = on_top[current]
            stack.append(current)
        stacks.append(stack)

    if len(stacks) != 3:
        return False

    expected = [
        [b for b in BLOCKS if num(b) % 4 == 0],
        [b for b in BLOCKS if num(b) % 2 == 1 and num(b) % 4 != 0],
        [b for b in BLOCKS if num(b) % 2 == 0 and num(b) % 4 != 0],
    ]

    used = [False, False, False]
    for stack in stacks:
        values = [num(b) for b in stack]
        if values != sorted(values):
            return False

        stack_set = frozenset(stack)
        for i, exp in enumerate(expected):
            if not used[i] and stack_set == frozenset(exp):
                used[i] = True
                break
        else:
            return False

    return all(used)


def goal(state):
    return first_goal(state) and additional_goal(state)


def successors(state):
    holding, on_table, on = state
    on_top = {bottom: top for top, bottom in on}
    actions = []

    if holding is None:
        for b in BLOCKS:
            if b in on_table and b not in on_top:
                actions.append(("pickup", b))

        for top, bottom in on:
            if top not in on_top:
                actions.append(("unstack", top, bottom))

    if holding is not None:
        actions.append(("putdown", holding))

        for y in BLOCKS:
            if y == holding:
                continue
            if y in on_top:
                continue
            actions.append(("stack", holding, y))

    return actions


def apply_action(state, action):
    holding, on_table, on = state
    kind = action[0]

    if kind == "pickup":
        b = action[1]
        return (b, on_table - {b}, on)

    if kind == "putdown":
        b = action[1]
        return (None, on_table | {b}, on)

    if kind == "unstack":
        x, y = action[1], action[2]
        return (x, on_table, on - {(x, y)})

    if kind == "stack":
        x, y = action[1], action[2]
        return (None, on_table, on | {(x, y)})

    raise ValueError


def support_map(state):
    holding, on_table, on = state
    m = {}
    for b in on_table:
        m[b] = "table"
    for top, bottom in on:
        m[top] = bottom
    if holding is not None:
        m[holding] = "arm"
    return m


GOAL_SUPPORT = {}
for b in REQUIRED_TABLE:
    GOAL_SUPPORT[b] = "table"
for top, bottom in REQUIRED_ON:
    GOAL_SUPPORT[top] = bottom


def heuristic(state):
    current = support_map(state)
    return sum(1 for b in BLOCKS if current.get(b) != GOAL_SUPPORT.get(b))


def solve():
    start = initial_state()
    if goal(start):
        return []

    g_score = {start: 0}
    came_from = {start: (None, None)}
    counter = 0
    open_heap = [(heuristic(start), 0, counter, start)]

    while open_heap:
        f, g, _, state = heapq.heappop(open_heap)
        if g != g_score.get(state, 10**18):
            continue

        if goal(state):
            plan = []
            cur = state
            while came_from[cur][0] is not None:
                prev, action = came_from[cur]
                plan.append(action)
                cur = prev
            plan.reverse()
            return plan

        for action in successors(state):
            nxt = apply_action(state, action)
            ng = g + 1
            if ng < g_score.get(nxt, 10**18):
                g_score[nxt] = ng
                came_from[nxt] = (state, action)
                counter += 1
                heapq.heappush(open_heap, (ng + heuristic(nxt), ng, counter, nxt))

    return None


def main():
    first_state = (None, REQUIRED_TABLE, REQUIRED_ON)

    if not additional_goal(first_state):
        print("No plan")
        return

    plan = solve()
    if plan is None:
        print("No plan")
    else:
        for action in plan:
            print("({})".format(" ".join(action)))


if __name__ == "__main__":
    main()

