    for b, s in goal.items():
        if s != table:
            support_count[s] = support_count.get(s, 0) + 1

    if any(c > 1 for c in support_count.values()):
        fail()
        return

    dependents = {b: [] for b in blocks}
    for b, s in goal.items():
        if s != table:
            dependents[s].append(b)

    queue = [b for b in blocks if goal[b] == table]
    order = []
    while queue:
        b = queue.pop(0)
        order.append(b)
        queue.extend(dependents[b])

    if len(order) != len(blocks):
        fail()
        return

    holding = None
    plan = []

    def is_clear(b):
        return all(on[x] != b for x in blocks)

    def unstack(x, y):
        nonlocal holding
        if holding is not None:
            return False
        if y == table:
            return False
        if on.get(x) != y:
            return False
        if not is_clear(x):
            return False

        holding = x
        on[x] = arm
        plan.append(f"(unstack {x} {y})")
        return True

    def putdown(x):
        nonlocal holding
        if holding != x:
            return False

        holding = None
        on[x] = table
        plan.append(f"(putdown {x})")
        return True

    def pickup(x):
        nonlocal holding
        if holding is not None:
            return False
        if on.get(x) != table:
            return False
        if not is_clear(x):
            return False

        holding = x
        on[x] = arm
        plan.append(f"(pickup {x})")
        return True

    def stack(x, y):
        nonlocal holding
        if holding != x:
            return False
        if y == table:
            return False
        if on.get(x) != arm:
            return False
        if not is_clear(y):
            return False

        holding = None
        on[x] = y
        plan.append(f"(stack {x} {y})")
        return True

    # Clear all stacks to the table.
    for _ in range(2 * len(blocks) + 1):
        top = None
        for b in blocks:
            if on[b] != table and on[b] != arm and is_clear(b):
                top = b
                break

        if top is None:
            break

        support = on[top]
        if not unstack(top, support) or not putdown(top):
            fail()
            return

    if holding is not None or any(on[b] != table for b in blocks):
        fail()
        return

    # Build the goal configuration bottom-up.
    for b in order:
        s = goal[b]

        if s == table:
            if on[b] != table:
                fail()
                return
            continue

        if on[b] != table or not is_clear(b):
            fail()
            return

        if not pickup(b) or not stack(b, s):
            fail()
            return

    if holding is not None or any(on[b] != goal[b] for b in blocks):
        fail()
        return

    if plan:
        sys.stdout.write("\n".join(plan) + "\n")


