import sys
import heapq


def main():
    n = 14
    names = [f"block{i}" for i in range(1, n + 1)]

    initial = [-1] * n
    initial[13] = -1
    initial[12] = 13
    initial[4] = 12
    initial[8] = 4
    initial[10] = 8
    initial[1] = 10
    initial[5] = 1
    initial[6] = 5
    initial[9] = 6
    initial[7] = 9
    initial[11] = 7
    initial[0] = -1
    initial[2] = 0
    initial[3] = 2
    start = tuple(initial)

    goal = [-1] * n
    goal[4] = 10
    goal = tuple(goal)

    def is_clear(state, b):
        for i in range(n):
            if state[i] == b:
                return False
        return True

    def held(state):
        for i, v in enumerate(state):
            if v == -2:
                return i
        return -1

    def heuristic(state):
        hb = held(state)
        total = 0
        for i, v in enumerate(state):
            if v != goal[i]:
                total += 1 if i == hb else 2
        return total

    def successors(state):
        result = []
        hb = held(state)

        if hb != -1:
            nxt = list(state)
            nxt[hb] = -1
            result.append((tuple(nxt), f"(putdown {names[hb]})"))

            for s in range(n):
                if s == hb:
                    continue
                if state[s] == -2:
                    continue
                if is_clear(state, s):
                    nxt = list(state)
                    nxt[hb] = s
                    result.append((tuple(nxt), f"(stack {names[hb]} {names[s]})"))
        else:
            for b in range(n):
                if state[b] == -1:
                    if is_clear(state, b):
                        nxt = list(state)
                        nxt[b] = -2
                        result.append((tuple(nxt), f"(pickup {names[b]})"))
                elif state[b] >= 0:
                    if is_clear(state, b):
                        s = state[b]
                        nxt = list(state)
                        nxt[b] = -2
                        result.append((tuple(nxt), f"(unstack {names[b]} {names[s]})"))

        return result

    counter = 0
    heap = [(heuristic(start), 0, counter, start)]
    g_score = {start: 0}
    parent = {start: (None, None)}

    while heap:
        _, neg_g, _, state = heapq.heappop(heap)
        g = -neg_g

        if g != g_score.get(state, 10**9):
            continue

        if state == goal:
            plan = []
            cur = state
            while parent[cur][0] is not None:
                prev, action = parent[cur]
                plan.append(action)
                cur = prev
            plan.reverse()
            sys.stdout.write("\n".join(plan))
            return

        for ns, action in successors(state):
            ng = g + 1
            if ng < g_score.get(ns, 10**9):
                g_score[ns] = ng
                parent[ns] = (state, action)
                counter += 1
                heapq.heappush(heap, (ng + heuristic(ns), -ng, counter, ns))

    sys.stdout.write("No plan")


