import sys
from collections import deque

BLOCKS = tuple(f"block{i}" for i in range(1, 11))
TABLE = "table"
ARM = "arm"
REQUIRED_STACKS = 10


def initial_state():
    support = {b: TABLE for b in BLOCKS}

    # Initial stacks:
    # table <- block8 <- block4 <- block1 <- block2
    support["block4"] = "block8"
    support["block1"] = "block4"
    support["block2"] = "block1"

    # table <- block3 <- block6
    support["block6"] = "block3"

    # table <- block5 <- block10
    support["block10"] = "block5"

    # block7 and block9 are single table stacks.
    # Arm is empty and no block has been moved yet.
    return (None, tuple(support[b] for b in BLOCKS), False)


def is_goal(arm, support):
    return arm is None and all(s == TABLE for s in support)


def stack_count(arm, support):
    # Count stack roots: blocks directly on the table or held by the arm.
    return sum(1 for s in support if s == TABLE or s == ARM)


def is_valid(arm, support):
    if arm is None:
        return ARM not in support

    if support.count(ARM) != 1:
        return False

    if support[BLOCKS.index(arm)] != ARM:
        return False

    # No block may be on top of a held block.
    for s in support:
        if s != TABLE and s != ARM:
            if support[BLOCKS.index(s)] == ARM:
                return False

    return True


def successors(arm, support, started):
    sup = dict(zip(BLOCKS, support))

    def clear(block):
        return not any(s == block for s in sup.values())

    if arm is None:
        # pickup X: X is on the table and clear.
        for x in BLOCKS:
            if sup[x] == TABLE and clear(x):
                ns = sup.copy()
                ns[x] = ARM
                new_support = tuple(ns[b] for b in BLOCKS)
                if is_valid(x, new_support):
                    yield ("pickup", x), (x, new_support, True)

        # unstack X Y: X is on block Y and clear.
        for x in BLOCKS:
            y = sup[x]
            if y != TABLE and y != ARM and clear(x):
                ns = sup.copy()
                ns[x] = ARM
                new_support = tuple(ns[b] for b in BLOCKS)
                if is_valid(x, new_support):
                    yield ("unstack", x, y), (x, new_support, True)

    else:
        x = arm

        # putdown X: place held block X on the table.
        ns = sup.copy()
        ns[x] = TABLE
        new_support = tuple(ns[b] for b in BLOCKS)
        if is_valid(None, new_support):
            yield ("putdown", x), (None, new_support, True)

        # stack X Y: place held block X on clear block Y.
        for y in BLOCKS:
            if y != x and sup[y] != ARM and clear(y):
                ns = sup.copy()
                ns[x] = y
                new_support = tuple(ns[b] for b in BLOCKS)
                if is_valid(None, new_support):
                    yield ("stack", x, y), (None, new_support, True)


def solve():
    start = initial_state()

    if is_goal(start[0], start[1]):
        return []

    queue = deque([start])
    parent = {start: (None, None)}

    while queue:
        state = queue.popleft()

        for action, nstate in successors(state[0], state[1], state[2]):
            # The extra constraint applies after the first action.
            if nstate[2] and stack_count(nstate[0], nstate[1]) != REQUIRED_STACKS:
                continue

            if nstate in parent:
                continue

            parent[nstate] = (state, action)

            if is_goal(nstate[0], nstate[1]):
                plan = []
                cur = nstate
                while parent[cur][0] is not None:
                    prev, act = parent[cur]
                    plan.append(act)
                    cur = prev
                plan.reverse()
                return plan

            queue.append(nstate)

    return None


def main():
    plan = solve()

    if plan is None:
        print("No plan")
        return

    lines = []
    for action in plan:
        if len(action) == 2:
            lines.append(f"({action[0]} {action[1]})")
        else:
            lines.append(f"({action[0]} {action[1]} {action[2]})")

    if lines:
        print("\n".join(lines))


if __name__ == "__main__":
    main()

def main():
    n = 14
    blocks = list(range(1, n + 1))

    def name(b):
        return "block" + str(b)

    initial = [0] * (n + 1)
    initial[13] = 12
    initial[5] = 1
    initial[3] = 10
    initial[8] = 11
    initial[14] = 8
