    goal[1] = 4
    goal[12] = 10
    goal[7] = 3
    goal[11] = 7
    goal[5] = 8

    plan = []
    state = initial[:]

    def covered(on):
        cov = set()
        for b in blocks:
            s = on[b]
            if s != 0 and s != -1:
                cov.add(s)
        return cov

    while True:
        cov = covered(state)
        moved = False
        for b in blocks:
            s = state[b]
            if s != 0 and b not in cov:
                plan.append(f"(unstack {name(b)} {name(s)})")
                state[b] = -1
                plan.append(f"(putdown {name(b)})")
                state[b] = 0
                moved = True
                break
        if not moved:
            break

    goal_stacks = []
    for b in blocks:
        if goal[b] == 0:
            stack = [b]
            cur = b
            while True:
                nxt = None
                for c in blocks:
                    if goal[c] == cur:
                        nxt = c
                        break
                if nxt is None:
                    break
                stack.append(nxt)
                cur = nxt
            goal_stacks.append(stack)

    for stack in goal_stacks:
        cur = stack[0]
        for top in stack[1:]:
            plan.append(f"(pickup {name(top)})")
            state[top] = -1
            plan.append(f"(stack {name(top)} {name(cur)})")
            state[top] = cur
            cur = top

    def is_clear(on, b):
        for c in blocks:
            if on[c] == b:
                return False
        return True

    def valid_plan(plan, start, target):
        on = start[:]
        holding = 0
        for action in plan:
            parts = action.strip().strip("()").split()
            op = parts[0]
            if op == "pickup":
                b = int(parts[1].replace("block", ""))
                if holding != 0 or on[b] != 0 or not is_clear(on, b):
                    return False
                on[b] = -1
                holding = b
            elif op == "putdown":
                b = int(parts[1].replace("block", ""))
                if holding != b or on[b] != -1:
                    return False
                on[b] = 0
                holding = 0
            elif op == "unstack":
                b = int(parts[1].replace("block", ""))
                s = int(parts[2].replace("block", ""))
                if holding != 0 or on[b] != s or not is_clear(on, b):
                    return False
                on[b] = -1
                holding = b
            elif op == "stack":
                b = int(parts[1].replace("block", ""))
                s = int(parts[2].replace("block", ""))
                if holding != b or on[b] != -1 or on[s] == -1 or not is_clear(on, s):
                    return False
                on[b] = s
                holding = 0
            else:
                return False
        return holding == 0 and on == target

    if not valid_plan(plan, initial, goal):
        print("No plan")
    else:
        for line in plan:
            print(line)

