import sys


def block_name(i):
    return f"block{i}"


def main():
    blocks = tuple(range(1, 12))

    # Bottom-to-top stacks.
    initial_stacks = [
        [8, 2, 5, 7],
        [9, 10, 1, 3, 11, 4, 6],
    ]

    # Bottom-to-top goal tower.
    goal_order = [7, 4, 11, 2, 9, 5, 8, 10, 1, 3, 6]

    if sorted(b for stack in initial_stacks for b in stack) != list(blocks):
        print("No plan")
        return

    if sorted(goal_order) != list(blocks):
        print("No plan")
        return

    # loc[b] is:
    #   None  -> on the table
    #   int   -> on block int
    #   "arm" -> held by the arm
    loc = {b: None for b in blocks}
    for stack in initial_stacks:
        for lower, upper in zip(stack, stack[1:]):
            loc[upper] = lower

    plan = []
    arm = None

    def clear_blocks():
        on_top = {loc[b] for b in blocks if isinstance(loc[b], int)}
        return {b for b in blocks if b not in on_top and loc[b] != "arm"}

    def state_valid():
        if arm is not None and loc[arm] != "arm":
            return False

        for b in blocks:
            v = loc[b]
            if v == "arm":
                if b != arm:
                    return False
            elif v is None:
                pass
            elif isinstance(v, int):
                if v not in blocks or v == b:
                    return False
                if loc[v] == "arm":
                    return False
            else:
                return False

        support_count = {}
        for b in blocks:
            v = loc[b]
            if isinstance(v, int):
                support_count[v] = support_count.get(v, 0) + 1
                if support_count[v] > 1:
                    return False

        for start in blocks:
            seen = set()
            cur = start
            while cur is not None:
                if cur in seen:
                    return False
                seen.add(cur)
                v = loc[cur]
                if v == "arm":
                    break
                if not isinstance(v, int):
                    break
                cur = v

        return True

    if not state_valid():
        print("No plan")
        return

    def do_pickup(b):
        nonlocal arm
        if (
            arm is not None
            or loc[b] is not None
            or b not in clear_blocks()
            or not state_valid()
        ):
            return False
        arm = b
        loc[b] = "arm"
        plan.append(f"(pickup {block_name(b)})")
        return True

    def do_putdown(b):
        nonlocal arm
        if arm != b or loc[b] != "arm" or not state_valid():
            return False
        arm = None
        loc[b] = None
        plan.append(f"(putdown {block_name(b)})")
        return True

    def do_unstack(x, y):
        nonlocal arm
        if (
            arm is not None
            or loc[x] != y
            or x not in clear_blocks()
            or not state_valid()
        ):
            return False
        arm = x
        loc[x] = "arm"
        plan.append(f"(unstack {block_name(x)} {block_name(y)})")
        return True

    def do_stack(x, y):
        nonlocal arm
        if (
            arm != x
            or loc[x] != "arm"
            or y not in clear_blocks()
            or loc[y] == "arm"
            or x == y
            or not state_valid()
        ):
            return False
        arm = None
        loc[x] = y
        plan.append(f"(stack {block_name(x)} {block_name(y)})")
        return True

    # Move every block that is not already on the table to the table.
    for stack in initial_stacks:
        for b in reversed(stack[1:]):
            support = loc[b]
            if not isinstance(support, int):
                print("No plan")
                return
            if not do_unstack(b, support) or not do_putdown(b):
                print("No plan")
                return

    # Build the goal tower from bottom to top.
    previous = goal_order[0]

    if loc[previous] is not None:
        if isinstance(loc[previous], int):
            if not do_unstack(previous, loc[previous]) or not do_putdown(previous):
                print("No plan")
                return
        elif loc[previous] == "arm":
            if not do_putdown(previous):
                print("No plan")
                return

    for b in goal_order[1:]:
        if loc[b] is not None:
            if isinstance(loc[b], int):
                if not do_unstack(b, loc[b]) or not do_putdown(b):
                    print("No plan")
                    return
            elif loc[b] == "arm":
                if not do_putdown(b):
                    print("No plan")
                    return

        if not do_pickup(b) or not do_stack(b, previous):
            print("No plan")
            return

        previous = b

    if arm is not None:
        print("No plan")
        return

    for i, b in enumerate(goal_order):
        expected = None if i == 0 else goal_order[i - 1]
        if loc[b] != expected:
            print("No plan")
            return

    sys.stdout.write("\n".join(plan))
    if plan:
        sys.stdout.write("\n")


