    main()

def main():
    blocks = [f"block{i}" for i in range(1, 12)]

    initial_on = {
        "block8": "table",
        "block2": "block8",
        "block5": "block2",
        "block7": "block5",
        "block9": "table",
        "block10": "block9",
        "block1": "block10",
        "block3": "block1",
        "block11": "block3",
        "block4": "block11",
        "block6": "block4",
    }

    goal_seq = [
        "block7",
        "block4",
        "block11",
        "block2",
        "block9",
        "block5",
        "block8",
        "block10",
        "block1",
        "block3",
        "block6",
    ]

    if set(initial_on) != set(blocks) or set(goal_seq) != set(blocks):
        print("No plan")
        return

    on = dict(initial_on)
    on_top = {b: set() for b in blocks}
    on_top["table"] = set()

    for b, s in on.items():
        if s == b:
            print("No plan")
            return
        if s == "table":
            if b in on_top["table"]:
                print("No plan")
                return
            on_top["table"].add(b)
        else:
            if s not in on_top:
                print("No plan")
                return
            if b in on_top[s]:
                print("No plan")
                return
            on_top[s].add(b)

    held = None
    plan = []

    def is_clear(b):
        return not on_top.get(b, set())

    def do_pickup(b):
        nonlocal held
        if held is not None:
            return False
        if on.get(b) != "table":
            return False
        if b not in on_top["table"]:
            return False
        if not is_clear(b):
            return False
        on_top["table"].remove(b)
        on[b] = None
        held = b
        plan.append(f"(pickup {b})")
        return True

    def do_putdown(b):
        nonlocal held
        if held != b:
            return False
        if on.get(b) is not None:
            return False
        on_top["table"].add(b)
        on[b] = "table"
        held = None
        plan.append(f"(putdown {b})")
        return True

    def do_unstack(x, y):
        nonlocal held
        if held is not None:
            return False
        if x == y:
            return False
        if y == "table" or y not in on_top:
            return False
        if on.get(x) != y:
            return False
        if x not in on_top[y]:
            return False
        if not is_clear(x):
            return False
        on_top[y].remove(x)
        on[x] = None
        held = x
        plan.append(f"(unstack {x} {y})")
        return True

    def do_stack(x, y):
        nonlocal held
        if held != x:
            return False
        if x == y:
            return False
        if y == "table" or y not in on_top:
            return False
        if on.get(y) is None:
            return False
        if not is_clear(y):
            return False
        on_top[y].add(x)
        on[x] = y
        held = None
        plan.append(f"(stack {x} {y})")
        return True

    def ensure_clear(b):
        while not is_clear(b):
            tops = on_top.get(b, set())
            if len(tops) != 1:
                return False
            y = next(iter(tops))
            if not move_to_table(y):
                return False
        return True

    def move_to_table(x):
        if not ensure_clear(x):
            return False
        if on.get(x) == "table":
            return x in on_top["table"]
        if on.get(x) is None:
            return False
        s = on[x]
        if not do_unstack(x, s):
            return False
        if not do_putdown(x):
            return False
        return True

    def supported_by_table(b):
        seen = set()
        cur = b
        while True:
            if cur in seen:
                return False
            seen.add(cur)
            if cur == "table":
                return True
            cur = on.get(cur)
            if cur is None:
                return False

    if held is not None:
        print("No plan")
        return

    if not all(supported_by_table(b) for b in blocks):
        print("No plan")
        return

    for i, b in enumerate(goal_seq):
        if not ensure_clear(b):
            print("No plan")
            return

        s = on.get(b)

        if i == 0:
            if s != "table":
                if s is None:
                    print("No plan")
                    return
                if not do_unstack(b, s):
                    print("No plan")
                    return
                if not do_putdown(b):
                    print("No plan")
                    return
        else:
            desired = goal_seq[i - 1]
            if s != desired:
                if s == "table":
                    if not do_pickup(b):
                        print("No plan")
                        return
                elif s is None:
                    print("No plan")
                    return
                else:
                    if not do_unstack(b, s):
                        print("No plan")
                        return
                if not do_stack(b, desired):
                    print("No plan")
                    return

    if held is not None:
        print("No plan")
        return

    expected = {goal_seq[0]: "table"}
    for lower, upper in zip(goal_seq, goal_seq[1:]):
        expected[upper] = lower

    for b in blocks:
        if on.get(b) != expected.get(b):
            print("No plan")
            return

    for b in blocks:
        if len(on_top.get(b, set())) > 1:
            print("No plan")
            return

    for b in blocks:
        s = on.get(b)
        if s == "table":
            if b not in on_top["table"]:
                print("No plan")
                return
        elif s is None:
            print("No plan")
            return
        else:
            if s not in on_top or b not in on_top[s]:
                print("No plan")
                return

    if on_top["table"] != {b for b in blocks if on.get(b) == "table"}:
        print("No plan")
        return

    if plan:
        print("\n".join(plan))


