import heapq

N = 11
TABLE = 0
ARM = 12
EMPTY = -1
B1 = 0
B2 = 1

GOAL = bytes([...])
INITIAL = bytes([...])

def compute_top(support):
    top = [-1] * N
    for b, code in enumerate(support):
        if 1 <= code <= N:
            top[code - 1] = b
    return top

def heuristic(support, top=None):
    if top is None:
        top = compute_top(support)
    need = [False] * N
    for b in range(N):
        if support[b] != GOAL[b]:
            c = b
            # optional cycle guard
            seen = -1
            while c != -1:
                need[c] = True
                c = top[c]
    h = 0
    for b in range(N):
        if not need[b]:
            continue
        code = support[b]
        if code == ARM:
            gcode = GOAL[b]
            if gcode == TABLE:
                h += 1
            else:
                g = gcode - 1
                if need[g] or top[g] != -1:
                    h += 3
                else:
                    h += 1
        elif code == GOAL[b]:
            if code == TABLE:
                h += 0
            else:
                h += 4
        else:
            h += 2
    return h

import heapq


def main():
    names = [f"block{i}" for i in range(1, 11)]
    n = len(names)

    # Towers are listed bottom to top.
    towers = [
        [0, 9],       # block1, block10
        [3, 7],       # block4, block8
        [2, 8, 1],    # block3, block9, block2
        [4, 5, 6],    # block5, block6, block7
    ]

    goal = [-1] * n
    for tower in towers:
        goal[tower[0]] = -1
        for i in range(1, len(tower)):
            goal[tower[i]] = tower[i - 1]

    start_on = tuple([-1] * n)
    start = (start_on, -1)
    goal_state = (tuple(goal), -1)

    # Preferred block order: upper blocks bottom-up, then bases.
    order = []
    for tower in towers:
        order.extend(tower[1:])
    for b in range(n):
        if b not in order:
            order.append(b)

    def is_clear(on, b):
        for c in range(n):
            if on[c] == b:
                return False
        return True

    def heuristic(state):
        on, hand = state
        total = 0
        for b in range(n):
            if b == hand:
                total += 1
            elif on[b] != goal[b]:
                total += 2
        return total

    def apply_action(state, action):
        on = list(state[0])
        hand = state[1]

        if action[0] == "pickup":
            b = action[1]
            on[b] = -1
            hand = b
        elif action[0] == "putdown":
            b = action[1]
            on[b] = -1
            hand = -1
        elif action[0] == "unstack":
            b = action[1]
            on[b] = -1
            hand = b
        elif action[0] == "stack":
            b, y = action[1], action[2]
            on[b] = y
            hand = -1

        return (tuple(on), hand)

    def generate_actions(state):
        on, hand = state

        if hand != -1:
            b = hand
            target = goal[b]

            if target != -1 and target != b and is_clear(on, target):
                yield ("stack", b, target)

            if target == -1:
                yield ("putdown", b)

            for y in order:
                if y == b or y == target:
                    continue
                if is_clear(on, y):
                    yield ("stack", b, y)
        else:
            for b in order:
                if on[b] == -1 and is_clear(on, b):
                    yield ("pickup", b)

            for b in order:
                if on[b] != -1 and is_clear(on, b):
                    yield ("unstack", b, on[b])

    counter = 0
    h0 = heuristic(start)
    heap = [(h0, 0, h0, counter, start)]
    g_score = {start: 0}
    parent = {start: (None, None)}

    while heap:
        f, neg_g, h, _, state = heapq.heappop(heap)
        g = -neg_g

        if g != g_score.get(state):
            continue

        if state == goal_state:
            plan = []
            cur = state
            while parent[cur][0] is not None:
                prev, action = parent[cur]
                plan.append(action)
                cur = prev
            plan.reverse()

            for action in plan:
                if action[0] in ("pickup", "putdown"):
                    print(f"({action[0]} {names[action[1]]})")
                else:
                    print(f"({action[0]} {names[action[1]]} {names[action[2]]})")
            return

        for action in generate_actions(state):
            new_state = apply_action(state, action)
            ng = g + 1

            if ng < g_score.get(new_state, 10**9):
                g_score[new_state] = ng
                parent[new_state] = (state, action)
                nh = heuristic(new_state)
                counter += 1
                heapq.heappush(heap, (ng + nh, -ng, nh, counter, new_state))

    print("No plan")


