from collections import deque

BLOCKS = ("block1", "block2", "block3", "block4")

INITIAL_LOC = {b: "table" for b in BLOCKS}

GOAL_LOC = {
    "block1": "table",
    "block2": "block3",
    "block3": "table",
    "block4": "block1",
}


def loc_to_tuple(loc):
    return tuple(loc[b] for b in BLOCKS)


def tuple_to_loc(t):
    return dict(zip(BLOCKS, t))


def is_clear(loc, block):
    return all(loc[other] != block for other in BLOCKS if other != block)


def generate_actions(loc, arm):
    actions = []

    for b in BLOCKS:
        if arm is None and loc[b] == "table" and is_clear(loc, b):
            actions.append(("pickup", b))

        if arm == b:
            actions.append(("putdown", b))
            for c in BLOCKS:
                if c != b and loc[c] != "arm" and is_clear(loc, c):
                    actions.append(("stack", b, c))

        if arm is None:
            c = loc[b]
            if c not in ("table", "arm") and is_clear(loc, b):
                actions.append(("unstack", b, c))

    return actions


def apply_action(loc, arm, action):
    loc = dict(loc)
    kind = action[0]

    if kind == "pickup":
        b = action[1]
        loc[b] = "arm"
        arm = b

    elif kind == "putdown":
        b = action[1]
        loc[b] = "table"
        arm = None

    elif kind == "stack":
        b, c = action[1], action[2]
        loc[b] = c
        arm = None

    elif kind == "unstack":
        b, c = action[1], action[2]
        loc[b] = "arm"
        arm = b

    return loc, arm


def moved_block(action):
    return action[1]


def required_next(last_moved):
    if last_moved == "block1":
        return "block2"
    if last_moved == "block2":
        return "block3"
    return None


def is_goal(loc, arm, last_moved):
    if arm is not None:
        return False
    if any(loc[b] != GOAL_LOC[b] for b in BLOCKS):
        return False
    return required_next(last_moved) is None


def main():
    start_loc_t = loc_to_tuple(INITIAL_LOC)
    start = (start_loc_t, None, None, ())

    queue = deque([start])
    visited = {(start_loc_t, None, None)}

    while queue:
        loc_t, arm, last_moved, path = queue.popleft()
        loc = tuple_to_loc(loc_t)

        for action in generate_actions(loc, arm):
            mb = moved_block(action)
            req = required_next(last_moved)

            if req is not None and mb != req:
                continue

            nloc, narm = apply_action(loc, arm, action)
            nlast = mb
            nloc_t = loc_to_tuple(nloc)
            key = (nloc_t, narm, nlast)

            if key in visited:
                continue

            npath = path + (action,)

            if is_goal(nloc, narm, nlast):
                for act in npath:
                    print("(" + " ".join(act) + ")")
                return

            visited.add(key)
            queue.append((nloc_t, narm, nlast, npath))

    print("No plan")


if __name__ == "__main__":
    main()

import sys


def main():
    blocks = [f"block{i}" for i in range(1, 10)]

    goal_on = {
        "block8": "table",
        "block3": "block8",
        "block6": "block3",
        "block5": "block6",
        "block2": "block5",
        "block1": "block2",
        "block9": "block1",
        "block4": "block9",
        "block7": "block4",
    }

    goal_order = [
        "block8",
        "block3",
        "block6",
        "block5",
        "block2",
        "block1",
        "block9",
        "block4",
        "block7",
    ]

    on = {b: "table" for b in blocks}
    arm = None
    actions = []

    def top_block(b):
        for c in blocks:
            if on[c] == b:
                return c
        return None

    def do_pickup(b):
        nonlocal arm
        actions.append(("pickup", b))
        on[b] = None
        arm = b

    def do_putdown(b):
        nonlocal arm
        actions.append(("putdown", b))
        on[b] = "table"
        arm = None

    def do_stack(b, y):
        nonlocal arm
        actions.append(("stack", b, y))
        on[b] = y
        arm = None

    def do_unstack(b, y):
        nonlocal arm
        actions.append(("unstack", b, y))
        on[b] = None
        arm = b

    def clear_block(b):
        while True:
            top = top_block(b)
            if top is None:
                return
            if arm is not None:
                do_putdown(arm)
            do_unstack(top, b)
            do_putdown(top)

    def ensure_on_table(b):
        if on[b] == "table":
            return

        clear_block(b)

        if arm is not None and arm != b:
            do_putdown(arm)

        if arm == b:
            do_putdown(b)
        elif on[b] != "table":
            if on[b] is None:
                return
            do_unstack(b, on[b])
            do_putdown(b)

    def ensure_on(x, y):
        if x == y:
            return
        if on[x] == y:
            return

        clear_block(x)
        clear_block(y)

        if arm is not None and arm != x:
            do_putdown(arm)

        if arm != x:
            if on[x] == "table":
                do_pickup(x)
            elif on[x] is not None:
                do_unstack(x, on[x])
            else:
                return

        if arm == x:
            do_stack(x, y)

    ensure_on_table(goal_order[0])

    for below, above in zip(goal_order[:-1], goal_order[1:]):
        ensure_on(above, below)

    if arm is not None:
        do_putdown(arm)

    def top_block_in(state, b):
        for c in blocks:
            if state[c] == b:
                return c
        return None

    def validate(plan):
        state = {b: "table" for b in blocks}
        held = None

        for action in plan:
            op = action[0]

            if op == "pickup":
                b = action[1]
                if held is not None:
                    return False
                if state[b] != "table":
                    return False
                if top_block_in(state, b) is not None:
                    return False
                state[b] = None
                held = b

            elif op == "putdown":
                b = action[1]
                if held != b:
                    return False
                if top_block_in(state, b) is not None:
                    return False
                state[b] = "table"
                held = None

            elif op == "stack":
                b, y = action[1], action[2]
                if held != b:
                    return False
                if y not in state:
                    return False
                if state[y] is None:
                    return False
                if top_block_in(state, y) is not None:
                    return False
                state[b] = y
                held = None

            elif op == "unstack":
                b, y = action[1], action[2]
                if held is not None:
                    return False
                if state[b] != y:
                    return False
                if top_block_in(state, b) is not None:
                    return False
                state[b] = None
                held = b

            else:
                return False

        if held is not None:
            return False

        return state == goal_on

    if validate(actions):
        output = []
        for action in actions:
            if len(action) == 2:
                output.append(f"({action[0]} {action[1]})")
            else:
                output.append(f"({action[0]} {action[1]} {action[2]})")
        sys.stdout.write("\n".join(output))
    else:
        sys.stdout.write("No plan")


if __name__ == "__main__":
    main()

from collections import deque

BLOCKS = ("a", "b", "c", "d", "e", "f")


def normalize(on, table, held):
    on = {k: v for k, v in on.items()}
    table = frozenset(table)
    clear = frozenset(set(BLOCKS) - set(on.values()))
    on_tuple = tuple(sorted(on.items()))
    return (on_tuple, table, clear, held)


def is_goal(state):
    on_tuple, table, clear, held = state
    if held is not None:
        return False
    on = dict(on_tuple)
    return (
        on.get("a") == "b"
        and on.get("b") == "c"
        and "c" in table
        and "d" in table
        and on.get("e") == "f"
        and "f" in table
    )


def successors(state):
    on_tuple, table, clear, held = state
    on = dict(on_tuple)

    if held is None:
        for x in BLOCKS:
            if x in table and x in clear:
                new_table = table - {x}
                yield (f"(pickup {x})", normalize(on, new_table, x))

    if held is not None:
        yield (f"(putdown {held})", normalize(on, table | {held}, None))

    if held is None:
        for x in BLOCKS:
            y = on.get(x)
            if y is not None and x in clear:
                new_on = dict(on)
                del new_on[x]
                yield (f"(unstack {x} {y})", normalize(new_on, table, x))

    if held is not None:
        for y in BLOCKS:
            if y != held and y in clear:
                new_on = dict(on)
                new_on[held] = y
                yield (f"(stack {held} {y})", normalize(new_on, table, None))


def main():
    initial_on = {"b": "c", "e": "d"}
    initial_table = frozenset({"a", "c", "d", "f"})
    start = normalize(initial_on, initial_table, None)

    if is_goal(start):
        return

    queue = deque([start])
    parent = {start: (None, None)}

    while queue:
        state = queue.popleft()
        for action, nxt in successors(state):
            if nxt not in parent:
                parent[nxt] = (state, action)
                if is_goal(nxt):
                    plan = []
                    cur = nxt
                    while parent[cur][0] is not None:
                        plan.append(parent[cur][1])
                        cur = parent[cur][0]
                    plan.reverse()
                    print("\n".join(plan))
                    return
                queue.append(nxt)

    print("No plan")


