import sys


def main():
    blocks = list(range(1, 16))

    def name(b):
        return f"block{b}"

    # Initial state:
    # All blocks are on the table except block10, which is on block5.
    loc = {b: "table" for b in blocks}
    loc[10] = 5
    hand = None

    # Goal on-relations.  Support 0 means the table.
    goal_on = [
        (10, 0),
        (6, 10),
        (4, 6),
        (9, 4),
        (1, 9),
        (13, 1),
        (8, 13),
        (11, 8),
        (3, 11),
        (14, 3),
        (7, 14),
        (2, 7),
        (15, 2),
        (12, 15),
        (5, 12),
    ]

    # Additional constraint: the final state must have block5 in the hand.
    final_hand = 5

    def no_plan():
        print("No plan")
        sys.exit(0)

    # Validate the goal specification.
    goal_support = {}
    for top, support in goal_on:
        if top in goal_support:
            no_plan()
        if support == top:
            no_plan()
        goal_support[top] = support

    child = {}
    for top, support in goal_on:
        if support != 0:
            if support in child:
                no_plan()
            child[support] = top

    # A block in the hand cannot also be on another block/table in the goal,
    # and no other block can be on the held block.
    if final_hand is not None:
        if final_hand not in blocks:
            no_plan()
        if final_hand in goal_support:
            no_plan()
        for top, support in goal_on:
            if support == final_hand:
                no_plan()

    # Detect cycles among specified on-relations.
    for start in goal_support:
        seen = set()
        cur = start
        while cur in goal_support:
            if cur in seen:
                no_plan()
            seen.add(cur)
            support = goal_support[cur]
            if support == 0:
                break
            cur = support

    actions = []

    def blocks_on(b):
        return [x for x in loc if loc[x] == b]

    def is_clear(b):
        return not blocks_on(b)

    def do_pickup(b):
        nonlocal hand
        if hand is not None or loc[b] != "table" or not is_clear(b):
            raise RuntimeError("invalid pickup")
        hand = b
        loc[b] = "hand"
        actions.append(f"(pickup {name(b)})")

    def do_putdown(b):
        nonlocal hand
        if hand != b:
            raise RuntimeError("invalid putdown")
        hand = None
        loc[b] = "table"
        actions.append(f"(putdown {name(b)})")

    def do_unstack(b, support):
        nonlocal hand
        if hand is not None or loc[b] != support or not is_clear(b):
            raise RuntimeError("invalid unstack")
        hand = b
        loc[b] = "hand"
        actions.append(f"(unstack {name(b)} {name(support)})")

    def do_stack(b, support):
        nonlocal hand
        if hand != b or support == 0 or loc[support] == "hand" or not is_clear(support):
            raise RuntimeError("invalid stack")
        hand = None
        loc[b] = support
        actions.append(f"(stack {name(b)} {name(support)})")

    def make_clear(b):
        nonlocal hand
        if hand is not None:
            do_putdown(hand)
        if loc[b] == "hand":
            do_putdown(b)

        while True:
            tops = blocks_on(b)
            if not tops:
                break
            top = tops[0]
            make_clear(top)
            do_unstack(top, b)
            do_putdown(top)

    def place_on(b, support):
        nonlocal hand
        if hand is not None:
            do_putdown(hand)

        if loc[b] == support:
            return

        make_clear(b)

        if support == 0:
            if loc[b] == "table":
                return
            current = loc[b]
            do_unstack(b, current)
            do_putdown(b)
        else:
            make_clear(support)
            if loc[b] == "table":
                do_pickup(b)
            else:
                current = loc[b]
                do_unstack(b, current)
            do_stack(b, support)

    # Build each required tower from bottom to top.
    starts = []
    for top, support in goal_on:
        if support == 0 or support not in goal_support:
            starts.append(top)

    for start in starts:
        cur = start
        while True:
            support = goal_support[cur]
            place_on(cur, support)
            if cur in child:
                cur = child[cur]
            else:
                break

    # Enforce the final-hand constraint.
    if final_hand is not None:
        b = final_hand
        if hand != b:
            if hand is not None:
                do_putdown(hand)
            make_clear(b)
            if hand is not None:
                do_putdown(hand)
            if loc[b] == "table":
                do_pickup(b)
            elif isinstance(loc[b], int):
                do_unstack(b, loc[b])
    else:
        if hand is not None:
            do_putdown(hand)

    def goal_met():
        for top, support in goal_on:
            if support == 0:
                if loc[top] != "table":
                    return False
            else:
                if loc[top] != support:
                    return False

        if final_hand is None:
            return hand is None
        return hand == final_hand

    if not goal_met():
        no_plan()

    if actions:
        print("\n".join(actions))


if __name__ == "__main__":
    main()

from collections import deque

blocks = ["a", "b", "c", "d", "e"]
idx = {b: i for i, b in enumerate(blocks)}

initial = ("table", "table", "a", "table", "b")
goal = ("b", "c", "d", "e", "table")


def top_flags(state):
    flags = [False] * len(blocks)
    for support in state:
        if support in idx:
            flags[idx[support]] = True
    return flags


def neighbors(state):
    tops = top_flags(state)
    held = [i for i, s in enumerate(state) if s is None]

    if len(held) == 1:
        h = held[0]

        ns = list(state)
        ns[h] = "table"
        yield ("putdown", blocks[h]), tuple(ns)

        for y in range(len(blocks)):
            if y != h and state[y] is not None and not tops[y]:
                ns = list(state)
                ns[h] = blocks[y]
                yield ("stack", blocks[h], blocks[y]), tuple(ns)
    else:
        for x in range(len(blocks)):
            if state[x] == "table" and not tops[x]:
                ns = list(state)
                ns[x] = None
                yield ("pickup", blocks[x]), tuple(ns)

        for x in range(len(blocks)):
            support = state[x]
            if support in idx and not tops[x]:
                ns = list(state)
                ns[x] = None
                yield ("unstack", blocks[x], support), tuple(ns)


def main():
    if initial == goal:
        return

    parent = {initial: (None, None)}
    queue = deque([initial])

    while queue:
        state = queue.popleft()

        if state == goal:
            actions = []
            cur = goal
            while cur != initial:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev

            actions.reverse()

            for action in actions:
                if len(action) == 2:
                    print(f"({action[0]} {action[1]})")
                else:
                    print(f"({action[0]} {action[1]} {action[2]})")
            return

        for action, nxt in neighbors(state):
            if nxt not in parent:
                parent[nxt] = (state, action)
                queue.append(nxt)

    print("No plan")


