    b = queue.pop(0)
    if b in goal_order:
        continue
    goal_order.append(b)
    for c in sorted(children.get(b, [])):
        if c not in goal_order:
            queue.append(c)
for b in blocks:
    if b not in goal_order:
        goal_order.append(b)


def heuristic(on):
    stable = [False] * 11
    for b in goal_order:
        if on[b] == goal_on[b]:
            if goal_on[b] == 0:
                stable[b] = True
            else:
                stable[b] = stable[goal_on[b]]

    h = 0
    for b in blocks:
        if on[b] == goal_on[b]:
            if goal_on[b] != 0 and not stable[goal_on[b]]:
                h += 2
        else:
            h += 1 if on[b] == ARM else 2
    return h


def neighbors(on):
    clear = [True] * 11
    arm = 0
    for b in blocks:
        s = on[b]
        if s == ARM:
            arm = b
        elif 1 <= s <= 10:
            clear[s] = False

    result = []
    if arm == 0:
        for b in blocks:
            if clear[b]:
                s = on[b]
                if s == 0:
                    nxt = list(on)
                    nxt[b] = ARM
                    result.append((tuple(nxt), f"(pickup block{b})"))
                elif 1 <= s <= 10:
                    nxt = list(on)
                    nxt[b] = ARM
                    result.append((tuple(nxt), f"(unstack block{b} block{s})"))
    else:
        b = arm
        nxt = list(on)
        nxt[b] = 0
        result.append((tuple(nxt), f"(putdown block{b})"))

        for y in blocks:
            if y != b and clear[y]:
                nxt = list(on)
                nxt[b] = y
                result.append((tuple(nxt), f"(stack block{b} block{y})"))

    return result


def astar(limit=100000):
    start = tuple(initial_on)
    if start == goal:
        return []

    g = {start: 0}
    parent = {}
    action = {}
    counter = 0
    heap = [(heuristic(start), 0, 0, start)]
    expansions = 0

    while heap:
        _, neg_g, _, state = heapq.heappop(heap)
        cur_g = -neg_g

        if cur_g != g.get(state):
            continue

        if state == goal:
            plan = []
            cur = state
            while cur != start:
                plan.append(action[cur])
                cur = parent[cur]
            plan.reverse()
            return plan

        expansions += 1
        if expansions > limit:
            return None

        for nstate, label in neighbors(state):
            ng = cur_g + 1
            if ng < g.get(nstate, 10**9):
                g[nstate] = ng
                parent[nstate] = state
                action[nstate] = label
                counter += 1
                heapq.heappush(heap, (ng + heuristic(nstate), -ng, counter, nstate))

    return None


def constructive():
    on = initial_on.copy()
    plan = []

    def arm_block():
        for b in blocks:
            if on[b] == ARM:
                return b
        return 0

    def do_pickup(b):
        on[b] = ARM
        plan.append(f"(pickup block{b})")

    def do_putdown(b):
        on[b] = 0
        plan.append(f"(putdown block{b})")

    def do_unstack(b, y):
        on[b] = ARM
        plan.append(f"(unstack block{b} block{y})")

    def do_stack(b, y):
        on[b] = y
        plan.append(f"(stack block{b} block{y})")

    def ensure_clear(x):
        while True:
            a = arm_block()
            if a:
                do_putdown(a)

            c = 0
            for b in blocks:
                if on[b] == x:
                    c = b
                    break

            if c == 0:
                return

            ensure_clear(c)
            do_unstack(c, x)
            do_putdown(c)

    for base in sorted(children.get(0, [])):
        ensure_clear(base)

        if on[base] != 0:
            if on[base] == ARM:
                do_putdown(base)
            elif 1 <= on[base] <= 10:
                do_unstack(base, on[base])
                do_putdown(base)

        cur = base
        while children.get(cur):
            child = children[cur][0]

            if on[child] == cur:
                cur = child
                continue

            ensure_clear(child)
            ensure_clear(cur)

            if on[child] == 0:
                do_pickup(child)
            elif 1 <= on[child] <= 10:
                do_unstack(child, on[child])
            elif on[child] == ARM:
                do_putdown(child)
                do_pickup(child)

            do_stack(child, cur)
            cur = child

        ensure_clear(cur)

    if on == goal_on and all(on[b] != ARM for b in blocks):
        return plan
    return None


plan = astar()
if plan is None:
    plan = constructive()

if plan is None:
    print("No plan")
else:
    for line in plan:
        print(line)

def main():
    blocks = list(range(1, 16))

    def name(b):
        return f"block{b}"

    support = {b: 0 for b in blocks}
    support[15] = 10
    support[7] = 9
    support[3] = 4
    arm = 0
    actions = []

    def is_clear(b):
        for c in blocks:
            if c != b and support[c] == b:
                return False
        return True

    def do_pickup(b):
        nonlocal arm
        if arm != 0 or support[b] != 0 or not is_clear(b):
            return False
        arm = b
        support[b] = -1
        actions.append(f"(pickup {name(b)})")
        return True

    def do_putdown(b):
        nonlocal arm
        if arm != b:
            return False
        support[b] = 0
        arm = 0
        actions.append(f"(putdown {name(b)})")
        return True

    def do_unstack(b, s):
        nonlocal arm
        if arm != 0 or support[b] != s or s == 0 or s == -1 or not is_clear(b):
            return False
        arm = b
        support[b] = -1
        actions.append(f"(unstack {name(b)} {name(s)})")
        return True

    def do_stack(b, s):
        nonlocal arm
        if arm != b or support[b] != -1 or s == b or support[s] == -1 or not is_clear(s):
            return False
        support[b] = s
        arm = 0
        actions.append(f"(stack {name(b)} {name(s)})")
        return True

    while True:
        candidate = None
        for b in blocks:
            if support[b] != 0 and support[b] != -1 and is_clear(b):
                candidate = b
                break
        if candidate is None:
            if any(support[b] not in (0, -1) for b in blocks):
                print("No plan")
                return
            break
        if not do_unstack(candidate, support[candidate]):
            print("No plan")
            return
        if not do_putdown(candidate):
            print("No plan")
            return

    goal_stacks = [
        [15, 8, 13, 14, 1],
        [5],
        [10],
        [7],
        [9],
        [11, 2],
        [4, 6, 12, 3],
    ]

    seen = []
    for stack in goal_stacks:
        seen.extend(stack)
    if sorted(seen) != blocks:
        print("No plan")
        return

    for stack in goal_stacks:
        current = stack[0]
        if support[current] != 0 or not is_clear(current):
            print("No plan")
            return
        for top in stack[1:]:
            if support[top] != 0 or not is_clear(top):
                print("No plan")
                return
            if not do_pickup(top):
                print("No plan")
                return
            if not do_stack(top, current):
                print("No plan")
                return
            current = top

    expected = {b: 0 for b in blocks}
    for stack in goal_stacks:
        for lower, upper in zip(stack, stack[1:]):
            expected[upper] = lower

    if arm != 0 or any(support[b] != expected[b] for b in blocks):
        print("No plan")
        return

    print("\n".join(actions))

if __name__ == "__main__":
    main()

from collections import deque

BLOCKS = ('red', 'blue', 'green', 'yellow')
TABLE = 'table'


def to_tuple(d):
    return tuple(d[b] for b in BLOCKS)


initial = {b: None for b in BLOCKS}
initial['red'] = TABLE
initial['blue'] = 'red'
initial['green'] = TABLE
initial['yellow'] = 'green'

goal = {b: None for b in BLOCKS}
goal['red'] = TABLE
goal['green'] = 'red'
goal['yellow'] = 'green'
goal['blue'] = 'yellow'

INITIAL_STATE = (to_tuple(initial), None, False)
GOAL_STATE = (to_tuple(goal), None, True)
FIRST_HOLDING = 'blue'


def clear_blocks(support_tuple):
    covered = set()
    for b, s in zip(BLOCKS, support_tuple):
        if s is not None and s != TABLE:
            covered.add(s)

    clear = set()
    for b, s in zip(BLOCKS, support_tuple):
        if s is not None and b not in covered:
            clear.add(b)

    return clear


def successors(state):
    support_tuple, holding, first_done = state
    support = list(support_tuple)
    clear = clear_blocks(support_tuple)
    out = []

    def add(action, new_support, new_holding):
        # Encode the extra constraint: the first action must leave blue held.
        if not first_done and new_holding != FIRST_HOLDING:
            return
        out.append((action, (tuple(new_support), new_holding, True)))

    if holding is None:
        for b in BLOCKS:
            if support[b] == TABLE and b in clear:
                ns = support.copy()
                ns[b] = None
                add(('pickup', b), ns, b)

        for b in BLOCKS:
            for other in BLOCKS:
                if support[b] == other and b in clear:
                    ns = support.copy()
                    ns[b] = None
                    add(('unstack', b, other), ns, b)
    else:
        b = holding

        ns = support.copy()
        ns[b] = TABLE
        add(('putdown', b), ns, None)

        for other in BLOCKS:
            if other == b:
                continue
            if support[other] is not None and other in clear:
                ns = support.copy()
                ns[b] = other
                add(('stack', b, other), ns, None)

    return out


def solve():
    parent = {INITIAL_STATE: None}
    queue = deque([INITIAL_STATE])

    while queue:
        state = queue.popleft()

        for action, nxt in successors(state):
            if nxt in parent:
                continue

            parent[nxt] = (state, action)

            if nxt == GOAL_STATE:
                plan = []
                cur = nxt
                while parent[cur] is not None:
                    prev, act = parent[cur]
                    plan.append(act)
                    cur = prev
                plan.reverse()
                return plan

            queue.append(nxt)

    return None


def main():
    plan = solve()
    if plan is None:
        print('No plan')
    else:
        for action in plan:
            print('(' + ' '.join(action) + ')')


if __name__ == '__main__':
    main()

def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


BLOCKS = [f"block{i}" for i in range(1, 16)]
NUM = {b: int(b[5:]) for b in BLOCKS}

INITIAL_SUPPORT = {
    "block1": "table",
    "block2": "table",
    "block3": "block11",
    "block4": "block9",
    "block5": "block15",
    "block6": "block5",
    "block7": "table",
    "block8": "table",
    "block9": "table",
    "block10": "table",
    "block11": "table",
    "block12": "table",
    "block13": "block7",
    "block14": "block6",
    "block15": "table",
}

GOAL_SUPPORT = {
    "block8": "table",
    "block12": "block8",
    "block13": "block12",
    "block4": "block13",
    "block2": "block4",
    "block7": "block2",
    "block15": "block7",
    "block14": "block15",
    "block3": "table",
    "block6": "block3",
    "block11": "block6",
    "block10": "block11",
    "block5": "block10",
    "block9": "block5",
    "block1": "table",
}


def stacks_from_support(support):
    if set(support.keys()) != set(BLOCKS):
        return None

    top = {b: None for b in BLOCKS}
    for b, s in support.items():
        if s == "table":
            continue
        if s not in BLOCKS:
            return None
        if top[s] is not None:
            return None
        top[s] = b

    stacks = []
    for b in BLOCKS:
        if support[b] == "table":
            stack = [b]
            cur = top.get(b)
            while cur is not None:
                if support[cur] != b:
                    return None
                stack.append(cur)
                cur = top.get(cur)
            stacks.append(stack)

    seen = [b for st in stacks for b in st]
    if len(seen) != len(BLOCKS) or len(set(seen)) != len(BLOCKS):
        return None

    return stacks


def satisfies_additional(stacks):
    if not stacks:
        return False
    if len(stacks) != 2:
        return False

    def all_prime(st):
        return all(is_prime(NUM[b]) for b in st)

    def all_nonprime(st):
        return all(not is_prime(NUM[b]) for b in st)

    if not (
        (all_prime(stacks[0]) and all_nonprime(stacks[1]))
        or (all_prime(stacks[1]) and all_nonprime(stacks[0]))
    ):
        return False

    for st in stacks:
        nums = [NUM[b] for b in st]
        if nums != sorted(nums):
            return False

    return True


def make_state(support):
    top = {b: None for b in BLOCKS}
    for b, s in support.items():
        if s != "table":
            if s not in top or top[s] is not None:
                return None
            top[s] = b
    return {"support": dict(support), "top": top, "holding": None}


def apply_action(state, action):
    ns = {
        "support": dict(state["support"]),
        "top": dict(state["top"]),
        "holding": state["holding"],
    }
    kind = action[0]

    if kind == "pickup":
        if len(action) != 2:
            return None
        b = action[1]
        if (
            b not in ns["support"]
            or ns["holding"] is not None
            or ns["support"][b] != "table"
            or ns["top"][b] is not None
        ):
            return None
        ns["support"][b] = "arm"
        ns["holding"] = b

    elif kind == "unstack":
        if len(action) != 3:
            return None
        x, y = action[1], action[2]
        if (
            x not in ns["support"]
            or y not in ns["support"]
            or y == "table"
            or ns["holding"] is not None
            or ns["support"][x] != y
            or ns["support"][y] == "arm"
            or ns["top"][x] is not None
        ):
            return None
        ns["support"][x] = "arm"
        ns["holding"] = x

    elif kind == "putdown":
        if len(action) != 2:
            return None
        b = action[1]
        if b not in ns["support"] or ns["holding"] != b:
            return None
        ns["support"][b] = "table"
        ns["holding"] = None

    elif kind == "stack":
        if len(action) != 3:
            return None
        x, y = action[1], action[2]
        if (
            x not in ns["support"]
            or y not in ns["support"]
            or y == "table"
            or ns["holding"] != x
            or x == y
            or ns["support"][y] == "arm"
            or ns["top"][x] is not None
            or ns["top"][y] is not None
        ):
            return None
        ns["support"][x] = y
        ns["holding"] = None

    else:
        return None

    new_top = {b: None for b in BLOCKS}
    for b, s in ns["support"].items():
        if s != "table" and s != "arm":
            if s not in new_top:
                return None
            if new_top[s] is not None:
                return None
            new_top[s] = b

    ns["top"] = new_top
    return ns


def action_to_string(action):
    return "(" + " ".join(action) + ")"


def generate_plan(initial_support, goal_stacks):
    state = make_state(initial_support)
    if state is None:
        return None

    plan = []

    while True:
        candidate = None
        for b in BLOCKS:
            if state["support"][b] not in ("table", "arm") and state["top"][b] is None:
                candidate = b
                break

        if candidate is None:
            break

        s = state["support"][candidate]

        a = ("unstack", candidate, s)
        state = apply_action(state, a)
        if state is None:
            return None
        plan.append(action_to_string(a))

        a = ("putdown", candidate)
        state = apply_action(state, a)
        if state is None:
            return None
        plan.append(action_to_string(a))

    for st in goal_stacks:
        prev = None
        for b in st:
            a = ("pickup", b)
            state = apply_action(state, a)
            if state is None:
                return None
            plan.append(action_to_string(a))

            if prev is None:
                a = ("putdown", b)
            else:
                a = ("stack", b, prev)

            state = apply_action(state, a)
            if state is None:
                return None
            plan.append(action_to_string(a))

            prev = b

    expected = {}
    for st in goal_stacks:
        if not st:
            continue
        expected[st[0]] = "table"
        for i in range(1, len(st)):
            expected[st[i]] = st[i - 1]

    if state["holding"] is not None or state["support"] != expected:
        return None

    return plan


def main():
    goal_stacks = stacks_from_support(GOAL_SUPPORT)

    if not satisfies_additional(goal_stacks):
        print("No plan")
        return

    plan = generate_plan(INITIAL_SUPPORT, goal_stacks)

    if plan is None:
        print("No plan")
    else:
        for line in plan:
            print(line)


if __name__ == "__main__":
    main()

N = 12
TABLE = -1
HELD = -2
BLOCKS = [chr(ord('a') + i) for i in range(N)]


def initial_state():
    below = [TABLE] * N
    below[1] = 0
    below[2] = HELD
    below[4] = 3
    below[5] = 4
    below[9] = 8
    below[10] = 9
    below[11] = 10
    return tuple(below)


def goal_state():
    below = [TABLE] * N
    for i in range(1, N):
        below[i] = i - 1
    return tuple(below)


def held_block(below):
    for i, support in enumerate(below):
        if support == HELD:
            return i
    return None


def block_above(b, below):
    for i, support in enumerate(below):
        if support == b:
            return i
    return None


def top_above(b, below):
    cur = b
    while True:
        nxt = block_above(cur, below)
        if nxt is None:
            return cur
        cur = nxt


def is_clear(b, below):
    return block_above(b, below) is None


def ensure_hand_empty(below, plan):
    h = held_block(below)
    if h is not None:
        plan.append(('putdown', h))
        below[h] = TABLE


def move_to_table(x, below, plan):
    ensure_hand_empty(below, plan)
    clear_block(x, below, plan)

    if below[x] == TABLE:
        return

    if below[x] == HELD:
        plan.append(('putdown', x))
        below[x] = TABLE
    else:
        y = below[x]
        plan.append(('unstack', x, y))
        below[x] = HELD
        plan.append(('putdown', x))
        below[x] = TABLE


def clear_block(b, below, plan):
    ensure_hand_empty(below, plan)
    while block_above(b, below) is not None:
        top = top_above(b, below)
        move_to_table(top, below, plan)


def move_to_block(x, y, below, plan):
    ensure_hand_empty(below, plan)
    clear_block(x, below, plan)

    if below[x] == y:
        return

    clear_block(y, below, plan)

    if below[x] == y:
        return

    if below[x] == TABLE:
        plan.append(('pickup', x))
        below[x] = HELD
    elif below[x] == HELD:
        pass
    else:
        z = below[x]
        plan.append(('unstack', x, z))
        below[x] = HELD

    plan.append(('stack', x, y))
    below[x] = y


def generate_plan():
    below = list(initial_state())
    plan = []
    current = None

    for b in range(N):
        if current is None:
            move_to_table(b, below, plan)
            current = b
        else:
            move_to_block(b, current, below, plan)
            current = b

    ensure_hand_empty(below, plan)
    return plan


def simulate(initial, plan):
    below = list(initial)

    for action in plan:
        name = action[0]

        if name == 'pickup':
            x = action[1]
            if held_block(below) is not None:
                return None
            if below[x] != TABLE:
                return None
            if not is_clear(x, below):
                return None
            below[x] = HELD

        elif name == 'putdown':
            x = action[1]
            if below[x] != HELD:
                return None
            below[x] = TABLE

        elif name == 'unstack':
            x, y = action[1], action[2]
            if held_block(below) is not None:
                return None
            if below[x] != y:
                return None
            if not is_clear(x, below):
                return None
            below[x] = HELD

        elif name == 'stack':
            x, y = action[1], action[2]
            if below[x] != HELD:
                return None
            if not is_clear(y, below):
                return None
            below[x] = y

        else:
            return None

    return tuple(below)


def main():
    plan = generate_plan()
    final = simulate(initial_state(), plan)

    if final is None or final != goal_state():
        print("No plan")
        return

    for action in plan:
        if action[0] in ('pickup', 'putdown'):
            print(f"({action[0]} {BLOCKS[action[1]]})")
        else:
            print(f"({action[0]} {BLOCKS[action[1]]} {BLOCKS[action[2]]})")


if __name__ == "__main__":
    main()

import sys
from collections import deque

N = 13
TABLE = -1
HELD = -2
REQUIRED_STACKS = 5

NAMES = [f"block{i}" for i in range(1, N + 1)]


def idx(n):
    return n - 1


initial = [TABLE] * N
for top, bottom in [(11, 7), (2, 11), (5, 13), (8, 4), (1, 6)]:
    initial[idx(top)] = idx(bottom)

goal = [TABLE] * N
for top, bottom in [
    (13, 6),
    (8, 2),
    (7, 8),
    (1, 7),
    (9, 5),
    (3, 12),
    (11, 3),
    (4, 11),
]:
    goal[idx(top)] = idx(bottom)

GOAL = tuple(goal)


def clear(locs, b):
    return all(x != b for x in locs)


def stack_count(locs):
    return sum(1 for x in locs if x == TABLE)


def valid_state(locs, moved):
    if not moved:
        return True
    return stack_count(locs) == REQUIRED_STACKS


def is_goal(locs, held):
    return held is None and locs == GOAL


def successors(state):
    locs, held, moved = state
    moved_after = True

    if held is None:
        for b in range(N):
            if locs[b] == TABLE and clear(locs, b):
                new_locs = list(locs)
                new_locs[b] = HELD
                yield ("pickup", b), (tuple(new_locs), b, moved_after)

            c = locs[b]
            if 0 <= c < N and clear(locs, b):
                new_locs = list(locs)
                new_locs[b] = HELD
                yield ("unstack", b, c), (tuple(new_locs), b, moved_after)
    else:
        b = held

        new_locs = list(locs)
        new_locs[b] = TABLE
        yield ("putdown", b), (tuple(new_locs), None, moved_after)

        for c in range(N):
            if c == b or locs[c] == HELD:
                continue
            if clear(locs, c):
                new_locs = list(locs)
                new_locs[b] = c
                yield ("stack", b, c), (tuple(new_locs), None, moved_after)


def action_string(action):
    if action[0] in ("pickup", "putdown"):
        return f"({action[0]} {NAMES[action[1]]})"
    return f"({action[0]} {NAMES[action[1]]} {NAMES[action[2]]})"


def main():
    start = (tuple(initial), None, False)

    if not valid_state(start[0], False):
        print("No plan")
        return

    if is_goal(start[0], None):
        return

    queue = deque([start])
    parent = {start: (None, None)}
    visited = {start}

    while queue:
        state = queue.popleft()
        locs, held, moved = state

        if is_goal(locs, held):
            actions = []
            current = state
            while parent[current][0] is not None:
                previous, action = parent[current]
                actions.append(action)
                current = previous
            actions.reverse()
            sys.stdout.write("\n".join(action_string(a) for a in actions))
            return

        for action, next_state in successors(state):
            if not valid_state(next_state[0], next_state[2]):
                continue
            if next_state in visited:
                continue
            visited.add(next_state)
            parent[next_state] = (state, action)
            queue.append(next_state)

    print("No plan")


if __name__ == "__main__":
    main()

import heapq

def main():
    blocks = tuple(range(1, 12))

    goal_support = ['T'] * 12
    goal_support[2] = 'T'
    goal_support[5] = 2
    goal_support[8] = 'T'
    goal_support[11] = 'T'
    goal_support[9] = 11
    goal_support[4] = 'T'
    goal_support[1] = 'T'
    goal_support[10] = 1
    goal_support[3] = 'T'
    goal_support[6] = 'T'
    goal_support[7] = 6
    goal_support = tuple(goal_support)

    initial_support = tuple(['T'] * 12)
    start = (None, initial_support)
    goal = (None, goal_support)

    protected = frozenset(b for b in blocks if initial_support[b] == 'T' and goal_support[b] == 'T')

    def is_clear(state, b):
        _, sup = state
        for i in blocks:
            if i != b and sup[i] == b:
                return False
        return True

    def neighbors(state):
        held, sup = state
        out = []

        if held is None:
            for x in blocks:
                if x in protected:
                    continue
                if sup[x] == 'T' and is_clear(state, x):
                    ns = list(sup)
                    ns[x] = 0
                    out.append(((x, tuple(ns)), f"(pickup block{x})"))

            for x in blocks:
                if x in protected:
                    continue
                y = sup[x]
                if y != 'T' and y != 0 and sup[y] != 0 and is_clear(state, x):
                    ns = list(sup)
                    ns[x] = 0
                    out.append(((x, tuple(ns)), f"(unstack block{x} block{y})"))

        if held is not None:
            x = held
            if is_clear(state, x):
                ns = list(sup)
                ns[x] = 'T'
                out.append(((None, tuple(ns)), f"(putdown block{x})"))

                for y in blocks:
                    if y == x or sup[y] == 0:
                        continue
                    if is_clear(state, y):
                        ns = list(sup)
                        ns[x] = y
                        out.append(((None, tuple(ns)), f"(stack block{x} block{y})"))

        return out

    def heuristic(state):
        _, sup = state
        return sum(1 for b in blocks if sup[b] != goal_support[b])

    if start == goal:
        return []

    parent = {start: (None, None)}
    g_score = {start: 0}
    counter = 0
    heap = [(heuristic(start), counter, 0, start)]
    closed = set()

    while heap:
        _, _, g, state = heapq.heappop(heap)

        if state in closed:
            continue

        if g != g_score.get(state):
            continue

        if state == goal:
            actions = []
            cur = state
            while cur != start:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev
            return actions[::-1]

        closed.add(state)

        for nstate, action in neighbors(state):
            ng = g + 1
            if ng < g_score.get(nstate, float('inf')):
                g_score[nstate] = ng
                parent[nstate] = (state, action)
                heapq.heappush(heap, (ng + heuristic(nstate), counter, ng, nstate))
                counter += 1

    return None

plan = main()
if plan is None:
    print("No plan")
else:
    for line in plan:
        print(line)

import sys
from collections import deque

# State: (table_order, on_pairs, holding)
# table_order: tuple of blocks currently on the table, in the specified order
# on_pairs: tuple of (block, below) for each block that is on another block
# holding: block currently held by the arm, or None

BLOCKS = ("block1", "block2", "block3", "block4")
INITIAL_TABLE = ("block3", "block4", "block1", "block2")
GOAL_TABLE = ("block4", "block2", "block1", "block3")


def normalize_on(pairs):
    return tuple(sorted(pairs))


def is_clear(on, block):
    return all(below != block for _, below in on)


def below_of(on, block):
    for b, below in on:
        if b == block:
            return below
    return None


def remove_block_on(on, block):
    return tuple((b, below) for b, below in on if b != block)


def add_block_on(on, block, below):
    return normalize_on(list(on) + [(block, below)])


def is_in_world(table, on, block):
    return block in table or any(b == block for b, _ in on)


def apply_action(state, action):
    table, on, holding = state
    kind = action[0]

    if kind == "pickup":
        x = action[1]
        if holding is not None:
            return None
        if x not in table:
            return None
        if not is_clear(on, x):
            return None
        new_table = tuple(b for b in table if b != x)
        return (new_table, on, x)

    if kind == "unstack":
        x, y = action[1], action[2]
        if holding is not None:
            return None
        if below_of(on, x) != y:
            return None
        if not is_clear(on, x):
            return None
        return (table, remove_block_on(on, x), x)

    if kind == "putdown":
        x = action[1]
        if holding != x:
            return None
        # Putdown is modeled as placing the block at the end of the table order.
        new_table = table + (x,)
        return (new_table, on, None)

    if kind == "stack":
        x, y = action[1], action[2]
        if holding != x:
            return None
        if x == y:
            return None
        if not is_in_world(table, on, y):
            return None
        if not is_clear(on, y):
            return None
        return (table, add_block_on(on, x, y), None)

    return None


def possible_actions(state):
    table, on, holding = state
    actions = []

    if holding is None:
        for b in BLOCKS:
            if b in table and is_clear(on, b):
                actions.append(("pickup", b))

        for x, y in on:
            if is_clear(on, x):
                actions.append(("unstack", x, y))
    else:
        actions.append(("putdown", holding))

        for y in BLOCKS:
            if y != holding and is_in_world(table, on, y) and is_clear(on, y):
                actions.append(("stack", holding, y))

    return actions


def is_goal(state):
    table, on, holding = state
    return holding is None and on == () and table == GOAL_TABLE


def format_action(action):
    return f"({action[0]} {' '.join(action[1:])})"


def main():
    start = (INITIAL_TABLE, (), None)

    if is_goal(start):
        return

    parent = {start: (None, None)}
    queue = deque([start])

    while queue:
        state = queue.popleft()

        for action in possible_actions(state):
            nxt = apply_action(state, action)
            if nxt is None or nxt in parent:
                continue

            parent[nxt] = (state, action)

            if is_goal(nxt):
                plan = []
                cur = nxt
                while parent[cur][0] is not None:
                    prev, act = parent[cur]
                    plan.append(act)
                    cur = prev

                plan.reverse()
                sys.stdout.write("\n".join(format_action(a) for a in plan))
                sys.stdout.write("\n")
                return

            queue.append(nxt)

    sys.stdout.write("No plan\n")


if __name__ == "__main__":
    main()

def main():
    blocks = [f"block{i}" for i in range(1, 16)]

    initial_stacks = [
        ["block6", "block11", "block4", "block12", "block7", "block5", "block14"],
        ["block3", "block1", "block13"],
        ["block2", "block9"],
        ["block8", "block15", "block10"],
    ]

    goal_on = [("block2", "block5")]

    support = {b: "table" for b in blocks}
    for stack in initial_stacks:
        for lower, upper in zip(stack, stack[1:]):
            support[upper] = lower
    held = None

    def is_clear(b):
        return all(support[x] != b for x in blocks)

    def can_pickup(b):
        return held is None and support[b] == "table" and is_clear(b)

    def can_putdown(b):
        return held == b

    def can_unstack(b, under):
        return held is None and support[b] == under and is_clear(b)

    def can_stack(b, under):
        return held == b and support[under] != "held" and is_clear(under)

    def apply(action):
        nonlocal held
        if action[0] == "pickup":
            b = action[1]
            if not can_pickup(b):
                return False
            support[b] = "held"
            held = b
        elif action[0] == "putdown":
            b = action[1]
            if not can_putdown(b):
                return False
            support[b] = "table"
            held = None
        elif action[0] == "unstack":
            b, under = action[1], action[2]
            if not can_unstack(b, under):
                return False
            support[b] = "held"
            held = b
        elif action[0] == "stack":
            b, under = action[1], action[2]
            if not can_stack(b, under):
                return False
            support[b] = under
            held = None
        else:
            return False
        return True

    plan = []

    def execute(action):
        if not apply(action):
            return False
        plan.append(action)
        return True

    while True:
        moved = False
        for b in blocks:
            if support[b] != "table" and support[b] != "held" and is_clear(b):
                if not execute(("unstack", b, support[b])):
                    print("No plan")
                    return
                if not execute(("putdown", b)):
                    print("No plan")
                    return
                moved = True
                break
        if not moved:
            break

    if held is not None or any(support[b] != "table" for b in blocks):
        print("No plan")
        return

    goal_support = {b: "table" for b in blocks}
    for x, y in goal_on:
        goal_support[x] = y

    for x, y in goal_on:
        if x == y or x not in support or y not in support:
            print("No plan")
            return

    children = {b: [] for b in blocks}
    for x, y in goal_on:
        children[y].append(x)
    if any(len(v) > 1 for v in children.values()):
        print("No plan")
        return

    def depth(b):
        seen = set()
        cur = b
        d = 0
        while goal_support[cur] != "table":
            if cur in seen:
                return None
            seen.add(cur)
            cur = goal_support[cur]
            d += 1
        return d

    ordered_goal = []
    for x, y in goal_on:
        d = depth(x)
        if d is None:
            print("No plan")
            return
        ordered_goal.append((d, x, y))
    ordered_goal.sort()

    for _, x, y in ordered_goal:
        if support[x] == y:
            continue
        if not is_clear(x):
            print("No plan")
            return
        if support[y] == "held" or not is_clear(y):
            print("No plan")
            return
        if support[x] == "table":
            if not execute(("pickup", x)):
                print("No plan")
                return
        elif support[x] != "held":
            if not execute(("unstack", x, support[x])):
                print("No plan")
                return
        if not execute(("stack", x, y)):
            print("No plan")
            return

    if held is not None or any(support[b] != goal_support[b] for b in blocks):
        print("No plan")
        return

    for action in plan:
        print("(" + " ".join(action) + ")")


