def main():
    blocks = ("block1", "block2", "block3", "block4")
    idx = {b: i for i, b in enumerate(blocks)}
    weight = {b: int(b[5:]) for b in blocks}

    # Initial and goal table orders as stated in the problem.
    initial_table = ("block3", "block4", "block1", "block2")
    goal_table = ("block4", "block2", "block1", "block3")

    # support tuple: None means the block is not on another block.
    initial_support = (None, None, None, None)
    start_state = (None, initial_table, initial_support)

    def is_clear(state, block):
        support = state[2]
        for other in blocks:
            if other != block and support[idx[other]] == block:
                return False
        return True

    queue = deque([start_state])
    parent = {start_state: None}

    while queue:
        state = queue.popleft()
        arm, table, support = state

        if arm is None and table == goal_table and all(s is None for s in support):
            actions = []
            current = state
            while parent[current] is not None:
                previous, action = parent[current]
                actions.append(action)
                current = previous
            actions.reverse()
            print("\n".join(actions))
            return

        if arm is None:
            # pickup block from the table
            for block in table:
                if is_clear(state, block):
                    new_table = tuple(t for t in table if t != block)
                    new_state = (block, new_table, support)
                    if new_state not in parent:
                        parent[new_state] = (state, f"(pickup {block})")
                        queue.append(new_state)

            # unstack block from another block
            for block in blocks:
                on_block = support[idx[block]]
                if on_block is not None and is_clear(state, block):
                    new_support = list(support)
                    new_support[idx[block]] = None
                    new_state = (block, table, tuple(new_support))
                    if new_state not in parent:
                        parent[new_state] = (state, f"(unstack {block} {on_block})")
                        queue.append(new_state)
        else:
            held = arm

            # putdown: modeled as appending to the ordered table
            new_table = table + (held,)
            new_support = list(support)
            new_support[idx[held]] = None
            new_state = (None, new_table, tuple(new_support))
            if new_state not in parent:
                parent[new_state] = (state, f"(putdown {held})")
                queue.append(new_state)

            # stack held block on another clear block
            for target in blocks:
                if target == held:
                    continue
                if is_clear(state, target) and weight[held] <= weight[target]:
                    new_support = list(support)
                    new_support[idx[held]] = target
                    new_state = (None, table, tuple(new_support))
                    if new_state not in parent:
                        parent[new_state] = (state, f"(stack {held} {target})")
                        queue.append(new_state)

    print("No plan")

