    main()

from collections import deque

TABLE = -1
HELD = -2
FRAGILE = 1
BLOCK_COUNT = 7


def block_name(index):
    return f"block{index + 1}"


def is_goal(state):
    loc, held = state
    return held == -1 and all(s == TABLE for s in loc)


def is_clear(loc, block):
    return all(s != block for s in loc)


def valid_state(state):
    loc, held = state

    if held == -1:
        if any(s == HELD for s in loc):
            return False
    else:
        if not (0 <= held < BLOCK_COUNT):
            return False
        if loc[held] != HELD:
            return False
        if sum(1 for s in loc if s == HELD) != 1:
            return False

    for i, support in enumerate(loc):
        if support == TABLE or support == HELD:
            continue
        if not (0 <= support < BLOCK_COUNT) or support == i:
            return False
        if support == held:
            return False

    if any(support == FRAGILE for support in loc):
        return False

    return True


def generate_actions(state):
    loc, held = state

    for block in range(BLOCK_COUNT):
        if held == -1:
            if loc[block] != HELD and is_clear(loc, block):
                if loc[block] == TABLE:
                    new_loc = list(loc)
                    new_loc[block] = HELD
                    yield ("pickup", block, None), (tuple(new_loc), block)
                else:
                    support = loc[block]
                    new_loc = list(loc)
                    new_loc[block] = HELD
                    yield ("unstack", block, support), (tuple(new_loc), block)
        else:
            if block == held:
                new_loc = list(loc)
                new_loc[block] = TABLE
                yield ("putdown", block, None), (tuple(new_loc), -1)

                for target in range(BLOCK_COUNT):
                    if target == block:
                        continue
                    if loc[target] == HELD:
                        continue
                    if target == FRAGILE:
                        continue
                    if is_clear(loc, target):
                        new_loc = list(loc)
                        new_loc[block] = target
                        yield ("stack", block, target), (tuple(new_loc), -1)


def format_action(action):
    name = action[0]
    if name in ("pickup", "putdown"):
        return f"({name} {block_name(action[1])})"
    return f"({name} {block_name(action[1])} {block_name(action[2])})"


def solve():
    initial_loc = (TABLE, TABLE, 4, 1, TABLE, TABLE, TABLE)
    start = (initial_loc, -1)

    if is_goal(start):
        return

    queue = deque([(start, [])])
    visited = {start}

    while queue:
        state, path = queue.popleft()

        if is_goal(state):
            for action in path:
                print(format_action(action))
            return

        for action, next_state in generate_actions(state):
            if next_state in visited:
                continue
            if not valid_state(next_state):
                continue
            visited.add(next_state)
            queue.append((next_state, path + [action]))

    print("No plan")


if __name__ == "__main__":
    solve()

def main():
    blocks = [f"block{i}" for i in range(1, 16)]
    goal = {b: None for b in blocks}
    for top, bottom in [
        ("block8", "block15"),
        ("block2", "block8"),
        ("block3", "block6"),
        ("block9", "block3"),
        ("block7", "block11"),
        ("block13", "block7"),
        ("block1", "block13"),
        ("block5", "block1"),
        ("block14", "block5"),
        ("block12", "block10"),
        ("block4", "block12"),
    ]:
        goal[top] = bottom

    children = {b: [] for b in blocks}
    for b, s in goal.items():
        if s is not None:
            children[s].append(b)

    for b in blocks:
        if len(children[b]) > 1:
            print("No plan")
            return

    stacks = []
    seen = set()
    for b in blocks:
        if goal[b] is None and b not in seen:
            stack = []
            cur = b
            while cur is not None and cur not in seen:
                seen.add(cur)
                stack.append(cur)
                if children[cur]:
                    cur = children[cur][0]
                else:
                    cur = None
            if cur is not None:
                print("No plan")
                return
            stacks.append(stack)

    if len(seen) != len(blocks):
        print("No plan")
        return

    def stack_index(block):
        for i, stack in enumerate(stacks):
            if block in stack:
                return i
        return None

    s1 = stack_index("block1")
    s2 = stack_index("block2")

    order = []
    if s1 is not None:
        order.append(s1)
    for i in range(len(stacks)):
        if i != s1 and i != s2:
            order.append(i)
    if s2 is not None and s2 != s1:
        order.append(s2)
    if s1 == s2:
        order = list(range(len(stacks)))
    missing = [i for i in range(len(stacks)) if i not in order]
    order.extend(missing)

    actions = []
    for idx in order:
        stack = stacks[idx]
        for lower, upper in zip(stack, stack[1:]):
            actions.append(("pickup", upper))
            actions.append(("stack", upper, lower))

    on = {b: None for b in blocks}
    held = None
    pending = False

    def is_clear(b):
        return all(on[c] != b for c in blocks)

    def moved_of(action):
        return action[1]

    for action in actions:
        if action[0] == "pickup":
            b = action[1]
            if held is not None or on[b] is not None or not is_clear(b):
                print("No plan")
                return
            held = b
        elif action[0] == "putdown":
            b = action[1]
            if held != b:
                print("No plan")
                return
            held = None
            on[b] = None
        elif action[0] == "unstack":
            x, y = action[1], action[2]
            if held is not None or on[x] != y or not is_clear(x):
                print("No plan")
                return
            held = x
            on[x] = None
        elif action[0] == "stack":
            x, y = action[1], action[2]
            if held != x or x == y or not is_clear(y):
                print("No plan")
                return
            held = None
            on[x] = y
        else:
            print("No plan")
            return

        m = moved_of(action)
        if m == "block1":
            pending = True
        elif m == "block2":
            pending = False

    if held is not None or pending:
        print("No plan")
        return
    for b in blocks:
        if on[b] != goal[b]:
            print("No plan")
            return

    print("\n".join(f"({a[0]} {' '.join(a[1:])})" for a in actions))

