import sys
import heapq
import itertools


def main():
    names = [f"block{i}" for i in range(1, 16)]
    idx = {name: i for i, name in enumerate(names)}
    n = len(names)
    TABLE = -1

    below = [TABLE] * n
    below[idx["block15"]] = idx["block10"]
    below[idx["block7"]] = idx["block9"]
    below[idx["block3"]] = idx["block4"]
    start = tuple(below)

    goal = [TABLE] * n
    goal[idx["block15"]] = TABLE
    goal[idx["block8"]] = idx["block15"]
    goal[idx["block13"]] = idx["block8"]
    goal[idx["block14"]] = idx["block13"]
    goal[idx["block1"]] = idx["block14"]

    for b in ("block5", "block10", "block7", "block9", "block11"):
        goal[idx[b]] = TABLE
    goal[idx["block2"]] = idx["block11"]

    goal[idx["block4"]] = TABLE
    goal[idx["block6"]] = idx["block4"]
    goal[idx["block12"]] = idx["block6"]
    goal[idx["block3"]] = idx["block12"]
    goal_state = tuple(goal)

    def is_clear(state, b):
        for x in range(n):
            if state[x] == b:
                return False
        return True

    def is_ready(state, d):
        cur = d
        while cur != TABLE:
            if state[cur] != goal_state[cur]:
                return False
            cur = goal_state[cur]
        return True

    def heuristic(state):
        return sum(1 for i in range(n) if state[i] != goal_state[i])

    first = idx["block1"]
    if start[first] != TABLE or not is_clear(start, first):
        print("No plan")
        return

    h0 = heuristic(start)
    counter = itertools.count()
    open_heap = [(h0, 0, next(counter), start)]
    best = {start: 0}
    parent = {}
    found = None

    while open_heap:
        f, g, _, state = heapq.heappop(open_heap)
        if g != best.get(state):
            continue
        if state == goal_state:
            found = state
            break

        moves = []
        for b in range(n):
            s = state[b]
            if not is_clear(state, b):
                continue

            if s != TABLE:
                if not (state[b] == goal_state[b] and is_ready(state, b)):
                    moves.append((b, s, TABLE))

            d = goal_state[b]
            if d != TABLE and d != s:
                if is_clear(state, d) and is_ready(state, d):
                    moves.append((b, s, d))

        ordered = []
        for b, s, d in moves:
            lst = list(state)
            lst[b] = d
            ns = tuple(lst)
            if ns == state:
                continue
            nh = heuristic(ns)
            ordered.append((g + 1 + nh, nh, b, s, d, ns))
        ordered.sort()

        for _, _, b, s, d, ns in ordered:
            ng = g + 1
            if best.get(ns, 10**9) <= ng:
                continue
            best[ns] = ng
            parent[ns] = (state, (b, s, d))
            nh = heuristic(ns)
            heapq.heappush(open_heap, (ng + nh, ng, next(counter), ns))

    if found is None:
        print("No plan")
        return

    macros = []
    cur = found
    while cur != start:
        prev, action = parent[cur]
        macros.append(action)
        cur = prev
    macros.reverse()

    actions = []
    actions.append(("pickup", names[first]))
    actions.append(("putdown", names[first]))

    for b, s, d in macros:
        if s == TABLE:
            actions.append(("pickup", names[b]))
        else:
            actions.append(("unstack", names[b], names[s]))

        if d == TABLE:
            actions.append(("putdown", names[b]))
        else:
            actions.append(("stack", names[b], names[d]))

    def plan_is_valid(actions):
        if not actions:
            return False
        if actions[0] != ("pickup", names[first]):
            return False

        state = list(start)
        held = None

        for act in actions:
            if len(act) == 2:
                a, bname = act
                b = idx[bname]

                if a == "pickup":
                    if held is not None:
                        return False
                    if state[b] != TABLE:
                        return False
                    if not is_clear(state, b):
                        return False
                    state[b] = -2
                    held = b

                elif a == "putdown":
                    if held != b:
                        return False
                    if state[b] != -2:
                        return False
                    state[b] = TABLE
                    held = None

                else:
                    return False

            elif len(act) == 3:
                a, bname, cname = act
                b = idx[bname]
                c = idx[cname]

                if a == "unstack":
                    if held is not None:
                        return False
                    if state[b] != c:
                        return False
                    if state[c] == -2:
                        return False
                    if not is_clear(state, b):
                        return False
                    state[b] = -2
                    held = b

                elif a == "stack":
                    if held != b:
                        return False
                    if state[b] != -2:
                        return False
                    if state[c] == -2:
                        return False
                    if not is_clear(state, c):
                        return False
                    state[b] = c
                    held = None

                else:
                    return False

            else:
                return False

        if held is not None:
            return False
        return tuple(state) == goal_state

    if not plan_is_valid(actions):
        print("No plan")
        return

    out = []
    for act in actions:
        if len(act) == 2:
            out.append(f"({act[0]} {act[1]})")
        else:
            out.append(f"({act[0]} {act[1]} {act[2]})")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

import sys


def main():
    blocks = tuple(range(1, 13))

    initial_stacks = [
        (9, 2, 1, 6),
        (7, 5),
        (10, 4, 3, 12, 8, 11),
    ]

    on_table = frozenset(stack[0] for stack in initial_stacks)
    on_top = frozenset(
        (stack[i + 1], stack[i])
        for stack in initial_stacks
        for i in range(len(stack) - 1)
    )

    state = (on_table, on_top, 0)
    plan = []

    def block_name(b):
        return f"block{b}"

    def is_clear(st, b):
        _, on_top_set, holding = st
        if b == holding:
            return True
        return all(y != b for _, y in on_top_set)

    def support(st, b):
        on_table_set, on_top_set, holding = st
        if b == holding:
            return "arm"
        if b in on_table_set:
            return "table"
        for x, y in on_top_set:
            if x == b:
                return y
        return None

    def transition(st, action, *args):
        on_table_set, on_top_set, holding = st

        if action == "pickup":
            b = args[0]
            if holding != 0 or b not in on_table_set or not is_clear(st, b):
                return None
            return (on_table_set - {b}, on_top_set, b)

        if action == "putdown":
            b = args[0]
            if holding != b:
                return None
            return (on_table_set | {b}, on_top_set, 0)

        if action == "unstack":
            x, y = args
            if holding != 0 or (x, y) not in on_top_set or not is_clear(st, x):
                return None
            return (on_table_set, on_top_set - {(x, y)}, x)

        if action == "stack":
            x, y = args
            if holding != x or x == y or not is_clear(st, y):
                return None
            return (on_table_set, on_top_set | {(x, y)}, 0)

        return None

    def execute(action, *args):
        nonlocal state
        ns = transition(state, action, *args)
        if ns is None:
            return False
        state = ns
        if len(args) == 1:
            plan.append(f"({action} {block_name(args[0])})")
        else:
            plan.append(f"({action} " + " ".join(block_name(a) for a in args) + ")")
        return True

    while True:
        if state[2] != 0:
            if not execute("putdown", state[2]):
                print("No plan")
                return

        on_table_set, _, holding = state
        candidate = None
        for b in blocks:
            if b != holding and b not in on_table_set and is_clear(state, b):
                candidate = b
                break

        if candidate is None:
            break

        y = None
        for x, sup in state[1]:
            if x == candidate:
                y = sup
                break

        if y is None:
            print("No plan")
            return

        if not execute("unstack", candidate, y):
            print("No plan")
            return
        if not execute("putdown", candidate):
            print("No plan")
            return

    goal_support = {b: "table" for b in (9, 12, 10, 5, 6, 7, 2, 3, 4, 8)}
    goal_support[11] = 5
    goal_support[1] = 4

    for b in blocks:
        if b not in goal_support:
            print("No plan")
            return
        s = goal_support[b]
        if s != "table" and s not in blocks:
            print("No plan")
            return

    above = {}
    for b, s in goal_support.items():
        if s != "table":
            if s in above:
                print("No plan")
                return
            above[s] = b

    def depth(b, seen=None):
        if seen is None:
            seen = set()
        if b in seen:
            return None
        seen.add(b)
        s = goal_support[b]
        if s == "table":
            return 0
        d = depth(s, seen)
        if d is None:
            return None
        return d + 1

    depths = {}
    for b in blocks:
        d = depth(b)
        if d is None:
            print("No plan")
            return
        depths[b] = d

    to_place = [b for b in blocks if goal_support[b] != "table"]
    to_place.sort(key=lambda b: (depths[b], b))

    for b in to_place:
        y = goal_support[b]
        if not execute("pickup", b):
            print("No plan")
            return
        if not execute("stack", b, y):
            print("No plan")
            return

    if state[2] != 0:
        print("No plan")
        return

    for b in blocks:
        if support(state, b) != goal_support[b]:
            print("No plan")
            return

    sys.stdout.write("\n".join(plan))
    if plan:
        sys.stdout.write("\n")


if __name__ == "__main__":
    main()
